window.POEM_DB=window.POEM_DB||{};POEM_DB["song_009"]={"n":"黄庭坚","dyn":"宋","poems":[{"t":"次韵文安国纪梦","f":"七言律诗","c":["道人偶许俗人知，法喜非妻解养儿。","夜久金茎添沆瀣，室虚璧月映琉璃。","远来醉侠匆匆去，近出诗仙句句奇。","独怪区区践绳墨，相逢未省角巾敧。"]},{"t":"谢公定和二范秋怀五首邀予同作 其一","f":"五言律诗","c":["西风一叶脱，迹亦不可扫。","巷有白马生，朝回焚谏草。","谁云事君难，是亦父子间。","所要功补衮，不言能犯颜。"]},{"t":"白鹤观","f":"七言律诗","c":["复殿重楼堕杳冥，故基乔木尚峥嵘。","银河不改三千尺，铁马曾经十万兵。","华表故应终化鹤，谪仙未解独骑鲸。","林泉一二儿童旧，白发衰颜只自惊。"]},{"t":"一夕风雨花药都尽唯有豨莶一丛濯濯得意戏题","f":"七言绝句","c":["红药山丹逐晓风，春荣分到豨莶丛。","朱颜颇欲辞镜去，煮叶掘根傥见功。"]},{"t":"九日对菊有怀粹老在河上四首 其四","f":"七言绝句","c":["碧窗闲杀春风手，古柳堤莺几日回。","纵有黄花堪对酒，应无红袖与传杯。"]},{"t":"九日对菊有怀粹老在河上四首 其三","f":"七言绝句","c":["忆得旧时重九日，紫萸黄菊压梳钗。","寒花有意催垂泪，喜鹊无端屡下阶。"]},{"t":"九日对菊有怀粹老在河上四首 其二","f":"七言绝句","c":["黄花节晚犹可惜，青眼故人殊未来。","金蕊飞觞无计共，香钿满地始应回。"]},{"t":"九日对菊有怀粹老在河上四首 其一","f":"七言绝句","c":["月邀棋约屡登台，学省公厅只对街。","九日菊花孤痛饮，百端人事可安排。"]},{"t":"入穷巷谒李材叟翘叟戏赠兼简田子平三首 其三","f":"七言绝句","c":["田郎杞菊荒三径，文字时追二叟游。","万卷藏书多未见，老夫端拟乞荆州。"]},{"t":"入穷巷谒李材叟翘叟戏赠兼简田子平三首 其二","f":"七言绝句","c":["只可阕中安止止，谁能铁里斗铮铮。","田多谷少无人会，譬似无田过一生。"]},{"t":"入穷巷谒李材叟翘叟戏赠兼简田子平三首 其一","f":"七言绝句","c":["紫冠黄钿网丝窠，蝶绕蜂围奈晚何。","二叟家居如避世，开门自少俗人过。"]},{"t":"几道复觅槟榔","f":"七言绝句","c":["蛮烟雨里红千树，逐水排痰肘后方。","莫笑忍饥穷县令，烦君一斛寄槟榔。"]},{"t":"十月十五早饭清都观逍遥堂","f":"七言绝句","c":["心游魏阙鱼千里，梦觉邯郸黍一炊。","蔬食菜羹吾亦饱，逍遥堂下叶辞枝。"]},{"t":"十四弟归洪州赋莫如兄弟四章赠行 其一","f":"五言绝句","c":["恼人自作乐，休休莫莫莫。","相看将白头，止有不如昨。"]},{"t":"十四弟归洪州赋莫如兄弟四章赠行 其三","f":"五言绝句","c":["志欲收九族，别离乃同生。","谁能成此意，惟有孔方兄。"]},{"t":"又戏为双井解嘲","f":"七言绝句","c":["山芽落硙风回雪，曾为尚书破睡来。","勿以姬姜弃蕉萃，逢时瓦釜亦鸣雷。"]},{"t":"又戏呈康国","f":"七言绝句","c":["整冠行客莫先尝，杨子家无数仞墙。","假借肃霜令弄色，勾添寒日与争黄。"]},{"t":"又戏题下岩","f":"七言绝句","c":["往往携家来托宿，裙襦参错佛衣巾。","未嫌满院油头臭，蹋破苔钱最恼人。"]},{"t":"又借前韵见意","f":"七言绝句","c":["招潮瘦恶无永味，海镜纤毫只强颜。","想见霜脐当大嚼，梦回雪压摩围山。"]},{"t":"又寄王立之","f":"七言绝句","c":["南人羁旅不成归，梦绕南枝与北枝。","安得孤根连夜发，要当雪月群明时。"]},{"t":"又答寄糖霜颂","f":"七言绝句","c":["远寄蔗霜知有味，胜于崔浩水精盐。","正宗扫地从谁说，我舌犹能及鼻尖。"]},{"t":"万州太守高仲本宿约游岑公洞而夜雨连明戏作二首 其二","f":"七言绝句","c":["蓬窗高卧雨如绳，恰似糟床压酒声。","今日岑公不能饮，吾侪闻健且频倾。"]},{"t":"上萧家峡","f":"七言绝句","c":["玉笥峰前几百家，山明松雪水明沙。","趁虚人集春蔬好，桑菌竹萌烟蕨芽。"]},{"t":"与李公择道中见两客布衣班荆而坐对戏弈秋因作一绝","f":"七言绝句","c":["两客班荆覆局图，看人车马溷泥涂。","文昌八座邻枢极，天上归来愧不如。"]},{"t":"乞姚花二首 其二","f":"七言绝句","c":["青春日月鸟飞过，汗简文书山叠重。","乞取好花天上看，宫衣黄带御炉烘。"]},{"t":"乞姚花二首 其一","f":"七言绝句","c":["正是风光懒困时，姚黄开晚落应迟。","欲雕好句乞春色，日历如山不到诗。"]},{"t":"乞猫","f":"七言绝句","c":["秋来鼠辈欺猫死，窥瓮翻盘搅夜眠。","闻道狸奴将数子，买鱼穿柳聘衔蝉。"]},{"t":"大风","f":"七言绝句","c":["霜重天高日色微，颠狂红叶上阶飞。","北风不惜江南客，更入破窗吹客衣。"]},{"t":"大暑水阁听晋卿家昭华吹笛","f":"七言绝句","c":["蕲竹能吟水底龙，玉人应在月明中。","何时为洗秋空热，散作霜天落叶风。"]},{"t":"子产庙","f":"七言绝句","c":["区区小郑多君子，谁若公孙用意深。","监巫执节诛腹诽，不除乡校独何心。"]},{"t":"子瞻去岁春侍立迩英子由秋冬间相继入侍作诗各述所怀予亦次韵四首 其四","f":"七言绝句","c":["乐天名位聊相似，却是初无富贵心。","只欠小蛮樊素在，我知造物爱公深。"]},{"t":"子瞻去岁春侍立迩英子由秋冬间相继入侍作诗各述所怀予亦次韵四首 其三","f":"七言绝句","c":["封掌丝纶罢记言，职亲黄屋傍尧轩。","雁行飞上犹回首，不受青云富贵吞。"]},{"t":"子瞻去岁春侍立迩英子由秋冬间相继入侍作诗各述所怀予亦次韵四首 其一","f":"七言绝句","c":["赤壁归来入紫清，堂堂心在鬓彫零。","江沙踏破青鞋底，却结丝絇侍禁庭。"]},{"t":"子瞻去岁春侍立迩英子由秋冬间相继入侍作诗各述所怀予亦次韵四首 其二","f":"七言绝句","c":["胸蟠万卷夜光寒，笔倒三江砚滴乾。","大似不蒙稽古力，只今犹著侍臣冠。"]},{"t":"小鸭","f":"七言绝句","c":["小鸭看从笔下生，幻法生机全得妙。","自知力小畏沧波，睡起晴沙依晚照。"]},{"t":"为黄龙心禅师烧香颂三首 其三","f":"七言绝句","c":["海风吹落楞伽山，四海山徒著眼看。","一把柳丝收不得，和风搭在玉阑干。"]},{"t":"为慧林冲禅师烧香颂三首 其二","f":"七言绝句","c":["多年破衲不胜针，一曲胡笳无古今。","往日闻韶独忘味，守株人在月西沈。"]},{"t":"书王氏梦锡扇","f":"七言绝句","c":["压枝梅子大于钱，惭愧春光又一年。","亭午无人初破睡，杜鹃啼在柳梢边。"]},{"t":"书扇","f":"七言绝句","c":["鲁公笔法屋漏雨，未减右军锥画沙。","可惜团团新月面，故教零乱黑云遮。"]},{"t":"书舞阳西寺旧题处","f":"七言绝句","c":["万事纷纷日日新，当时题壁是前身。","寺僧物色来相访，我似昔人非昔人。"]},{"t":"书蔡秀才屏风颂四首 其四","f":"七言绝句","c":["读经一字礼一拜，瘦骨棱棱心苦辛。","看伊冷淡教人笑，定作阎浮百岁人。"]},{"t":"予去岁在长沙数与处度元实相从把酒自过岭来不复有此乐感叹之馀戏成一绝","f":"七言绝句","c":["玄霜捣尽音尘绝，去作湖南万里春。","想见山川佳绝地，落花飞絮转愁人。"]},{"t":"今岁官茶极妙而难为赏音者戏作两诗用前韵 其二","f":"七言绝句","c":["乳花翻椀正眉开，时苦渴羌冲热来。","知味者谁心已许，维摩虽默语如雷。"]},{"t":"今岁官茶极妙而难为赏音者戏作两诗用前韵 其一","f":"七言绝句","c":["鸡苏狗虱难同味，怀取君恩归去来。","青箬湖边寻顾陆，白莲社里觅宗雷。"]},{"t":"从人求花","f":"七言绝句","c":["舍南舍北勃姑啼，体中不佳阴雨垂。","欲向黄梅问消息，背阴合有两三枝。"]},{"t":"从张仲谋乞蜡梅","f":"七言绝句","c":["闻君寺后野梅发，香蜜染成宫样黄。","不拟折来遮老眼，欲知春色到池塘。"]},{"t":"从时中乞蒲团","f":"七言绝句","c":["扑屋阴风雪作团，织蒲投我最宜寒。","君当自致青云上，快取金狨覆马鞍。"]},{"t":"从时中乞蒲团","f":"七言绝句","c":["织蒲投我最宜寒，正欲阴风雪作团。","方竹火炉趺坐稳，何如矍铄跨征鞍。"]},{"t":"从舅氏李公择将抵京辅以归江南初自淮之西犹未秋日思归","f":"七言绝句","c":["归心摇摇若鞦带，哀操切切如蝉吟。","百年双鬓欲俱白，千里一书真万金。"]},{"t":"仓后酒正厅昔唐林夫谪官所作十一月己卯余纳秋租隔墙芙蓉盛开","f":"七言绝句","c":["攀槛朱云头未白，不知流落向何州。","空馀前日学书地，小阁红蕖取意秋。"]},{"t":"以天坛灵寿杖送莘老","f":"七言绝句","c":["王屋千霜老紫藤，扶公休沐对亲朋。","异时驷马安车去，拄到天坛愿力能。"]},{"t":"以虎臂杖送李任道二首 其二","f":"七言绝句","c":["未衰筋力先扶杖，能救衰年十二三。","八百老彭嗟杖晚，可怜矍铄马征南。"]},{"t":"以虎臂杖送李任道二首 其一","f":"七言绝句","c":["走送书堂倚绛纱，瘦藤七尺走惊蛇。","晴沙每要交头拄，寻遍渔翁野老家。"]},{"t":"以金沙酴醾送公寿","f":"七言绝句","c":["天遣酴醾玉作花，紫绵揉色染金沙。","凭君著意樽前看，便与春工立等差。"]},{"t":"以梅馈晁深道戏赠二首 其二","f":"七言绝句","c":["渴梦吞江起解颜，诗成有味齿牙间。","前身邺下刘公干，今日江南庾子山。"]},{"t":"以梅馈晁深道戏赠二首 其一","f":"七言绝句","c":["带叶连枝摘未残，依依茶坞竹篱间。","相如病渴应须此，莫与文君蹙远山。"]},{"t":"以椰子小冠送子予","f":"七言绝句","c":["浆成乳酒醺人醉，肉截鹅肪上客盘。","有核如匏可彫琢，道装宜作玉人冠。"]},{"t":"以潞公所惠拣芽送公择次旧韵","f":"七言绝句","c":["庆云十六升龙样，国老元年密赐来。","披拂龙纹射牛斗，外家英鉴似张雷。"]},{"t":"公择用前韵嘲戏双井","f":"七言绝句","c":["万仞峰前双井坞，婆娑曾占早春来。","如今摸索苍龙璧，沈井铜瓶漫学雷。"]},{"t":"公益尝茶","f":"七言绝句","c":["子云窗下草玄经，寒雀争喧户昼扃。","好事应无携酒榼，相过聊欲煮茶瓶。"]},{"t":"六月十七日昼寝","f":"七言绝句","c":["红尘席帽乌韡里，想见沧洲白鸟双。","马龁枯萁喧午枕，梦成风雨浪翻江。"]},{"t":"双涧寺二首 其二","f":"七言绝句","c":["山陕江深屋翠崖，夜钟声自瓮中来。","长松偃蹇苍龙卧，六月涧泉轰怒雷。"]},{"t":"双涧寺二首 其一","f":"七言绝句","c":["二水奔奔鸣屋除，松林落日吼乌菟。","老僧更有百岁母，白发身为反哺乌。"]},{"t":"太平州作二首 其二","f":"七言绝句","c":["千古人心指下传，杨姝烟月过年年。","不知心向谁边切，弹尽松风欲断弦。"]},{"t":"太平州作二首 其一","f":"七言绝句","c":["欧靓腰支柳一涡，小梅催拍大梅歌。","舞馀片片梨花雨，奈此当涂风月何。"]},{"t":"忆邢惇夫","f":"七言绝句","c":["诗到随州更老成，江山为助笔纵横。","眼看白璧埋黄壤，何况人间父子情。"]},{"t":"木龟亭留题","f":"七言绝句","c":["南台西路木龟坊，乃是灵蛙赑屃藏。","从此改名杉蚵蚾，恐来吞月直须防。"]},{"t":"王才元舍人许牡丹求诗","f":"七言绝句","c":["闻道潜溪千叶紫，主人不剪要题诗。","欲搜佳句恐春老，试遣七言赊一枝。"]},{"t":"王立之以小诗送并蒂牡丹戏答二首 其二","f":"七言绝句","c":["露晞风晚别春丛，拂掠残妆可意红。","多病废诗仍止酒，可怜虽在与谁同。"]},{"t":"王立之以小诗送并蒂牡丹戏答二首 其一","f":"七言绝句","c":["分送香红惜折残，春阴醉起薄罗寒。","不如王谢堂前燕，曾见新妆并倚栏。"]},{"t":"王立之承奉诗报梅花已落尽次韵戏答","f":"七言绝句","c":["南枝北枝春事休，榆钱可穿柳带柔。","定是沈郎作诗瘦，不应春能生许愁。"]},{"t":"王厚颂二首 其二","f":"七言绝句","c":["夕阳尽处望清闲，想见千岩细菊斑。","人得交游是风月，天开图画即江山。"]},{"t":"王厚颂二首 其一","f":"七言绝句","c":["八风动摇人不闲，五羖自鬻鬓毛斑。","文章书画当富贵，惟有如今至乐山。"]},{"t":"见二十弟倡和花字漫兴五首 其五","f":"七言绝句","c":["池面白鱼吹落絮，□□□□退枯花。","无因光禄赐官酒，且学潞公灌蜀茶。"]},{"t":"见二十弟倡和花字漫兴五首 其四","f":"七言绝句","c":["邺城也似洛城阔，□□园林学养花。","欲把一樽随饮处，□□处处锁官茶。"]},{"t":"见二十弟倡和花字漫兴五首 其三","f":"七言绝句","c":["睡起草玄三亩宅，无人载酒眼昏花。","不知谁劝路门讲，天上日长坐赐茶。"]},{"t":"见二十弟倡和花字漫兴五首 其二","f":"七言绝句","c":["官驼鸣铎逐盐车，只见风尘不见花。","空作江南江北梦，辛夷踯躅倚山茶。"]},{"t":"见二十弟倡和花字漫兴五首 其一","f":"七言绝句","c":["落絮游丝三月候，风吹雨洗一城花。","未知东郭清明酒，何似西窗谷雨茶。"]},{"t":"长沙留别","f":"七言绝句","c":["折脚铛中同淡粥，曲腰桑下把离杯。","知君不是南迁客，魑魅无情须早回。"]},{"t":"世弼病方家不善论蛤蜊之功戏答","f":"七言绝句","c":["伯乐无传骥空老，重华不见士长饥。","从来万事乖名实，岂但药翁论蛤蜊。"]},{"t":"东林寺二首 其二","f":"七言绝句","c":["胜地东林十八公，庐山千古一清风。","渊明岂是难拘束，正与白莲出处同。"]},{"t":"东林寺二首 其一","f":"七言绝句","c":["白莲种出净无尘，千古风流社里人。","禅律定知谁束缚，过溪沽酒见天真。"]},{"t":"东禅长老梦偈","f":"七言绝句","c":["伐木丁丁斧下鸣，隔溪便应谷中声。","不因蘋末微风起，漂影溪光本自明。"]},{"t":"代二螯解嘲","f":"七言绝句","c":["仙儒昔日卷龟壳，蛤蜊自可洗愁颜。","不比二螯风味好，那堪把酒对西山。"]},{"t":"出礼部试院王才元惠梅花三种皆妙绝戏答三首 其三","f":"七言绝句","c":["病夫中岁屏杯杓，百叶缃梅触拨人。","拂杀官黄春有思，满城桃李不能春。"]},{"t":"出礼部试院王才元惠梅花三种皆妙绝戏答三首 其二","f":"七言绝句","c":["舍人梅坞无关锁，携酒俗人来未曾。","旧时爱菊陶彭泽，今作梅花树下僧。"]},{"t":"出礼部试院王才元惠梅花三种皆妙绝戏答三首 其一","f":"七言绝句","c":["城南名士遣春来，三月乃见腊前梅。","定知锁著江南客，故放绿阴春晚回。"]},{"t":"北园步折梅寄君庸","f":"七言绝句","c":["林中破笑派雪雨，不著世间笑粉尘。","覆入晓风香满袖，无人同咏一枝春。"]},{"t":"史彦升送春花","f":"七言绝句","c":["千林摇落照秋空，忽散秾花在眼中。","蝶绕蜂随俱入座，君家女手化春风。"]},{"t":"四休居士诗三首 其一","f":"七言绝句","c":["富贵何时润髑髅，守钱奴与拘官囚。","太医诊得人间病，安乐延年万事休。"]},{"t":"宁子与追和予岳阳楼诗复次韵二首 其二","f":"七言绝句","c":["轩皇乐罢拱朝班，天地为家不闭关。","惟有金炉紫烟起，至今留作御前山。"]},{"t":"宁子与追和予岳阳楼诗复次韵二首 其一","f":"七言绝句","c":["去年新霁独凭栏，山似樊姬拥髻鬟。","个里宛然多事在，世间遥望但云山。"]},{"t":"平原郡斋二首 其二","f":"七言绝句","c":["成巢不处避岁鹊，得巢不安呼妇鸠。","金钱满地无人费，一斛明珠薏苡秋。"]},{"t":"平原郡斋二首 其一","f":"七言绝句","c":["生平浪学不知株，江北江南去荷锄。","窗风文字翻叶叶，犹似劝人勤读书。"]},{"t":"平原宴坐二首 其二","f":"七言绝句","c":["黄落委庭观九州，虫声日夜戒衣裘。","金钱满地无人费，一斛明珠薏苡秋。"]},{"t":"平原宴坐二首 其一","f":"七言绝句","c":["老作儒生不解事，江南有田归荷锄。","北窗风来举书叶，犹似劝人勤读书。"]},{"t":"玉笥山","f":"七言绝句","c":["上天下地似探梯，怪石巉岩衬马蹄。","拟是客程行不得，隔林犹听杜鹃啼。"]},{"t":"用前韵戏公静","f":"七言绝句","c":["偶逢携酒便与饮，竟别我为何等人。","兔月龙团不当惜，长卿消渴肺生尘。"]},{"t":"立春","f":"五言绝句","c":["韭苗香煮饼，野老不知春。","看镜道如咫，倚楼梅照人。"]},{"t":"再次前韵 其一","f":"七言绝句","c":["春工调物似盐梅，一一根中生意回。","风日安排催岁换，丹青次第与花开。"]},{"t":"再次前韵 其三","f":"七言绝句","c":["酒有全功笔有神，可将心付白头新。","春盘一任人争席，莫道前衔是近臣。"]},{"t":"再次韵四首 其四","f":"七言绝句","c":["延和西路古槐阴，不隔朝宗夙夜心。","公有胸中五色线，平生补衮用功深。"]},{"t":"再次韵四首 其三","f":"七言绝句","c":["万国归心天不言，诸儒争席异临轩。","圣功典学形歌颂，更觉曹刘不足吞。"]},{"t":"再次韵四首 其二","f":"七言绝句","c":["风棂倒影日光寒，尧日当中露正乾。","殿上给扶鸣汉履，螭头簪笔见秦冠。"]},{"t":"再次韵四首 其一","f":"七言绝句","c":["隆儒殿阁对横经，咫尺清都雨露零。","见说文星环北极，人间无路仰天庭。"]},{"t":"再次韵答吉老二首 其二","f":"七言绝句","c":["贤劳王事一归休，霜落园林失九秋。","想得君家乌鹊喜，蛛丝萦绕玉搔头。"]},{"t":"再次韵答吉老二首 其一","f":"七言绝句","c":["水宿风餐甚劳苦，勉旃吾子富春秋。","我愧疲民欲归去，麦田春雨把锄头。"]},{"t":"再和元礼春怀十首 其十","f":"七言绝句","c":["滞梦停愁乱性灵，安眠灭念闭幽扃。","体中忽觉有佳处，读易一篇如酒醒。"]},{"t":"再和元礼春怀十首 其九","f":"七言绝句","c":["双盘锦带丁香结，窄袖春衫甘草黄。","旧赠恐能开宝匣，新年时候梦残妆。"]},{"t":"再和元礼春怀十首 其八","f":"七言绝句","c":["风光琰琰动春华，回首烟波万里赊。","山似翠屏西子国，溪如罨画越王家。"]},{"t":"再和元礼春怀十首 其七","f":"七言绝句","c":["雨馀花色倍鲜明，最是春深多晚晴。","美酒壮人如敌国，千金一笑买倾城。"]},{"t":"再和元礼春怀十首 其六","f":"七言绝句","c":["玉壶耽耽浸晴霞，庭有三春接续花。","准拟只无难白发，金炉谁为煮黄芽。"]},{"t":"再和元礼春怀十首 其五","f":"七言绝句","c":["抹裙彩凤盘宫锦，插鬓真珠络贝多。","酒恶花愁梦多魇，灵砂犀角费频魔。"]},{"t":"再和元礼春怀十首 其四","f":"七言绝句","c":["红紫欲疏啼百劳，洞宫春色醉蟠桃。","虚窗酒病扶头起，强取金钗痒处搔。"]},{"t":"再和元礼春怀十首 其三","f":"七言绝句","c":["行云行雨迷三峡，归凤求凰振九苞。","月白花红倾酒满，不将春色等闲抛。"]},{"t":"再和元礼春怀十首 其二","f":"七言绝句","c":["吴中风物最娇饶，百里春风酒旆摇。","往往贵人留骑从，少年丛里贳金貂。"]},{"t":"再和元礼春怀十首 其一","f":"七言绝句","c":["回肠无奈别愁煎，待得鸾胶续断弦。","最忆钱塘风物苦，西湖月落采菱船。"]},{"t":"再答并简康国兄弟四首 其四","f":"七言绝句","c":["日中一饭蒙头睡，黄叶堆门莫扫除。","夜半枕前师子吼，起来烧却野狐书。"]},{"t":"再答并简康国兄弟四首 其三","f":"七言绝句","c":["须弥椎打虚空鼓，撼得毗卢海月昏。","四海无波安乐住，陈家松下小柴门。"]},{"t":"再答并简康国兄弟四首 其二","f":"七言绝句","c":["妙舌寒山一居士，净居金粟几如来。","玄关无键直须透，不得春风花不开。"]},{"t":"再答并简康国兄弟四首 其一","f":"七言绝句","c":["瞿昙不解祖师机，却许狸奴白牯知。","道人只要贫到骨，沈却黄金卖笊离。"]},{"t":"再答静翁并以筇竹一枝赠行四首 其四","f":"七言绝句","c":["万事实头方稳当，十分足陌莫跷除。","困来展席日里睡，读尽空中鸟迹书。"]},{"t":"再答静翁并以筇竹一枝赠行四首 其三","f":"七言绝句","c":["一筇九节添行李，用得人间处处尊。","只要上山行饱饭，莫将风雪打人门。"]},{"t":"再答静翁并以筇竹一枝赠行四首 其二","f":"七言绝句","c":["栽松道者身先老，放下锄头好再来。","八万四千关捩子，与公一个锁匙开。"]},{"t":"再答静翁并以筇竹一枝赠行四首 其一","f":"七言绝句","c":["南鸿北雁年年客，有个生涯主不知。","撼动从来忧乐事，夜窗风叶响棠梨。"]},{"t":"刘邦直送早梅水仙花四首 其四","f":"七言绝句","c":["钱塘昔闻水仙庙，荆州今见水仙花。","暗香静色撩诗句，宜在林逋处士家。"]},{"t":"刘邦直送早梅水仙花四首 其三","f":"七言绝句","c":["得水能仙天与奇，寒香寂寞动冰肌。","仙风道骨今谁有，淡扫蛾眉簪一枝。"]},{"t":"刘邦直送早梅水仙花四首 其二","f":"七言绝句","c":["探请东皇第一机，水边风日笑横枝。","鸳鸯浮弄婵娟影，白鹭窥鱼凝不知。"]},{"t":"刘邦直送早梅水仙花四首 其一","f":"七言绝句","c":["簸船綪缆北风嗔，霜落千林憔悴人。","欲问江南近消息，喜君贻我一枝春。"]},{"t":"压沙寺梨花","f":"七言绝句","c":["压沙寺后千株雪，长乐坊前十里香。","寄语春风莫吹尽，夜深留与雪争光。"]},{"t":"吊死心禅师偈","f":"七言绝句","c":["海风吹落楞伽山，四海禅徒著眼看。","一把柳丝收不得，和烟搭在玉栏干。"]},{"t":"同元明过洪福寺戏题","f":"七言绝句","c":["洪福僧园拂绀纱，旧题尘壁似昏鸦。","春残已是风和雨，更著游人撼落花。"]},{"t":"同刘景文游郭氏西园因留宿","f":"七言绝句","c":["人居城市虚华馆，秋入园林著晚花。","落日临池见蝌斗，必知清夜有鸣蛙。"]},{"t":"同景文丈咏莲塘","f":"七言绝句","c":["塘上钩帘对晚香，半斜红日已侵床。","江妃羞出凌波袜，长在高荷扇影凉。"]},{"t":"同谢公定携书浴室院汶师置饭作此","f":"七言绝句","c":["竹林风与日俱斜，细草犹开一两花。","天上归来对书客，愧勤僧饭更煎茶。"]},{"t":"吏部苏尚书右选胡侍郎皆和鄙句次韵道谢","f":"七言绝句","c":["不待烹茶唤睡回，天官两宰和诗来。","清如接笕通春溜，快似挥刀斫怒雷。"]},{"t":"因六祖举太和山语而成颂贵此话大行","f":"五言绝句","c":["峨眉山中老，千颂自成集。","持问太和山，鹘臭当风立。"]},{"t":"寺斋睡起二首 其二","f":"七言绝句","c":["桃李无言一再风，黄鹂惟见绿葱葱。","人言九事八为律，傥有江船吾欲东。"]},{"t":"寺斋睡起二首 其一","f":"七言绝句","c":["小黠大痴螳捕蝉，有馀不足夔怜蚿。","退食归来北窗梦，一江风月桃李船。"]},{"t":"延寿寺见红药小魏扬州号为醉西施","f":"五言绝句","c":["醉红如堕珥，奈此恼人香。","政尔无言笑，未应吴国亡。"]},{"t":"戏呈闻善二兄","f":"七言绝句","c":["匏悬篱落鸦窥井，草上阶除雪衮风。","想得尊前攲醉帽，浑家儿女笑山公。"]},{"t":"戏和舍弟船场探春二首 其二","f":"七言绝句","c":["百舌解啼泥滑滑，忽成风雨落花天。","城南一段春如锦，唤取诗人到酒边。"]},{"t":"戏和舍弟船场探春二首 其一","f":"七言绝句","c":["雨馀禽语催天晓，月上梨花放夜阑。","莫听游人待妍暖，十分倾酒对春寒。"]},{"t":"戏咏高节亭边山矾花二首 其一","f":"七言绝句","c":["北岭山矾取意开，轻风正用此时来。","平生习气难料理，爱著幽香未拟回。"]},{"t":"戏咏高节亭边山矾花二首 其二","f":"七言绝句","c":["高节亭边竹已空，山矾独自倚春风。","二三名士开颜笑，把断花光水不通。"]},{"t":"戏咏猩猩毛笔二首 其二","f":"七言绝句","c":["明窗脱帽见蒙茸，醉著青鞋在眼中。","束缚归来傥无辱，逢时犹作黑头公。"]},{"t":"戏咏猩猩毛笔二首 其一","f":"七言绝句","c":["桄榔叶暗宾郎红，朋友相呼堕酒中。","正以多知巧言语，失身来作管城公。"]},{"t":"戏咏零陵李宗古居士家驯鹧鸪二首 其二","f":"七言绝句","c":["真人梦出大槐宫，万里苍梧一洗空。","终日忧兄行不得，鹧鸪应是鼻亭公。"]},{"t":"戏咏零陵李宗古居士家驯鹧鸪二首 其一","f":"七言绝句","c":["山雌之弟竹鸡兄，乍入雕笼便不惊。","此鸟为公行不得，报晴报雨总同声。"]},{"t":"戏咏蜡梅二首 其二","f":"五言绝句","c":["体薰山麝脐，色染蔷薇露。","披拂不满襟，时有暗香度。"]},{"t":"戏咏蜡梅二首 其一","f":"五言绝句","c":["金蓓锁春寒，恼人香未展。","虽无桃李颜，风味极不浅。"]},{"t":"戏招饮客解酲","f":"七言绝句","c":["破卯扶头把一杯，灯前风味唤仍回。","高阳社里如相访，不用闲携恶客来。"]},{"t":"戏答仇梦得承制二首 其二","f":"七言绝句","c":["横槊不为万骑先，传杯把笔过年年。","怀中黄石闲三略，道上青旗漫百篇。"]},{"t":"戏答仇梦得承制二首 其一","f":"七言绝句","c":["结发从征听鼓鼙，未曾一展胸中奇。","弯弓如月落霜雁，谁道将军能赋诗。"]},{"t":"戏答王子予送凌风菊二首 其二","f":"七言绝句","c":["王郎颇病金瓢酒，不耐寒花晚更芳。","瘦尽腰围怯风景，故来归我一枝香。"]},{"t":"戏答王子予送凌风菊二首 其一","f":"七言绝句","c":["病来孤负鸬鹚杓，禅板蒲团入眼中。","浪说閒居爱重九，黄花应笑白头翁。"]},{"t":"戏答王观复酴醾菊二首 其二","f":"七言绝句","c":["吕园未肯轻沽我，且寄田家砌下栽。","他日秋花媚重九，清香知自故人来。"]},{"t":"戏答王观复酴醾菊二首 其一","f":"七言绝句","c":["谁将陶令黄金菊，幻作酴醾白玉花。","小草真成有风味，东园添我老生涯。"]},{"t":"戏答王居士送文石","f":"七言绝句","c":["南极一星天九秋，自埋光景落江流。","是公至乐山中物，乞与衰翁似暗投。"]},{"t":"戏答史应之三首 其三","f":"七言绝句","c":["甑有轻尘釜有鱼，汉庭日日召严徐。","不嫌藜藿来同饭，更展芭蕉看学书。"]},{"t":"戏答史应之三首 其二","f":"七言绝句","c":["老莱有妇怀高义，不厌夫家苜蓿盘。","收得千金不龟药，短裙漂絖暮江寒。"]},{"t":"戏答史应之三首 其一","f":"七言绝句","c":["先生早擅屠龙学，袖有新硎不试刀。","岁晚亦无鸡可割，庖蛙煎鳝荐松醪。"]},{"t":"戏答龙泉余尉问禅二小诗 其一","f":"七言绝句","c":["重帘复幕锁蛾眉，银烛金荷醉舞衣。","长为扶头欠㪷酒，不关禅病减腰围。"]},{"t":"戏答龙泉余尉问禅二小诗 其二","f":"七言绝句","c":["翻头作尾掉枯藤，腊月花开更造冰。","何似清歌倚桃李，一炉沈水醉红灯。"]},{"t":"戏答张秘监馈羊","f":"七言绝句","c":["细肋柔毛饱卧沙，烦公遣骑送寒家。","忍令无罪充庖宰，留与儿童驾小车。"]},{"t":"戏答李子真河上见招来诗颇誇河上风物聊以当嘲云","f":"七言绝句","c":["浑浑旧水无新意，漫漫黄尘涴白鸥。","安得江湖忽当眼，卧听禽语信船流。"]},{"t":"戏答陈季常寄黄州山中连理松枝二首 其二","f":"七言绝句","c":["老松连枝亦偶然，红紫事退独参天。","金沙滩头锁子骨，不妨随俗暂婵娟。"]},{"t":"戏答陈季常寄黄州山中连理松枝二首 其一","f":"七言绝句","c":["故人折松寄千里，想听万壑风泉音。","谁言五鬣苍烟面，犹作人间儿女心。"]},{"t":"戏答荆州王充道烹茶四首 其四","f":"七言绝句","c":["龙焙东风鱼眼汤，个中即是白云乡。","更煎双井苍鹰爪，始耐落花春日长。"]},{"t":"戏答荆州王充道烹茶四首 其三","f":"七言绝句","c":["香从灵坚垄上发，味自白石源中生。","为公唤觉荆州梦，可待南柯一梦成。"]},{"t":"戏答荆州王充道烹茶四首 其二","f":"七言绝句","c":["茗椀难加酒椀醇，暂时扶起藉糟人。","何须忍垢不濯足，苦学梁州阴子春。"]},{"t":"戏答荆州王充道烹茶四首 其一","f":"七言绝句","c":["三径虽锄客自稀，醉乡安稳更何之。","老翁更把春风椀，灵府清寒要作诗。"]},{"t":"戏答晁深道乞消梅二首 其二","f":"七言绝句","c":["北客未尝眉自颦，南人誇说齿生津。","磨钱和蜜谁能许，去蒂供盐亦可人。"]},{"t":"戏答晁深道乞消梅二首 其一","f":"七言绝句","c":["青莎径里香未乾，黄鸟阴中实已团。","蒸豆作乌盐作白，属闻丹杏荐牙盘。"]},{"t":"戏答诸君追和予去年醉碧桃","f":"七言绝句","c":["当时倒著接䍦回，不但碧桃邀我来。","白蚁拨醅官酒满，紫绵揉色海棠开。"]},{"t":"戏题大年防禦芦雁","f":"七言绝句","c":["挥毫不作小池塘，芦荻江村落雁行。","虽有珠帘藏翡翠，不忘烟雨罩鸳鸯。"]},{"t":"戏题曾处善尉厅二首 其一 超然台","f":"七言绝句","c":["鸡埘啄雁如鴐鹅，万里天衢且一波。","宫锦络衫弓石八，与人同状不同科。"]},{"t":"戏赠元翁","f":"七言绝句","c":["从来五字弄珠玑，忍负僧床锁翠微。","传语风流三语掾，何时缀我百家衣。"]},{"t":"戏赠世弼用前韵","f":"七言绝句","c":["盗蹠人肝常自饱，首阳薇蕨向来饥。","谁能著意知许事，且为元长食蛤蜊。"]},{"t":"戏赠米元章二首 其二","f":"七言绝句","c":["我有玄晖古印章，印刓不忍与诸郎。","虎儿笔力能扛鼎，教字玄晖继阿章。"]},{"t":"戏赠米元章二首 其一","f":"七言绝句","c":["万里风帆水著天，麝煤鼠尾过年年。","沧江静夜虹贯月，定是米家书画船。"]},{"t":"朱道人下世","f":"七言绝句","c":["桑户居然同物化，青灯犹在读书檠。","身如陌上狂风过，心似夜来新月明。"]},{"t":"杂诗","f":"七言绝句","c":["迷时今日如前日，悟后今年似去年。","随食随衣随事办，谁知佛印祖师禅。"]},{"t":"杂诗","f":"七言绝句","c":["古风萧索不言归，贫贱交情富贵非。","世祖本无天下量，子陵何慕钓鱼矶。"]},{"t":"杂诗","f":"七言绝句","c":["迷情淡荡不知津，老却平生梦幻身。","满眼纷华心寂寞，长安市上酒家人。"]},{"t":"杂诗七首 其七","f":"七言绝句","c":["碧窗凉簟唯便睡，露井无尘荫绿槐。","梦入醉乡犹病渴，辘轳声到枕边来。"]},{"t":"杂诗七首 其六","f":"七言绝句","c":["古屋清寒雪未消，小窗晴日展芭蕉。","酸甘荔子尝春酒，更碾新芽荐菊苗。"]},{"t":"杂诗七首 其五","f":"七言绝句","c":["薰炉茶鼎偶然同，晴日鸦啼柿叶风。","万事尽还曲居士，百年常在大槐宫。"]},{"t":"杂诗七首 其四","f":"七言绝句","c":["少年不爱万金身，歌舞寻春愁送春。","满眼纷华心寂寞，长安市上酒家人。"]},{"t":"杂诗七首 其三","f":"七言绝句","c":["馆甥宫里叹才难，当日同朝听百官。","光武早知尧舜事，只今那得子陵滩。"]},{"t":"杂诗七首 其二","f":"七言绝句","c":["营巢燕燕几时休，在处成家春复秋。","岁岁自来还自去，主人无厌客无求。"]},{"t":"杂诗七首 其一","f":"七言绝句","c":["此身天地一蘧庐，世事消磨绿鬓疏。","毕竟几人真得鹿，不知终日梦为鱼。"]},{"t":"杂诗四首 其四","f":"七言绝句","c":["黄帝炼丹求子母，神农尝药辨君臣。","如何苦思形中事，忧患从来为有身。"]},{"t":"杂诗四首 其三","f":"七言绝句","c":["小德有为因有累，至神无用故无功。","须知广大精微处，不在存亡得失中。"]},{"t":"杂诗四首 其二","f":"七言绝句","c":["佛子身归乐国遥，至人神会碧天寥。","劫灰沈尽还生妄，但向平沙看海潮。"]},{"t":"杂诗四首 其一","f":"七言绝句","c":["扁舟江上未归身，明月清风作四邻。","观化悟来俱是妄，渐疏人事与天亲。"]},{"t":"次韵子瞻子由题憩寂图二首 其二","f":"七言绝句","c":["龙眠不似虎头痴，笔妙天机可并时。","苏仙漱墨作苍石，应解种花开此诗。"]},{"t":"次韵子瞻子由题憩寂图二首 其一","f":"七言绝句","c":["松寒风雨石骨瘦，法窟寂寥僧定时。","李侯有句不肯吐，淡墨写出无声诗。"]},{"t":"次韵子瞻送穆父二绝 其一","f":"七言绝句","c":["渺然今日望人材，每见紫芝眉宇开。","又触惠文江海去，快帆谁与挽令回。"]},{"t":"次韵子瞻送穆父二绝 其二","f":"七言绝句","c":["谪官犹得住蓬莱，抱牍人稀书卷开。","张敞怃眉应急召，董宣强项莫低回。"]},{"t":"次韵中玉水仙花二首 其二","f":"七言绝句","c":["淤泥解作白莲藕，粪壤能开黄玉花。","可惜国香天不管，随缘流落小民家。"]},{"t":"次韵中玉水仙花二首 其一","f":"七言绝句","c":["借水开花自一奇，水沈为骨玉为肌。","暗香已压酴醾倒，只比寒梅无好枝。"]},{"t":"次韵中玉早梅二首 其二","f":"七言绝句","c":["折得寒香不露机，小窗斜日两三枝。","罗帷翠幕深调护，已被游蜂圣得知。"]},{"t":"次韵中玉早梅二首 其一","f":"七言绝句","c":["梅蕊争先公不嗔，知公家有似梅人。","何时各得自由去，相逐扬州作好春。"]},{"t":"次韵元礼春怀十首 其十","f":"七言绝句","c":["闻道邻家有酒瓶，三更不卧叩柴扃。","我身便是鸱夷榼，肯学离骚要独醒。"]},{"t":"次韵元礼春怀十首 其九","f":"七言绝句","c":["冉冉光阴花柳场，红飘紫落便蔫黄。","都无畔岸随风去，却是游丝意思长。"]},{"t":"次韵元礼春怀十首 其八","f":"七言绝句","c":["老杜当年鬓发华，尚言春到酒须赊。","不堪诗思相料理，恼乱街头卖酒家。"]},{"t":"次韵元礼春怀十首 其七","f":"七言绝句","c":["穿花蹴踏千秋索，挑菜嬉游二月晴。","已被风光催我老，懒随儿辈绕春城。"]},{"t":"次韵元礼春怀十首 其六","f":"七言绝句","c":["春风也似江南早，梅与辛夷斗著花。","自是无言桃李晚，莫嗔榆柳更萌芽。"]},{"t":"次韵元礼春怀十首 其五","f":"七言绝句","c":["春来问字有谁过，颇觉闲销日月多。","醉里乾坤知酒圣，贫中风物似诗魔。"]},{"t":"次韵元礼春怀十首 其四","f":"七言绝句","c":["久无长者回车辙，仲蔚门墙映野蒿。","稍觉春衣生虮虱，南窗晴日照爬搔。"]},{"t":"次韵元礼春怀十首 其三","f":"七言绝句","c":["故园春色常年早，红紫知他破几苞。","压帽花枝如可折，折花手版直须抛。"]},{"t":"次韵元礼春怀十首 其二","f":"七言绝句","c":["春心分付酒杯销，勿为浮云妄动摇。","试觅金张池馆问，几人能插侍中貂。"]},{"t":"次韵元礼春怀十首 其一","f":"七言绝句","c":["渐老春心不可言，亦如琴意在无弦。","新花准拟千场醉，美酒经营一百船。"]},{"t":"次韵公择雨后","f":"七言绝句","c":["二圣勤民损膳羞，雨馀今见角田秋。","碧酒尚堪遮眼醉，红榴不解替人愁。"]},{"t":"次韵文潜立春日三绝句 其三","f":"七言绝句","c":["江山也似随春动，花柳真成触眼新。","清浊尽须归瓮蚁，吉凶更莫问波臣。"]},{"t":"次韵文潜立春日三绝句 其二","f":"七言绝句","c":["谁怜旧日青钱选，不立春风玉笋班。","传得黄州新句法，老夫端欲把降幡。"]},{"t":"次韵文潜立春日三绝句 其一","f":"七言绝句","c":["眇然今日望欧梅，已发黄州首更回。","试问淮南风月主，新年桃李为谁开。"]},{"t":"次韵王稚川客舍二首 其二","f":"七言绝句","c":["身如病鹤翅翎短，心似乱丝头绪多。","此曲朱门歌不得，湖南湖北竹枝歌。"]},{"t":"次韵王稚川客舍二首 其一","f":"七言绝句","c":["五更归梦常苦短，一寸客愁无奈多。","慈母每占乌鹊喜，家人应赋扊扅歌。"]},{"t":"次韵吉老十小诗 其十","f":"五言绝句","c":["学似斲轮扁，诗如饭颗山。","室中馀一剑，无气斗牛间。"]},{"t":"次韵吉老十小诗 其六","f":"五言绝句","c":["佳人斗南北，美酒玉东西。","梦鹿分真鹿，无鸡应木鸡。"]},{"t":"次韵吉老十小诗 其九","f":"五言绝句","c":["半菽一瓢饮，悬鹑百结衣。","萧条鬼不瞰，聊可与同归。"]},{"t":"次韵吉老十小诗 其二","f":"五言绝句","c":["万木霜摇落，山呈斧凿痕。","痴蝇思附尾，警鹤畏乘轩。"]},{"t":"次韵吉老十小诗 其三","f":"五言绝句","c":["日短循除庑，溪寒出臼科。","官居图画里，小鸭睡枯荷。"]},{"t":"次韵吉老十小诗 其一","f":"五言绝句","c":["什袭发硎刀，无名自贵高。","秋衣犹葛制，午饭厌溪毛。"]},{"t":"次韵吉老十小诗 其八","f":"五言绝句","c":["茵席絮剪茧，枕囊收决明。","南风入昼梦，起坐是松声。"]},{"t":"次韵吉老十小诗 其四","f":"五言绝句","c":["眼看人换世，手种木成阴。","藏拙无三窟，谈禅剧七禽。"]},{"t":"次韵吉老十小诗 其七","f":"五言绝句","c":["斲鼻昔常尔，绝弦知者稀。","无人与争长，惟有钓鱼矶。"]},{"t":"次韵向和卿行松滋县与邹天锡夜语南极亭二首 其二","f":"七言绝句","c":["冲风冲雨走七县，唯有白鸥盟未寒。","坐中更得江南客，开尽南窗借月看。"]},{"t":"次韵向和卿行松滋县与邹天锡夜语南极亭二首 其一","f":"七言绝句","c":["雪泥滑滑到山郭，提壶劝沽亦不恶。","林中解道不如归，家人应念思归乐。"]},{"t":"次韵李士雄子飞独游西园折牡丹忆弟子奇二首 其二","f":"七言绝句","c":["桃李阴中五兄弟，扶将白发共传杯。","风吹一雁忽南去，空得平安书信回。"]},{"t":"次韵李士雄子飞独游西园折牡丹忆弟子奇二首 其一","f":"七言绝句","c":["西园春色才桃李，蜂已成围蝶作团。","更欲开花比京洛，放教姚魏接山丹。"]},{"t":"再次韵杜仲观二绝 其一","f":"七言绝句","c":["短舞朱裙惬醉看，惜公官守隔江干。","遥怜得句无人赏，走马城东觅道安。"]},{"t":"再次韵杜仲观二绝 其二","f":"七言绝句","c":["诗家二杜见仍云，佳句风流照映人。","青眼向来同醉醒，白头相望不缁磷。"]},{"t":"次韵杨君全送春花","f":"七言绝句","c":["化工能斡大钧回，不得东君花不开。","谁道纤纤绿窗手，磨刀剪綵唤春来。"]},{"t":"次韵奉答南山禅师二颂兼呈琦上人 其二","f":"七言绝句","c":["南山四至分明也，一日元来十二时。","两个泥牛齐著力，矛头淅米剑头炊。"]},{"t":"次韵奉答南山禅师二颂兼呈琦上人 其一","f":"七言绝句","c":["鱼吼钟鸣索饭钱，牧牛耕种别人田。","淮师收得祖关在，一笛操江月满船。"]},{"t":"次韵徐文将至国门见寄二首 其二","f":"七言绝句","c":["千头剖蚌明珠熟，百尺垂丝鲙缕长。","柳下石门君有此，可能冲雪厌清凉。"]},{"t":"次韵徐文将至国门见寄二首 其一","f":"七言绝句","c":["槐催举子著花黄，来食邯郸道上粱。","便欲扫床悬麈尾，正愁喘月似灯光。"]},{"t":"次韵钱德循鹿苑滩舣舟有作","f":"七言绝句","c":["鹿苑滩头秋月明，使君辍棹爱江清。","尘埃一段思归路，已听荆州渔鼓鸣。"]},{"t":"次韵喜陈吉老还家二绝 其二","f":"七言绝句","c":["夜寒客枕多归梦，归得黄柑紫蔗秋。","小雨对谈挥麈尾，青灯分坐写蝇头。"]},{"t":"次韵喜陈吉老还家二绝 其一","f":"七言绝句","c":["公庭无事吏人休，垂箔寒厅对弈秋。","催织青笼篘白酒，竹炉煨栗煮鸡头。"]},{"t":"次韵游景叔闻洮河捷报寄诸将四首 其四","f":"七言绝句","c":["遥知一炬绝河津，生缚青宜不动尘。","付与山河印如斗，忍为鼠子腹心人。"]},{"t":"次韵游景叔闻洮河捷报寄诸将四首 其三","f":"七言绝句","c":["汉得洮州箭有神，斩关禽敌不逡巡。","将军快上屯田计，要纳降胡十万人。"]},{"t":"次韵游景叔闻洮河捷报寄诸将四首 其二","f":"七言绝句","c":["中原日月九夷知，不用禽胡衅鼓旗。","更向天阶舞干羽，降书剩破一年迟。"]},{"t":"次韵游景叔闻洮河捷报寄诸将四首 其一","f":"七言绝句","c":["千仞溪中石转雷，汉家万骑捣虚回。","定知献马胡雏入，看即称觞都护来。"]},{"t":"次韵答马中玉三首 其三","f":"七言绝句","c":["仁气已蒸全楚尽，同云欲合暮江前。","争春梅柳无三月，对雪樽罍属二天。"]},{"t":"次韵答马中玉三首 其二","f":"七言绝句","c":["卷沙成浪北风颠，衔尾千艘不敢前。","匝岸水居皆有酒，行人得意买江天。"]},{"t":"次韵答马中玉三首 其一","f":"七言绝句","c":["雨入纱窗风簸船，菊花过后早梅前。","锦江春色熏人醉，也到壶中小隐天。"]},{"t":"次韵答少章闻雁听鸡二首 其二","f":"七言绝句","c":["朝士闻鸡常半途，朱门拥被不关渠。","秦郎五起听三唱，残烛贪传未见书。"]},{"t":"次韵答少章闻雁听鸡二首 其一","f":"七言绝句","c":["平生绝少分甘处，身要从师万事忘。","霜雁叫群倾半枕，梦回兄弟綵衣行。"]},{"t":"次韵答邵之才","f":"七言绝句","c":["文章真向古人疏，聊有孤怀与世殊。","陋质不堪华衮赠，可能薏苡似明珠。"]},{"t":"次韵谢公定王世弼赠答二绝句 其二","f":"七言绝句","c":["酒因咀嚼还知味，诗就呻吟不要工。","王谢风流看二妙，病夫直欲卧墙东。"]},{"t":"次韵谢公定王世弼赠答二绝句 其一","f":"七言绝句","c":["何用苦吟肝肾愁，但知把酒更无忧。","声名本不关人事，看取青门一故侯。"]},{"t":"次韵裴尉过马鞍山","f":"七言绝句","c":["青山如马怒盘旋，错认林花作锦鞯。","君不据鞍朝玉帝，岂宜长作市门仙。"]},{"t":"次韵题粹老客亭诗后","f":"七言绝句","c":["客亭长短路南北，衮衮行人那得知。","惟有相逢即相别，一杯成喜只成悲。"]},{"t":"江南","f":"七言绝句","c":["梦寐江南未得归，清波鷠子上钩肥。","五年身属官仓米，输与渔人坐钓矶。"]},{"t":"百花洲杂题","f":"七言绝句","c":["范公种竹水边亭，漂泊来游一客星。","神理不应从此尽，百年草树至今青。"]},{"t":"竹下把酒","f":"五言绝句","c":["竹下倾春酒，愁阴为我开。","不知临水语，更得几回来。"]},{"t":"竹颂","f":"五言绝句","c":["深根藏器时，寸寸抱奇节。","遭时上风云，故可傲冰雪。"]},{"t":"考试局与孙元忠博士竹间对窗夜闻元忠诵书声调悲壮戏作竹枝歌三章和之 其三","f":"七言绝句","c":["勃姑夫妇喜相唤，街头雪泥即渐乾。","已放游丝高百尺，不应桃李尚春寒。"]},{"t":"自咸平至太康鞍马间得十小诗寄怀晏叔原并问王稚川行李鹅儿黄似酒对酒爱新鹅此他日醉时与叔原所咏因以为韵 其十","f":"五言绝句","c":["土气昏风日，人嚣极雁鹅。","寻河著绳墨，诗思略无多。"]},{"t":"自咸平至太康鞍马间得十小诗寄怀晏叔原并问王稚川行李鹅儿黄似酒对酒爱新鹅此他日醉时与叔原所咏因以为韵 其二","f":"五言绝句","c":["春风马上梦，樽酒故人持。","犹作狂时语，邻家乞侍儿。"]},{"t":"自咸平至太康鞍马间得十小诗寄怀晏叔原并问王稚川行李鹅儿黄似酒对酒爱新鹅此他日醉时与叔原所咏因以为韵 其三","f":"五言绝句","c":["忆同嵇阮辈，醉卧酒家床。","今日垆边客，初无人姓黄。"]},{"t":"自咸平至太康鞍马间得十小诗寄怀晏叔原并问王稚川行李鹅儿黄似酒对酒爱新鹅此他日醉时与叔原所咏因以为韵 其一","f":"五言绝句","c":["诗入鸡林市，书邀道士鹅。","云间晏公子，风月兴如何。"]},{"t":"芝赞","f":"七言绝句","c":["不生甘泉铜池边，一茎九叶媚神天。","伴余西去禦魑魅，马湖江上看蛮船。"]},{"t":"行迈杂篇六首 其六","f":"七言绝句","c":["十日狂风桃柳休，常因酒尽觉春愁。","泰山为肉酿沧海，料得人间无白头。"]},{"t":"行迈杂篇六首 其五","f":"七言绝句","c":["满院青杨吐白绵，未多柳絮解漫天。","野人岂会断优劣，只问床头沽酒钱。"]},{"t":"行迈杂篇六首 其四","f":"七言绝句","c":["杏村桃坞春三月，少有人家不出游。","一顾虽无倾国色，千金肯为使君留。"]},{"t":"行迈杂篇六首 其三","f":"七言绝句","c":["村落人家桃李枝，无言气味亦依依。","可怜憔悴蓬蒿底，蜂蝶不知春又归。"]},{"t":"行迈杂篇六首 其二","f":"七言绝句","c":["白白红红相间开，三三五五踏青来。","戏随胡蝶不知远，惊见行人笑却回。"]},{"t":"行迈杂篇六首 其一","f":"七言绝句","c":["簇簇深红间浅红，苦才多思是春风。","千村万落花相照，尽日经行锦绣中。"]},{"t":"观化十五首 其十五","f":"七言绝句","c":["花开岁岁复年年，病眼看花隔晚烟。","春去明明红紫落，清风明月是春前。"]},{"t":"观化十五首 其十四","f":"七言绝句","c":["淘沙邂逅得黄金，莫便沙中着意寻。","指月向人人不会，清霄印在碧潭心。"]},{"t":"观化十五首 其十三","f":"七言绝句","c":["身前身后与谁同，花落花开毕竟空。","千里追奔两蜗角，百年得意大槐宫。"]},{"t":"观化十五首 其十二","f":"七言绝句","c":["身入醉乡如避秦，醒时尘事百端新。","塞鸿过尽无家信，海燕归来思故人。"]},{"t":"观化十五首 其十一","f":"七言绝句","c":["竹笋初生黄犊角，蕨芽已作小儿拳。","试挑野菜炊香饭，便是江南二月天。"]},{"t":"观化十五首 其十","f":"七言绝句","c":["红罗步障三十里，忆得南溪踯躅花。","马上春风吹梦去，依稀人摘雨前茶。"]},{"t":"观化十五首 其九","f":"七言绝句","c":["柳似罗敷十五馀，宫腰舞罢不胜扶。","年年折在行人手，为问春风管得无。"]},{"t":"观化十五首 其八","f":"七言绝句","c":["不知喜事在谁边，风结灯花何太妍。","恐是邻家醅瓮熟，竹渠今夜滴春泉。"]},{"t":"观化十五首 其七","f":"七言绝句","c":["菰蒲短短未出水，渺渺春湖如冻云。","安得酒船三万斛，棹歌长入白鸥群。"]},{"t":"观化十五首 其六","f":"七言绝句","c":["故人去后绝朱弦，不报双鱼已隔年。","邻笛风飘月中起，碧云为我作愁天。"]},{"t":"观化十五首 其五","f":"七言绝句","c":["一原风俗异衣裘，流落来从绵上州。","未到清明先禁火，还依桑下系千秋。"]},{"t":"观化十五首 其四","f":"七言绝句","c":["风烟漠漠半阴晴，人道春归不见形。","嫩草已侵水面绿，平芜还破烧痕青。"]},{"t":"观化十五首 其三","f":"七言绝句","c":["山回路转水深深，欲问津头谷鸟吟。","隔岸野花随意发，小蹊犹忆去年寻。"]},{"t":"观化十五首 其二","f":"七言绝句","c":["生涯萧洒似吾庐，人在青山远近居。","泉响风摇苍玉佩，月高云插水晶梳。"]},{"t":"观化十五首 其一","f":"七言绝句","c":["柳外花中百鸟喧，相媒相和隔春烟。","黄昏寂寞无言语，恰似人归锁管弦。"]},{"t":"访赵君举","f":"七言绝句","c":["朔风吹雪满都城，晓踏骅骝访玉京。","相引槽头看春酒，细流三峡夜泉声。"]},{"t":"过西山","f":"七言绝句","c":["新春木叶未蒙笼，西望天涯几日通。","商洛山间白云起，行歌思见采芝翁。"]},{"t":"问渔父","f":"七言绝句","c":["白发丈人持竹竿，系船留我坐柴关。","偶然领会一谈胜，落日使人思故山。"]},{"t":"何萧二族","f":"七言绝句","c":["西汉功名相国多，南朝人物数诸何。","向来富贵喧天地，亦有文章在涧阿。"]},{"t":"余成诗","f":"七言绝句","c":["丹籍生涯无列鼎，白头忠信可专城。","自非车骑将军势，愧使王尼常作兵。"]},{"t":"吴执中有两鹅为余烹之戏赠","f":"七言绝句","c":["学书池上一双鹅，宛颈相追笔意多。","皆为涪翁赴汤鼎，主人言汝不能歌。"]},{"t":"吴君送水仙花并二大本","f":"七言绝句","c":["折送南园栗玉花，并移香本到寒家。","何时持上玉宸殿，乞与宫梅定等差。"]},{"t":"呈外舅孙莘老二首 其二","f":"七言绝句","c":["甓社湖中有明月，淮南草木借光辉。","故应剖蚌登王府，不若行沙弄夕霏。"]},{"t":"呈外舅孙莘老二首 其一","f":"七言绝句","c":["九陌黄尘乌帽底，五湖春水白鸥前。","扁舟不为鲈鱼去，收取声名四十年。"]},{"t":"呈杨康国","f":"七言绝句","c":["君家秋实罗浮种，已作累累半拂墙。","莫遣儿童酸打尽，要看霜后十分黄。"]},{"t":"张仲谋家堂前酴醾委地","f":"七言绝句","c":["沈水衣笼白玉苗，不蒙湔拂苦无聊。","烦君斫取西庄柳，扶起春风十万条。"]},{"t":"李右司以诗送梅花至潞公予虽不接右司想见其人用老杜和元次山诗例次韵","f":"七言绝句","c":["凡花俗草败人意，晚见琼蕤不恨迟。","江左风流尚如此，春功终到岁寒枝。"]},{"t":"李宗古出示谢李道人苕帚杖从蒋彦回乞葬地二颂作二诗奉呈 其二","f":"七言绝句","c":["诗书传女似中郎，杞菊同盘有孟光。","今日鹧鸪鸣蹇蹇，他年鹦鹉恨堂堂。"]},{"t":"李宗古出示谢李道人苕帚杖从蒋彦回乞葬地二颂作二诗奉呈 其一","f":"七言绝句","c":["提携禅客扶衰杖，断当姻家葬骨山。","因病废棋仍废酒，鹧鸪鹦鹉伴清閒。"]},{"t":"杜似吟院二首 其二","f":"七言绝句","c":["吟院虚明如画舫，想成槛外是长江。","杜郎忽作扬州梦，雨带风沙打夜窗。"]},{"t":"杜似吟院二首 其一","f":"七言绝句","c":["日长吟院无公事，燕入花开必有诗。","莫道南风吹雁去，春来亦有北风时。"]},{"t":"杨朴墓","f":"七言绝句","c":["三尺孤坟一布衣，人言无复似当时。","千秋万岁还来此，月笛烟莎世不知。"]},{"t":"求范子默染鸦青纸二首 其二","f":"七言绝句","c":["深如女发兰膏罢，明似山光夜月馀。","为染溪藤三百个，待渠湔拂一床书。"]},{"t":"求范子默染鸦青纸二首 其一","f":"七言绝句","c":["学似贫家老破除，古今迷忘失三馀。","极知鹄白非新得，谩染鸦青袭旧书。"]},{"t":"走笔谢王朴居士拄杖","f":"七言绝句","c":["投我木瓜霜雪枝，六年流落放归时。","千岩万壑须重到，脚底危时幸见持。"]},{"t":"邹松滋寄苦竹泉橙曲莲子汤三首 其三","f":"七言绝句","c":["新收千百秋莲菂，剥尽红衣捣玉霜。","不假参同成气味，跳珠椀里绿荷香。"]},{"t":"邹松滋寄苦竹泉橙曲莲子汤三首 其二","f":"七言绝句","c":["天将金阙真黄色，借与洞庭霜后橙。","松滋解作逡巡曲，压倒江南好事僧。"]},{"t":"邹松滋寄苦竹泉橙曲莲子汤三首 其一","f":"七言绝句","c":["松滋县西竹林寺，苦竹林中甘井泉。","巴人漫说虾蟆培，试裹春芽来就煎。"]},{"t":"阻水戏呈几复二首 其二","f":"七言绝句","c":["月明遥夜见秋高，桂影依稀数兔豪。","散发行歌野田上，一樽可慰百年劳。"]},{"t":"阻水戏呈几复二首 其一","f":"七言绝句","c":["秋风落木秋天高，月入金樽动酒豪。","过眼衰荣等昏晓，勿嗟迟速把心劳。"]},{"t":"陈说道约日送菜把","f":"七言绝句","c":["南山畴昔从诸父，雨甲烟苗手自锄。","三径就荒归计拙，溷烦僚友送园蔬。"]},{"t":"饮李氏园三首 其三","f":"七言绝句","c":["手挼红杏醉繁香，回首春前梦一场。","便与经营百船酒，再来应是菊花黄。"]},{"t":"饮李氏园三首 其二","f":"七言绝句","c":["日暮凉风特特来，醉呼红烛更传杯。","歌阑兴尽须归去，不用繁蝉抵死催。"]},{"t":"饮李氏园三首 其一","f":"七言绝句","c":["小摘来禽兴未厌，蔬畦经雨绿纤纤。","坐分紫石蒲萄下，不怕龙须罥帽檐。"]},{"t":"饮南禅梅下戏题","f":"七言绝句","c":["新春江上使星回，不为离人寄早梅。","爱惜幽香意如此，一樽岂是等闲来。"]},{"t":"龟壳轩","f":"七言绝句","c":["紫极宫中三百楹，道人独藏一神屋。","开轩纳息星月明，时有白云来伴宿。"]},{"t":"到官归志浩然二绝句 其一","f":"七言绝句","c":["雨洗风吹桃李净，松声聒尽鸟惊春。","满船明月从此去，本是江湖寂寞人。"]},{"t":"到官归志浩然二绝句 其二","f":"七言绝句","c":["鸟乌未觉常先晓，笋蕨登盘始见春。","敛手还他能者作，从来刀笔不如人。"]},{"t":"叔父给事挽词十首 其十","f":"七言绝句","c":["荣禄常思泽九宗，山摧梁坏床成空。","百年遗恨谁昭洗，他日诸郎有父风。"]},{"t":"叔父给事挽词十首 其九","f":"七言绝句","c":["廊庙从来不在边，黄扉青琐庆登贤。","除书未试回天笔，何意佳城到马前。"]},{"t":"叔父给事挽词十首 其八","f":"七言绝句","c":["陇上千山汉节回，扫除民蜮不为灾。","蜀茶总入诸蕃市，胡马常从万里来。"]},{"t":"叔父给事挽词十首 其七","f":"七言绝句","c":["军容百万转风雷，独料王师不战摧。","三箧飞书公对狱，元丰天子照奸回。"]},{"t":"叔父给事挽词十首 其六","f":"七言绝句","c":["晋地无戎卧贼曹，民兵赐笏解弓刀。","六年讲武儒冠在，不踏金门著战袍。"]},{"t":"叔父给事挽词十首 其五","f":"七言绝句","c":["曾发公家钜万钱，沟中襁褓却生全。","三齐水后皆禾稼，不杀耕牛更可传。"]},{"t":"叔父给事挽词十首 其四","f":"七言绝句","c":["更生苦讼石中书，宰掾非人欲引裾。","两猾论兵几败国，同时御史更谁如。"]},{"t":"叔父给事挽词十首 其三","f":"七言绝句","c":["三晋山河数十州，频年水旱不能秋。","我公出把司农节，粟麦还于地上流。"]},{"t":"叔父给事挽词十首 其二","f":"七言绝句","c":["平生治狱有阴功，忠孝临民父母同。","赣上樵夫谈卓令，宣城老吏识于公。"]},{"t":"叔父给事挽词十首 其一","f":"七言绝句","c":["元祐宗臣考十科，公居八九未为多。","功名身后无瑕点，孝友生知不琢磨。"]},{"t":"和子瞻内翰题公择舅中丞山房","f":"七言绝句","c":["幽人八座复中台，想见书堂山杏开。","四十馀年僧屈指，时因秋雁寄声来。"]},{"t":"和宁子与白鹿寺","f":"七言绝句","c":["谷朗岩开见佛灯，云遮雾掩碧层层。","青山得意看流水，白鹿归来失旧僧。"]},{"t":"和李才甫先辈快阁五首 其五","f":"七言绝句","c":["西南佳气浮马祖，东北祥风绕静居。","山邑丰年人少讼，身来访道得斋鱼。"]},{"t":"和李才甫先辈快阁五首 其四","f":"七言绝句","c":["云横章贡雨翻盆，寺下江深水到门。","落日荷锄人著本，西风满地叶归根。"]},{"t":"和李才甫先辈快阁五首 其三","f":"七言绝句","c":["长江淡淡吞天去，甲子随波日日流。","万事转头同堕甑，一身随世作虚舟。"]},{"t":"和李才甫先辈快阁五首 其二","f":"七言绝句","c":["赤栏终日倚西风，山色挼蓝小雨中。","将老鬓毛秋著木，相思亲旧水连空。"]},{"t":"和李才甫先辈快阁五首 其一","f":"七言绝句","c":["山寒江冷丹枫落，争渡行人簇晚沙。","菰叶蘋花飞白鸟，一张红锦夕阳斜。"]},{"t":"和陈君仪读太真外传五首 其五","f":"七言绝句","c":["上皇曾御昭仪传，镜里观形只眼前。","养得禄儿倾四海，千秋更有一伶玄。"]},{"t":"和陈君仪读太真外传五首 其四","f":"七言绝句","c":["高丽条脱雕红玉，逻逤琵琶撚绿丝。","蛛网屋煤昏故物，此生惟有梦来时。"]},{"t":"和陈君仪读太真外传五首 其三","f":"七言绝句","c":["梁州一曲当时事，记得曾拈玉笛吹。","端正楼空春昼永，小桃犹学淡燕支。"]},{"t":"和陈君仪读太真外传五首 其二","f":"七言绝句","c":["扶风乔木夏阴合，斜谷铃声秋夜深。","人到愁来无处会，不关情处总伤心。"]},{"t":"和陈君仪读太真外传五首 其一","f":"七言绝句","c":["朝廷无事君臣乐，花柳多情殿阁春。","不觉胡雏心暗动，绮罗翻作坠楼人。"]},{"t":"和凉轩二首 其二","f":"五言绝句","c":["茗椀梦中觉，荷花镜里香。","凉生只当处，暑退亦无方。"]},{"t":"和凉轩二首 其一","f":"五言绝句","c":["打荷看急雨，吞月任行云。","夜半蚊雷起，西风为解纷。"]},{"t":"和程德裕颂五首 其五","f":"七言绝句","c":["石田耕种难成稻，荼蓼栽来只苦辛。","万物一家真富贵，使君见后却清贫。"]},{"t":"和程德裕颂五首 其四","f":"七言绝句","c":["如来刹刹与尘尘，北斗南箕透法身。","金粟默然轲好辩，唱歌须是帝乡人。"]},{"t":"和程德裕颂五首 其三","f":"七言绝句","c":["山河大地目前机，横按吹毛更不疑。","万里无人无寸草，冻山亭上与谁欺。"]},{"t":"和程德裕颂五首 其二","f":"七言绝句","c":["鹏飞逼塞满空虚，蚊睫安巢却有馀。","腊月火烧三界尽，从来灰里拨真如。"]},{"t":"和程德裕颂五首 其一","f":"七言绝句","c":["贫子还家作富儿，粪箕苕帚未曾遗。","人人欲问草书意，怀素从来自不知。"]},{"t":"和答君庸见寄别时绝句","f":"七言绝句","c":["看镜白头知我老，平生青眼为君明。","舞姝别后閒珠履，已报丝虫网玉笙。"]},{"t":"和谢公定河朔漫成八首 其二","f":"七言绝句","c":["直渠杀势烦才吏，机器爬沙聚水兵。","河面常从天上落，金堤千里护都城。"]},{"t":"和谢公定河朔漫成八首 其一","f":"七言绝句","c":["急雨长风溢两河，欣然河伯顺风歌。","行观东海方存少，不以黄流更自多。"]},{"t":"和谢公定河朔漫成八首 其八","f":"七言绝句","c":["百里弃疆王自直，万金捐费物皆春。","须令牧马甘踰幕，更遣弯弓不射人。"]},{"t":"和谢公定河朔漫成八首 其七","f":"七言绝句","c":["蛛蒙黄画屏初暗，尘涩金门锁不开。","六十馀年望雕辇，赭袍曾是映宫槐。"]},{"t":"和谢公定河朔漫成八首 其六","f":"七言绝句","c":["漠庭数遣林牙使，羌种来窥雁塞耕。","壮士看天思上策，月边鸣笛为谁横。"]},{"t":"和谢公定河朔漫成八首 其五","f":"七言绝句","c":["汉时水占十万顷，官寺民居皆浊河。","岂必九渠亡故道，直缘穿凿用功多。"]},{"t":"和谢公定河朔漫成八首 其四","f":"七言绝句","c":["莱公庙略传耆旧，韩令风流在井疆。","安用鸣鼛增汉垒，不妨罗拜下诸羌。"]},{"t":"和谢公定河朔漫成八首 其三","f":"七言绝句","c":["直令南粤还归帝，谁谓匈奴不敢王。","愿见推财多卜式，未须算赋似桑羊。"]},{"t":"和蒲泰亨四首 其四","f":"七言绝句","c":["栽竹养松人去尽，空闻道士种桃花。","昨来一夜惊风雨，满地残红噪暮蛙。"]},{"t":"和蒲泰亨四首 其三","f":"七言绝句","c":["玉座天开旋北斗，清班鸟散落馀花。","有人难立百官上，不为庙中羔兔蛙。"]},{"t":"和蒲泰亨四首 其二","f":"七言绝句","c":["东坡海上无消息，想见惊帆出浪花。","三十年来世三变，几人能不变鹑蛙。"]},{"t":"和蒲泰亨四首 其一","f":"七言绝句","c":["我已人间无所用，鬓飘霜雪眼生花。","东坡兄弟来虽晚，折箭堪除蚀月蛙。"]},{"t":"和裴仲谋雨中自石塘归","f":"七言绝句","c":["裴友西来咏古风，驱驰万象笔端空。","尚将物色留分我，远近青山烟雨中。"]},{"t":"咏萍","f":"七言绝句","c":["白发已侵残梦境，绿苔应忆旧渔矶。","桃源鸡犬尘凡隔，韦曲桑麻念想归。"]},{"t":"夜发分宁寄杜涧叟","f":"七言绝句","c":["阳关一曲水东流，灯火旌阳一钓舟。","我自只如常日醉，满川风月替人愁。"]},{"t":"夜闻邻舟崔家儿歌","f":"七言绝句","c":["半夜闻歌客寝惊，空馀缥缈渡江声。","湘妃舞罢波纹冷，月欲衔山天未明。"]},{"t":"奉同公择作拣芽咏","f":"七言绝句","c":["赤囊岁上双龙璧，曾见前朝盛事来。","想得天香随御所，延春阁道转轻雷。"]},{"t":"奉同六舅尚书咏茶碾煎烹三首 其三","f":"七言绝句","c":["乳粥琼糜雾脚回，色香味触映根来。","睡魔有耳不及掩，直拂绳床过疾雷。"]},{"t":"奉同六舅尚书咏茶碾煎烹三首 其二","f":"七言绝句","c":["风炉小鼎不须催，鱼眼长随蟹眼来。","深注寒泉收第一，亦防枵腹爆乾雷。"]},{"t":"奉同六舅尚书咏茶碾煎烹三首 其一","f":"七言绝句","c":["要及新香碾一杯，不应传宝到云来。","碎身粉骨方馀味，莫厌声喧万壑雷。"]},{"t":"奉和孙奉议谢送菜","f":"七言绝句","c":["春蔬照映庾郎贫，遣骑持笼佐茹荤。","却得斋厨厌滋味，白鹅存掌鳖留裙。"]},{"t":"奉留楚金长老 其一","f":"七言绝句","c":["长安甚闹不须惊，好与牛儿著鼻绳。","方便把他悲愿满，斩新然佛大明灯。"]},{"t":"奉答李和甫代简二绝句 其一","f":"七言绝句","c":["山色江声相与清，卷帘待得月华生。","可怜一曲并船笛，说尽故人离别情。"]},{"t":"奉答李和甫代简二绝句 其二","f":"七言绝句","c":["梦中往事随心见，醉里繁华乱眼生。","长为风流恼人病，不如天性总无情。"]},{"t":"奉谢泰亨送酒","f":"七言绝句","c":["风扫三峨山外雨，霜摧五柳宅边花。","非君送酒添秋睡，可耐东池到晓蛙。"]},{"t":"学元翁作女儿浦口诗","f":"七言绝句","c":["五老峰前万顷江，女儿浦口鸳鸯双。","惊飞何处沙上宿，夜雨钓船灯照窗。"]},{"t":"学许氏说文赠诸弟","f":"七言绝句","c":["六书章句苦支离，非复黄神太古时。","鸟迹虫纹皆有法，犹胜双陆伴儿嬉。"]},{"t":"往岁过广陵值早春尝作诗云春风十里珠帘捲彷佛三生杜牧之红药梢头初茧栗扬州风物鬓成丝今春有自淮南来者道扬州事戏以前韵寄王定国二首 其一","f":"七言绝句","c":["淮南二十四桥月，马上时时梦见之。","想得扬州醉年少，正围红袖写乌丝。"]},{"t":"往岁过广陵值早春尝作诗云春风十里珠帘捲彷佛三生杜牧之红药梢头初茧栗扬州风物鬓成丝今春有自淮南来者道扬州事戏以前韵寄王定国二首 其二","f":"七言绝句","c":["日边置论诚深矣，圣处时中乃得之。","莫作秋虫促机杼，贫家能有几絇丝。"]},{"t":"所住堂","f":"七言绝句","c":["此山花光佛所住，今日花光还放光。","天女来修散花供，道人自有本来香。"]},{"t":"承示中秋不见月及悯雨连作恐妨秋成奉次元韵","f":"七言绝句","c":["秀稻秋风喜太平，独疑连雨未全晴。","银蟾似亦无聊赖，默度寒宵懒吐明。"]},{"t":"招吉老子范观梅花","f":"七言绝句","c":["播糠眯眼丞良苦，鸣鼓连村尉始归。","及取江梅来一醉，明朝花作玉尘飞。"]},{"t":"招戴道士弹琴","f":"七言绝句","c":["春愁如发不胜梳，酒病绵绵困未苏。","欲听淳音消妄想，抱琴端为一来无。"]},{"t":"欧阳从道许寄金橘以诗督之","f":"七言绝句","c":["禅客入秋无气息，想依红袖醉毰毸。","霜枝摇落黄金弹，许送筠笼殊未来。"]},{"t":"武陵","f":"七言绝句","c":["武陵樵客出桃源，自许重游不作难。","却觅洞门烟锁断，归舟风月夜深寒。"]},{"t":"牧童","f":"七言绝句","c":["骑牛远远过前村，吹笛风斜隔垄闻。","多少长安名利客，机关用尽不如君。"]},{"t":"直舍寄陈子惠","f":"七言绝句","c":["广文宾退下帘重，凉气微生笔砚中。","不得朱弦写流水，绿槐阴合鸟呼风。"]},{"t":"罗汉南公升堂颂二首 其二","f":"七言绝句","c":["黑蚁旋磨千里错，巴蛇吞象三年觉。","日光天子转须弥，失眼众生问演若。"]},{"t":"罗汉南公升堂颂二首 其一","f":"七言绝句","c":["宝积拾得漏贯钱，古佛堂前狗尿天。","东山日出西山雨，露柱搥胸哭破船。"]},{"t":"范德孺须笔裒诸工佳者共成十枝分送","f":"七言绝句","c":["临池闻道学书成，已许家鸡胜伯英。","雪竹霜毛分一束，开包何异五侯鲭。"]},{"t":"雨中登岳阳楼望君山二首 其一","f":"七言绝句","c":["投荒万死鬓毛斑，生出瞿塘滟滪关。","未到江南先一笑，岳阳楼上对君山。"]},{"t":"雨中登岳阳楼望君山二首 其二","f":"七言绝句","c":["满川风雨独凭栏，绾结湘娥十二鬟。","可惜不当湖水面，银山堆里看青山。"]},{"t":"雨花岩颂彭泽三岩","f":"七言绝句","c":["孤峰中流分江南，马当大雷无一帆。","波涛掀空鸟不度，天花雨我读书岩。"]},{"t":"驻舆遣人寻访后山陈德方家","f":"七言绝句","c":["江雨濛濛作小寒，雪飘五老发毛斑。","城中咫尺云横栈，独立前山望后山。"]},{"t":"临江寺僧以金线猿皮蒙棐几","f":"五言绝句","c":["蒙茸冒枯几，想像挂霜枝。","永失金衣友，文章安用为。"]},{"t":"养斗鸡","f":"七言绝句","c":["峥嵘已介季氏甲，更以黄金饰两戈。","虽有英心甘斗死，其如纪渻木鸡何。"]},{"t":"南楼画阁观方公悦二小诗戏次韵 其一","f":"七言绝句","c":["十年华屋网蛛尘，大旆重来一日新。","五凤楼前脩造手，个中馀刃亦精神。"]},{"t":"南楼画阁观方公悦二小诗戏次韵 其二","f":"七言绝句","c":["重山复水绕深幽，不见高贤独倚楼。","手拂壁间留恨句，凌波微步有人愁。"]},{"t":"急雪寄王立之问梅花","f":"七言绝句","c":["红梅雪里与蓑衣，莫遣寒侵鹤膝枝。","老子此中殊不浅，尚堪何逊作同时。"]},{"t":"春近四绝句 其二","f":"七言绝句","c":["亭台经雨压尘沙，春近登临意气佳。","更喜轻寒勒成雪，未春先放一城花。"]},{"t":"春近四绝句 其四","f":"七言绝句","c":["梅英欲尽香无赖，草色才苏绿未匀。","苦竹空将岁寒节，又随官柳到青春。"]},{"t":"春近四绝句 其三","f":"七言绝句","c":["小雪晴沙不作泥，疏帘红日弄朝晖。","年华已伴梅梢晚，春色先从草际归。"]},{"t":"春近四绝句 其一","f":"七言绝句","c":["闰后阳和腊里回，濛濛小雨暗楼台。","柳条榆荚弄颜色，便恐入帘双燕来。"]},{"t":"洪范以不合俗人题厅壁二绝句次韵和之 其二","f":"七言绝句","c":["埋没高才筑钓间，风云未会要鲵桓。","南康郡下参军耳，付与红尘白眼看。"]},{"t":"洪范以不合俗人题厅壁二绝句次韵和之 其一","f":"七言绝句","c":["寂寥吾道付万世，忍向时人觅赏音。","搔首金城西万里，樽前从此叹人琴。"]},{"t":"砌台晚思","f":"七言绝句","c":["日极江南千里春，谁今洒笔可招魂。","向人犹作故时面，翠竹苍烟一万根。"]},{"t":"秋冬之间鄂渚绝市无蟹今日偶得数枚吐沫相濡乃可悯笑戏成小诗三首 其一","f":"七言绝句","c":["怒目横行与虎争，寒沙奔火祸胎成。","虽为天上三辰次，未免人间五鼎烹。"]},{"t":"秋冬之间鄂渚绝市无蟹今日偶得数枚吐沫相濡乃可悯笑戏成小诗三首 其二","f":"七言绝句","c":["勃窣媻跚烝涉波，草泥出没尚横戈。","也知觳觫元无罪，奈此尊前风味何。"]},{"t":"秋思寄子由","f":"七言绝句","c":["黄落山川知晚秋，小虫催女献功裘。","老松阅世卧云壑，挽著沧江无万牛。"]},{"t":"绝句","f":"七言绝句","c":["花气薰人欲破禅，心情其实过中年。","春来诗思何所似，八节滩头上水船。"]},{"t":"绝句","f":"七言绝句","c":["富贵功名茧一盆，缲车头绪正纷纷。","肯寻冷淡做生活，定是著书扬子云。"]},{"t":"绝句赠初和甫","f":"七言绝句","c":["处士孤怀少往还，平时一刺字多漫。","能容著帽挥谈拂，可见高人礼数宽。"]},{"t":"胜业寺悦亭","f":"五言绝句","c":["苦雨已解严，诸峰来献状。","不见白头禅，空倚紫藤杖。"]},{"t":"荆州即事药名诗八首 其四","f":"五言绝句","c":["天竺黄卷在，人中白发侵。","客至独扫榻，自然同此心。"]},{"t":"荆州即事药名诗八首 其三","f":"五言绝句","c":["千里及归鸿，半天河影东。","家人森户外，笑拥白头翁。"]},{"t":"荆州即事药名诗八首 其一","f":"五言绝句","c":["四海无远志，一溪甘遂心。","牵牛避洗耳，卧著桂枝阴。"]},{"t":"贵耳贱目谜","f":"五言绝句","c":["驴耳对轩轩，争酬价十千。","眈眈两虎视，不值一文钱。"]},{"t":"赵子充示竹夫人诗盖凉寝竹器憩臂休膝似非夫人之职予为名曰青奴并以小诗取之二首 其二","f":"七言绝句","c":["秾李四弦风拂席，昭华三弄月侵床。","我无红袖堪娱夜，正要青奴一味凉。"]},{"t":"送六十五弟贲南归","f":"五言绝句","c":["风惊鸿雁行，吹落秋江上。","为扫碧岩边，问叔今无恙。"]},{"t":"送君庸","f":"七言绝句","c":["北风吹雨薄寒生，人与蜡梅相照明。","恨君草草渡江去，重约归时五凤笙。"]},{"t":"送张子列茶","f":"七言绝句","c":["斋馀一椀是常珍，味触色香当几尘。","借问深禅长不卧，何如官路醉眠人。"]},{"t":"送酒与毕大夫","f":"七言绝句","c":["浅色官醅昨夜篘，一樽聊付卯时投。","瓮边吏部应欢喜，殊胜平原老督邮。"]},{"t":"送蛤蜊与李明叔诸公","f":"七言绝句","c":["雪屋吹灯然豆萁，古来壮士亦长饥。","广文不得载酒去，且咏太玄庖蛤蜊。"]},{"t":"重答","f":"七言绝句","c":["莫怪东墙掷果频，沈郎眉宇正青春。","自言多病腰围减，依旧琼林照映人。"]},{"t":"闻吉老县丞按田在万安山中","f":"七言绝句","c":["苦雨初闻唤妇鸠，红妆满院木蕖秋。","樽前不记崔思立，应在诸山最上头。"]},{"t":"香炉峰","f":"七言绝句","c":["香炉不铸石陶甄，鼻不闻香眼见烟。","上有文殊师利塔，好将一瓣此中燃。"]},{"t":"效王仲至少监咏姚花用其韵四首 其四","f":"七言绝句","c":["汤沐冰肌照春色，海牛压帘风不开。","直言红尘无路入，犹傍蜂须蝶翅来。"]},{"t":"效王仲至少监咏姚花用其韵四首 其三","f":"七言绝句","c":["仙衣襞积驾黄鹄，草木无光一笑开。","人间风日不可奈，故待成阴叶下来。"]},{"t":"效王仲至少监咏姚花用其韵四首 其二","f":"七言绝句","c":["九疑山中萼绿华，黄云承袜到羊家。","真筌虫蚀诗句断，犹托馀情开此花。"]},{"t":"效王仲至少监咏姚花用其韵四首 其一","f":"七言绝句","c":["映日低风整复斜，绿玉眉心黄袖遮。","大梁城里虽罕见，心知不是牛家花。"]},{"t":"晓从任大夫祖行过石桥寄粹甫","f":"七言绝句","c":["令尹鸣驺过石桥，想君寒梦正飘摇。","追思转觉年来剧，乱似春风柳万条。"]},{"t":"晓出祥符趋府","f":"七言绝句","c":["朝霞藻绘舜衣裳，天碧山青认赭黄。","忆得御炉烟直下，紫宸辞罢过宫廊。"]},{"t":"海棠","f":"七言绝句","c":["海棠院里寻春色，日炙蔫红满院香。","不觉风光都过了，东窗浑为读书忙。"]},{"t":"病来十日不举酒二首 其二","f":"七言绝句","c":["病来十日不举酒，独卧南床春草生。","承君折送袁家紫，令我兴发郎官清。"]},{"t":"病来十日不举酒二首 其一","f":"七言绝句","c":["病来十日不举酒，回施青春与后生。","满袖东风惬人意，见君诗与字俱清。"]},{"t":"病起荆江亭即事十首 其四","f":"七言绝句","c":["成王小心似文武，周召何妨略不同。","不须要出我门下，实用人材即至公。"]},{"t":"病起荆江亭即事十首 其三","f":"七言绝句","c":["禁中夜半定天下，仁风义气彻脩门。","十分整顿乾坤了，复辟归来道更尊。"]},{"t":"离汝寄张子","f":"七言绝句","c":["草枯木落晚凄凄，目断黄尘听马嘶。","想子重行分首处，荒凉巢父井亭西。"]},{"t":"读书呈几复二首 其二","f":"七言绝句","c":["得君真似指南车，杖策方图问燕居。","吾欲忘言观道妙，六经俱是不完书。"]},{"t":"读书呈几复二首 其一","f":"七言绝句","c":["身入群经作蠹鱼，断编残简伴闲居。","不随当世师章句，颇识扬雄善读书。"]},{"t":"读晋史","f":"五言绝句","c":["天下放玄虚，谁知与道俱。","唯馀范武子，乃是晋诸儒。"]},{"t":"读谢安传","f":"七言绝句","c":["倾败秦师琰与玄，矫情不顾驿书传。","持危又幸桓温死，太傅功名亦偶然。"]},{"t":"贾天锡惠宝薰乞诗予以兵卫森画戟燕寝凝清香十字作诗报之 其十","f":"五言绝句","c":["衣篝丽纨绮，有待乃芬芳。","当念真富贵，自薰知见香。"]},{"t":"贾天锡惠宝薰乞诗予以兵卫森画戟燕寝凝清香十字作诗报之 其三","f":"五言绝句","c":["石蜜化螺甲，榠楂煮水沈。","博山孤烟起，对此作森森。"]},{"t":"贾天锡惠宝薰乞诗予以兵卫森画戟燕寝凝清香十字作诗报之 其九","f":"五言绝句","c":["雉尾映鞭声，金炉拂太清。","班近闻香早，归来学得成。"]},{"t":"贾天锡惠宝薰乞诗予以兵卫森画戟燕寝凝清香十字作诗报之 其八","f":"五言绝句","c":["床帷夜气馥，衣桁晚烟凝。","瓦沟鸣急雪，睡鸭照华灯。"]},{"t":"酌姨母崇德君寿酒","f":"七言绝句","c":["日月行当寿星纪，仙人初出阆风时。","欲将何物献寿酒，天上千秋桂一枝。"]},{"t":"酒","f":"七言绝句","c":["江形圜似阮家盆，山势岑如北海樽。","户有浮蛆春盎盎，双松一路醉乡门。"]},{"t":"陪师厚游百花洲槃礴范文正祠下道羊昙哭谢安石事因读生存华屋处零落归山丘为十诗 其七","f":"五言绝句","c":["委径问谣俗，高丘省佃作。","昔游非苟然，今花几开落。"]},{"t":"陪师厚游百花洲槃礴范文正祠下道羊昙哭谢安石事因读生存华屋处零落归山丘为十诗 其十","f":"五言绝句","c":["落日衔城壁，祠东更一游。","悲来惜酒少，安得董糟丘。"]},{"t":"陪师厚游百花洲槃礴范文正祠下道羊昙哭谢安石事因读生存华屋处零落归山丘为十诗 其六","f":"五言绝句","c":["公有一杯酒，与人同醉醒。","遗民能记忆，欲语涕飘零。"]},{"t":"陪师厚游百花洲槃礴范文正祠下道羊昙哭谢安石事因读生存华屋处零落归山丘为十诗 其九","f":"五言绝句","c":["人去洲渚在，春回花草斑。","清谈值渊对，发兴如江山。"]},{"t":"陪师厚游百花洲槃礴范文正祠下道羊昙哭谢安石事因读生存华屋处零落归山丘为十诗 其二","f":"五言绝句","c":["羊生但著鞭，勿哭西州门。","故有不亡者，南山相与存。"]},{"t":"陪师厚游百花洲槃礴范文正祠下道羊昙哭谢安石事因读生存华屋处零落归山丘为十诗 其一","f":"五言绝句","c":["忆在昭陵日，倾心用老成。","功归仁祖庙，正得一书生。"]},{"t":"陪师厚游百花洲槃礴范文正祠下道羊昙哭谢安石事因读生存华屋处零落归山丘为十诗 其三","f":"五言绝句","c":["庆州自不恶，藉甚载声华。","忠义可无憾，公今有世家。"]},{"t":"颂取之左右逢其原","f":"七言绝句","c":["取之左右逢其原，香严腊月火烧山。","对面谩人犹伫思，打得香严也是閒。"]},{"t":"宿钱塘尉廨","f":"七言绝句","c":["平湖绕舍山无盗，官事长闲俸有金。","安得终身为禦寇，不辞儿女作吴音。"]},{"t":"宿黄山","f":"七言绝句","c":["平时游此每雍容，掩袂今来对晚风。","白首同归人不见，黄山依旧月明中。"]},{"t":"寄刘泗州 其二","f":"七言绝句","c":["生天生地常为主，此事惟应作者知。","康济小民归一臂，屈伸由我更由谁。"]},{"t":"寄刘泗州 其一","f":"七言绝句","c":["万马千艘要路津，禅翁新画两朱轮。","行春定得忘言对，金碧浮图何姓人。"]},{"t":"寄杜家父二首 其二","f":"七言绝句","c":["风尘点污青春面，自汲寒泉洗醉红。","径欲题诗嫌浪许，杜郎觅句有新功。"]},{"t":"寄杜家父二首 其一","f":"七言绝句","c":["红紫争春触处开，九衢终日犊车雷。","閒情欲被春将去，鸟唤花惊只么回。"]},{"t":"寄贺方回","f":"七言绝句","c":["少游醉卧古藤下，谁与愁眉唱一杯。","解作江南断肠句，只今唯有贺方回。"]},{"t":"寄家","f":"七言绝句","c":["近别几日客愁生，固知远别难为情。","梦回官烛不盈把，犹听娇儿索乳声。"]},{"t":"寄黄龙清老三首 其三","f":"七言绝句","c":["骑驴觅驴但可笑，非马喻马亦成痴。","一天月色为谁好，二老风流只自知。"]},{"t":"寄黄龙清老三首 其二","f":"七言绝句","c":["风前橄榄星宿落，日下桄榔羽扇开。","昭默堂中有相忆，清秋忽遣化人来。"]},{"t":"梅花","f":"七言绝句","c":["障羞半面依篁竹，随意淡妆窥野塘。","飘泊风尘少滋味，一枝犹傍故人香。"]},{"t":"梦李白诵竹枝词三叠 其一","f":"七言绝句","c":["一声望帝花片飞，万里明妃雪打围。","马上胡儿那解听，琵琶应道不如归。"]},{"t":"梦李白诵竹枝词三叠 其三","f":"七言绝句","c":["命轻人鲊瓮头船，日瘦鬼门关外天。","北人堕泪南人笑，青壁无梯闻杜鹃。"]},{"t":"梨花","f":"五言绝句","c":["巧解逢人笑，还能乱蝶飞。","清风时入户，几片落新衣。"]},{"t":"欸乃歌二章戏王稚川 其二","f":"七言绝句","c":["从师学道鱼千里，盖世成功黍一炊。","日日倚门人不见，看尽林乌反哺儿。"]},{"t":"萧子云宅","f":"七言绝句","c":["郁木坑头春鸟呼，云迷帝子在时居。","风流扫地无寻处，只有寒藤学草书。"]},{"t":"鄂州南楼书事四首 其四","f":"七言绝句","c":["武昌参佐幕中画，我亦来追六月凉。","老子平生殊不浅，诸君少住对胡床。"]},{"t":"鄂州南楼书事四首 其三","f":"七言绝句","c":["势压湖南可长雄，胸吞云梦略从容。","北船未尝睹巨丽，复阁重楼天际逢。"]},{"t":"鄂州南楼书事四首 其二","f":"七言绝句","c":["画阁传觞容十客，透风透月两明轩。","南楼槃礴三百尺，天上云居不足言。"]},{"t":"鄂州南楼书事四首 其一","f":"七言绝句","c":["四顾山光接水光，凭栏十里芰荷香。","清风明月无人管，并作南楼一味凉。"]},{"t":"铜官僧舍得尚书郎赵宗闵墨竹一枝笔势妙天下为作小诗二首 其一","f":"七言绝句","c":["省郎潦倒今何处，败壁风生霜竹枝。","满世□□专翰墨，谁为真赏拂蛛丝。"]},{"t":"铜官僧舍得尚书郎赵宗闵墨竹一枝笔势妙天下为作小诗二首 其二","f":"七言绝句","c":["独来野寺无人识，故作寒崖雪压枝。","想得平生藏妙手，只今犹在鬓如丝。"]},{"t":"隐梅福处","f":"七言绝句","c":["吴门不作南昌尉，上疏归来朝市空。","笑拂岩花问尘世，故人子是国师公。"]},{"t":"雪后登南禅茅亭简张仲谋二首 其二","f":"七言绝句","c":["风入村墟摇酒旆，云埋行径罢樵苏。","狐裘年少宜追猎，正有饥鹰待一呼。"]},{"t":"雪后登南禅茅亭简张仲谋二首 其一","f":"七言绝句","c":["雪后凭高望洛都，万峰遮眼白模糊。","相将阆苑楼台上，展尽山阴水墨图。"]},{"t":"鸿沟","f":"七言绝句","c":["英雄并世不相容，割据山川计亦穷。","沟水已东全入汉，淮阴谁复议元功。"]},{"t":"黄几复自海上寄惠金液三十两且曰唯有德之士宜享将以排荡阴邪守卫真火幸不以凡物畜之戏答","f":"七言绝句","c":["皱面黄须已一翁，樽前犹发少年红。","金丹乞与烦真友，只恐无名帝籍中。"]},{"t":"黄雀","f":"七言绝句","c":["牛大垂天且割烹，细微黄雀莫贪生。","头颅虽复行万里，犹和盐梅傅说羹。"]},{"t":"短韵奉乞腊梅","f":"七言绝句","c":["卧云庄上残花笑，香似早梅开不迟。","浅色春衫弄风日，遣来当为作新诗。"]},{"t":"禅句二首 其二","f":"七言绝句","c":["予自钓鱼船上客，偶除须鬓著袈裟。","佛祖位中留不住，夜来依旧宿芦花。"]},{"t":"禅句二首 其一","f":"五言绝句","c":["牵驴饮江水，鼻吹波浪起。","岸上蹄踏蹄，水中嘴对嘴。"]},{"t":"禅颂","f":"五言绝句","c":["自古多如此，君今独奈何。","可来白云里，教汝紫芝歌。"]},{"t":"窗日","f":"七言绝句","c":["叹息西窗过隙驹，微阳初至日光舒。","□□□长宫中线，添得思堂一卷书。"]},{"t":"答余洪范二首 其二","f":"七言绝句","c":["悬磬斋厨数米炊，贫中气味更相思。","可无昨日黄花酒，又是春风柳絮时。"]},{"t":"答李任道谢分豆粥","f":"七言绝句","c":["豆粥能驱晚瘴寒，与公同味更同餐。","安知天上养贤鼎，且作山中煮菜看。"]},{"t":"答雍熙光老颂","f":"七言绝句","c":["独弄参军无鼓笛，右军池里泛渔舟。","岂知剑外雍熙老，收得黄巢折剑头。"]},{"t":"答檀君送含笑花颂","f":"七言绝句","c":["檀郎惠我花含笑，借问凝情笑阿谁。","一世茫茫走声利，阎公捉定始应知。"]},{"t":"谢人惠茶","f":"七言绝句","c":["一规苍玉琢蜿蜒，藉有佳人锦段鲜。","莫笑持归淮海去，为君重试大明泉。"]},{"t":"谢人惠猫头笋","f":"七言绝句","c":["长沙一月煨鞭笋，鹦鹉洲前人未知。","走送烦公助汤饼，猫头突兀想穿篱。"]},{"t":"谢五开府番罗袄","f":"七言绝句","c":["叠送香罗浅色衣，著来春色入书帷。","到家慈母惊相问，为说王孙脱赠时。"]},{"t":"谢公择舅分赐茶三首 其三","f":"七言绝句","c":["细题叶字包青箬，割取丘郎春信来。","拚洗一春汤饼睡，亦知清夜有蚊雷。"]},{"t":"谢公择舅分赐茶三首 其二","f":"七言绝句","c":["文书满案惟生睡，梦里鸣鸠唤雨来。","乞与降魔大圆镜，真成破柱作惊雷。"]},{"t":"谢公择舅分赐茶三首 其一","f":"七言绝句","c":["外家新赐苍龙璧，北焙风烟天上来。","明日蓬山破寒月，先甘和梦听春雷。"]},{"t":"谢王子予送橄榄","f":"七言绝句","c":["方怀味谏轩中果，忽见金盘橄榄来。","想共馀甘有瓜葛，苦中真味晚方回。"]},{"t":"谢王舍人剪送状元红","f":"七言绝句","c":["清香拂袖剪来红，似绕名园晓露丛。","欲作短章凭阿素，缓歌誇与落花风。"]},{"t":"谢应之","f":"七言绝句","c":["昨夜风雷震海隅，天心急拟活焦枯。","去年席上蛟龙语，未委先生记得无。"]},{"t":"谢张仲谋端午送巧作","f":"七言绝句","c":["君家玉女从小见，闻道如今画不成。","剪裁似借天女手，萱草石榴偏眼明。"]},{"t":"谢杨景山送酒器","f":"七言绝句","c":["杨君喜我梨花盏，却念初无注酒魁。","矲矮金壶肯持送，挼莎残菊更传杯。"]},{"t":"谢杨履道送银茄四首 其四","f":"七言绝句","c":["畦丁收尽垂露实，叶底犹藏十二三。","待得银包已成谷，更当乞种过江南。"]},{"t":"谢杨履道送银茄四首 其三","f":"七言绝句","c":["白金作颗非椎成，中有万粟嚼轻冰。","戎州夏畦少蔬供，感君来饭在家僧。"]},{"t":"谢杨履道送银茄四首 其二","f":"七言绝句","c":["君家水茄白银色，殊胜埧里紫彭亨。","蜀人生疏不下箸，吾与北人俱眼明。"]},{"t":"谢杨履道送银茄四首 其一","f":"七言绝句","c":["藜藿盘中生精神，珍蔬长蒂色胜银。","朝来盐醯饱滋味，已觉瓜瓠漫轮囷。"]},{"t":"谢陈正字送荔支三首 其三","f":"七言绝句","c":["橄榄湾南远归客，烦将嘉果送蓬门。","红衣襞积蛮烟润，白晒丁香之子孙。"]},{"t":"谢陈正字送荔支三首 其二","f":"七言绝句","c":["斋馀睡思生汤饼，红颗分甘惬下茶。","如梦泊船甘柘雨，芭蕉林里有人家。"]},{"t":"谢陈正字送荔支三首 其一","f":"七言绝句","c":["十年梨枣雪中看，想见江城荔子丹。","赠我甘酸三百颗，稍知身作近南官。"]},{"t":"谢周文之送猫儿","f":"七言绝句","c":["养得狸奴立战功，将军细柳有家风。","一箪未厌鱼餐薄，四壁当令鼠穴空。"]},{"t":"谢郑闳中惠高丽画扇二首 其二","f":"七言绝句","c":["蘋汀游女能骑马，传道蛾眉画不如。","宝扇真成集陈隼，史臣今得杀青书。"]},{"t":"谢郑闳中惠高丽画扇二首 其一","f":"七言绝句","c":["会稽内史三韩扇，分送黄门画省中。","海外人烟来眼界，全胜博物注鱼虫。"]},{"t":"谢荣绪割獐见贻二首 其二","f":"七言绝句","c":["二十馀年枯淡过，病来箸下剧甘肥。","果然口腹为灾怪，梦去呼鹰雪打围。"]},{"t":"谢荣绪割獐见贻二首 其一","f":"七言绝句","c":["何处惊麇触祸机，烦君遣骑割鲜肥。","秋来多病新开肉，粝饭寒菹得解围。"]},{"t":"谢荣绪惠贶鲜鲫","f":"七言绝句","c":["偶思暖老庖玄鲫，公遣霜鳞贯柳来。","齑臼方看金作屑，鲙盘已见雪成堆。"]},{"t":"谢赵令载酒","f":"七言绝句","c":["邂逅相将倒一壶，看朱成碧倩人扶。","欲眠甚急须公去，能略陶潜醉后无。"]},{"t":"谢晓纯送衲袜","f":"七言绝句","c":["刬草曾升马祖堂，暖窗接膝话还乡。","赠行百衲兜罗袜，处处相随入道场。"]},{"t":"谢益修四弟送石屏","f":"七言绝句","c":["石似江沧落日明，鸬鹚乌鹊满沙汀。","小儿骨相能文字，乞与班班作砚屏。"]},{"t":"谢答闻善二兄九绝句 其三","f":"七言绝句","c":["群猪过饮尚可醉，疥手轑瓮庸何伤。","柳家兄弟太迫窄，狂药不容人发狂。"]},{"t":"谢答闻善二兄九绝句 其六","f":"七言绝句","c":["公择醉面桃花红，人百忤之无愠容。","莘老夜阑倾数斗，焚香默坐日生东。"]},{"t":"谢答闻善二兄九绝句 其一","f":"七言绝句","c":["身入醉乡无畔岸，心与欢伯为友朋。","更阑骂坐客星散，午过未苏发鬅鬙。"]},{"t":"谢答闻善二兄九绝句 其五","f":"七言绝句","c":["阮籍醉睡不论昏，刘伶鸡肋避尊拳。","至今凛凛有生气，饮酒真成不愧天。"]},{"t":"谢答闻善二兄九绝句 其七","f":"七言绝句","c":["椎床破面枨触人，作无义语怒四邻。","尊中欢伯笑尔辈，我本和气如三春。"]},{"t":"谢答闻善二兄九绝句 其二","f":"七言绝句","c":["未尝顷刻可去酒，无有一日不吟诗。","诗狂克念作酒圣，意态忽如少年时。"]},{"t":"谢答闻善二兄九绝句 其九","f":"七言绝句","c":["阮籍刘伶智如海，人间有道作糟丘。","酒中无诤真三昧，便觉嵇康输一筹。"]},{"t":"谢答闻善二兄九绝句 其四","f":"七言绝句","c":["莫作叫号惊四邻，瓮中有地可藏真。","渊明醉握远公手，大笑绝倒人不嗔。"]},{"t":"谢答闻善二兄九绝句 其八","f":"七言绝句","c":["陶令舍中有名酒，无日不为父老倾。","四座欢欣观酒德，一灯明暗又诗成。"]},{"t":"谢檀敦信送柑子","f":"七言绝句","c":["色深林表风霜下，香著尊前指爪间。","书后合题三百颗，频随驿使未应悭。"]},{"t":"催公静碾茶","f":"七言绝句","c":["雪里过门多恶客，春阴只恼有情人。","睡魔正仰茶料理，急遣溪童碾玉尘。"]},{"t":"睡起","f":"七言绝句","c":["彷佛江南一梦中，虚堂尽日转温风。","春深稍觉裌衣重，昼永不知樽酒空。"]},{"t":"睡起","f":"七言绝句","c":["柿叶铺庭红颗秋，薰炉沈水度衣篝。","松风梦与故人遇，同驾飞鸿跨九州。"]},{"t":"睡起二首 其二","f":"七言绝句","c":["古来志士愿不辱，少在朝廷多在山。","寄食生涯无定止，此心长到白云间。"]},{"t":"睡起二首 其一","f":"七言绝句","c":["帘幕阴阴不见人，日斜窗影弄游尘。","风和睡起鸟声乐，天地无私花柳春。"]},{"t":"谪居黔南十首 其二","f":"五言绝句","c":["霜降水反壑，风落木归山。","冉冉岁华晚，昆虫皆闭关。"]},{"t":"谪居黔南十首 其五","f":"五言绝句","c":["冥怀齐远近，委顺随南北。","归去诚可怜，天涯住亦得。"]},{"t":"谪居黔南十首 其六","f":"五言绝句","c":["老色日上面，欢悰日去心。","今既不如昔，后当不如今。"]},{"t":"谪居黔南十首 其一","f":"五言绝句","c":["相望六千里，天地隔江山。","十书九不到，何用一开颜。"]},{"t":"暮到张氏园和壁间旧题","f":"七言绝句","c":["邵平不见见园瓜，三径还寻二仲家。","莫道暂来无所得，未秋先已碧莲华。"]},{"t":"漫书呈几复三首 其三","f":"七言绝句","c":["秋虫振羽惊寒梦，河汉西斜夜独兴。","欲罢不能呼子起，新凉宜近读书灯。"]},{"t":"漫书呈几复三首 其二","f":"七言绝句","c":["空名不系身轻重，此道当如命废兴。","彷佛古人前日事，解衣扪虱对青灯。"]},{"t":"漫书呈几复三首 其一","f":"七言绝句","c":["古人踽踽已先登，后学萧萧不再兴。","顾我尪羸君勉强，百年漂忽甚风灯。"]},{"t":"漫兴","f":"七言绝句","c":["肉食倾人如出凡，藜羹赋我是朝三。","晓来不倦听衙鼓，云里捲帘山正南。"]},{"t":"蜡梅","f":"七言绝句","c":["天工戏剪百花房，夺尽人工更有香。","埋玉地中成故物，折枝镜里忆新妆。"]},{"t":"裴晋公书堂","f":"七言绝句","c":["裴公入相便论兵，跃马淮西一战平。","黄閤不须金印好，却来山下作书生。"]},{"t":"酴醾","f":"七言绝句","c":["汉宫娇额半涂黄，入骨浓薰贾女香。","日色渐迟风力细，倚栏偷舞白霓裳。"]},{"t":"醇道得蛤蜊复索舜泉舜泉已酌尽官酝不堪不敢送","f":"七言绝句","c":["青州从事难再得，墙底数樽犹未眠。","商略督邮风味恶，不堪持到蛤蜊前。"]},{"t":"题子瞻寺壁小山枯木二首 其二","f":"七言绝句","c":["海内文章非画师，能回笔力作枯枝。","豫章从小有梁栋，也似郑公双鬓丝。"]},{"t":"题子瞻寺壁小山枯木二首 其一","f":"七言绝句","c":["烂肠五斗对狱吏，白发千丈濯沧浪。","却来献纳云台表，小山桂枝不相忘。"]},{"t":"题子瞻墨竹","f":"七言绝句","c":["眼入毫端写竹真，枝掀叶举是精神。","因知幻物出无象，问取人间老斲轮。"]},{"t":"题小景扇","f":"七言绝句","c":["草色青青柳色黄，桃花零落杏花香。","春风不解吹愁却，春日偏能惹恨长。"]},{"t":"题仁上座画松","f":"七言绝句","c":["偃蹇松枝隔烟雨，知侬定是岁寒材。","百年根节要老硬，将恐崩崖倒石来。"]},{"t":"题太和南塔寺壁","f":"七言绝句","c":["熏炉茶鼎暂来同，寒日鸦啼柿叶风。","万事尽还杯酒里，百年俱在大槐中。"]},{"t":"题文潞公黄河议后","f":"七言绝句","c":["澶渊不作渡河梁，由是中原府库疮。","白首丹心一元老，归来高枕梦河隍。"]},{"t":"题王居士所藏王友画桃杏花二首 其二","f":"七言绝句","c":["凌云见桃万事无，我见杏花心亦如。","从此华山图籍上，更添潘阆倒骑驴。"]},{"t":"题王居士所藏王友画桃杏花二首 其一","f":"七言绝句","c":["凌云一笑见桃花，三十年来始到家。","从此春风春雨后，乱随流水到天涯。"]},{"t":"题王晋卿平远溪山幅","f":"七言绝句","c":["风流子晋罢吹笙，小笔溪山刮眼明。","相倚鸳鸯得偎映，一川风雨断人行。"]},{"t":"题东丁水","f":"七言绝句","c":["古人题作东丁水，自古东丁直到今。","我为改名方响洞，要知山水有清音。"]},{"t":"题归去来图二首 其二","f":"七言绝句","c":["人间处处犹崔子，岂忍更令三径荒。","谁与老翁同避世，桃花源里捕鱼郎。"]},{"t":"题归去来图二首 其一","f":"七言绝句","c":["日日言归真得归，迎门儿女笑牵衣。","宅边犹有旧时柳，漫向世人言昨非。"]},{"t":"题永首座庵颂","f":"七言绝句","c":["夺得胡儿马便休，休嗟李广不封侯。","分明射得南山虎，子细看来是石头。"]},{"t":"题刘氏所藏展子虔感应观音二首 其二","f":"七言绝句","c":["群盗挽弓江簸船，丹青当在普通前。","谁能与作赤挽板，老笔犹堪寿百年。"]},{"t":"题刘氏所藏展子虔感应观音二首 其一","f":"七言绝句","c":["人间犹有展生笔，佛事苍茫烟景寒。","常恐花飞蝴蝶散，明窗一日百回看。"]},{"t":"题刘将军雁二首 其二","f":"七言绝句","c":["将军一矢万人看，雪洒晴空碎羽翰。","乞与失群沙宿雁，笔间千顷暮江寒。"]},{"t":"题刘将军雁二首 其一","f":"七言绝句","c":["滕王蛱蝶双穿花，东丹胡马喷胡沙。","祁连将军一笔雁，生不并世俱名家。"]},{"t":"题竹尊者轩","f":"七言绝句","c":["平生脊骨硬如铁，听风听雨随宜说。","百尺竿头放步行，更向脚跟参一节。"]},{"t":"题邢惇夫扇","f":"七言绝句","c":["黄叶委庭观九州，小虫催女献功裘。","金钱满地无人费，百斛明珠薏苡秋。"]},{"t":"题阳关图二首 其二","f":"七言绝句","c":["人事好乖当语离，龙眠貌出断肠诗。","渭城柳色关何事，自是离人作许悲。"]},{"t":"题阳关图二首 其一","f":"七言绝句","c":["断肠声里无形影，画出无声亦断肠。","想得阳关更西路，北风低草见牛羊。"]},{"t":"题伯时天育骠骑图二首 其二","f":"七言绝句","c":["明窗槃礴万物表，写出人间真乘黄。","邂逅今身犹姓李，可非前世江都王。"]},{"t":"题伯时天育骠骑图二首 其一","f":"七言绝句","c":["玉花照夜今无种，枥上追风亦不传。","想见真龙如此笔，蒺藜沙晚草迷川。"]},{"t":"题伯时画严子陵钓滩","f":"七言绝句","c":["平生久要刘文叔，不肯为渠作三公。","能令汉家重九鼎，桐江波上一丝风。"]},{"t":"题君子泉","f":"七言绝句","c":["云梦泽南君子泉，水无名字托人贤。","两苏翰墨相为重，未刻他山世已传。"]},{"t":"题李夫人偃竹","f":"七言绝句","c":["孤根偃蹇非傲世，劲节癯枝万壑风。","闺中白发翰墨手，落笔乃与天同功。"]},{"t":"题花光老为曾公卷作水边梅","f":"五言绝句","c":["梅蕊触人意，冒寒开雪花。","遥怜水风晚，片片点汀沙。"]},{"t":"题花光画","f":"五言绝句","c":["湖北山无地，湖南水彻天。","云沙真富贵，翰墨小神仙。"]},{"t":"题花光画山水","f":"七言绝句","c":["花光寺下对云沙，欲把轻舟小钓车。","更看道人烟雨笔，乱峰深处是吾家。"]},{"t":"题苏才翁草书壁后","f":"七言绝句","c":["老松不得千年寿，何况高材傲世人。","唯有草书三昧法，龙蛇夭矫锁黄尘。"]},{"t":"题苏若兰回文锦诗图","f":"七言绝句","c":["千诗织就回文锦，如此阳台暮雨何。","亦有英灵苏蕙手，只无悔过窦连波。"]},{"t":"题净因壁二首 其二","f":"七言绝句","c":["门外黄尘不见山，此中草木亦常閒。","履声如度薄冰过，催粥华鲸吼夜阑。"]},{"t":"题净因壁二首 其一","f":"七言绝句","c":["暝倚蒲团挂钵囊，半窗疏箔度微凉。","蕉心不展待时雨，葵叶为谁倾太阳。"]},{"t":"题季张竹林村","f":"七言绝句","c":["百亩清阴十万竿，一溪流水四围山。","太平无用经纶者，乞与闲身向此闲。"]},{"t":"题宗室大年画二首 其二","f":"七言绝句","c":["轻鸥白鹭定吾友，翠柏幽篁是可人。","海角逢春知几度，卧游到处总伤神。"]},{"t":"题宗室大年画二首 其一","f":"七言绝句","c":["水色烟光上下寒，忘机鸥鸟恣飞还。","年来频作江湖梦，对此身疑在故山。"]},{"t":"题画鹅雁二首 其二","f":"五言绝句","c":["水国鸿雁秋，烟沙风日丽。","莫遣角弓鸣，惊飞不成字。"]},{"t":"题画鹅雁二首 其一","f":"五言绝句","c":["鴐鹅引颈回，似我胸中字。","右军数能来，不为口腹事。"]},{"t":"题罗公山古柏庵二首 其二","f":"七言绝句","c":["千年鹿死尚精神，睡足苍龙半屈伸。","百年妖狐住不得，个中曾卧谪仙人。"]},{"t":"题罗公山古柏庵二首 其一","f":"七言绝句","c":["尘埃奔走尚飘蓬，想听庵头老柏风。","会向天阶乞衰晚，住庵长作主人翁。"]},{"t":"题前定录赠李伯牖二首 其二","f":"七言绝句","c":["万般尽被鬼神戏，看取人间傀儡棚。","烦恼自无安脚处，从他鼓笛弄浮生。"]},{"t":"题前定录赠李伯牖二首 其一","f":"七言绝句","c":["五贼追奔十二宫，白头寒士黑头公。","明朝一饭先书籍，安用研桑作老翁。"]},{"t":"题南寺王髯题名处","f":"七言绝句","c":["日华长在红尘外，春色全归绿树中。","花发鸟啼常走马，故人不见酒樽空。"]},{"t":"题觉海寺","f":"七言绝句","c":["炉香滔滔水沈肥，水绕禅床竹绕溪。","一段秋蝉思高柳，夕阳原在竹阴西。"]},{"t":"题晁以道雪雁图","f":"七言绝句","c":["飞雪洒芦如银箭，前雁惊飞后回眄。","凭谁说与谢玄晖，莫道澄湖静如练。"]},{"t":"题海首座壁","f":"五言绝句","c":["骑虎度诸岭，入鸥同一波。","香寒明鼻观，日永称头陀。"]},{"t":"题郭熙山水扇","f":"七言绝句","c":["郭熙虽老眼犹明，便面江山取意成。","一段风烟且千里，解如明月逐人行。"]},{"t":"题惠崇画扇","f":"七言绝句","c":["惠崇笔下开江面，万里晴波向落晖。","梅影横斜人不见，鸳鸯相对浴红衣。"]},{"t":"题落星寺四首 其四","f":"七言绝句","c":["北风吹倒落星寺，吾与伯伦俱醉眠。","螟蛉蜾蠃但痴坐，夜寒南北斗垂天。"]},{"t":"题燕邸洋川公养浩堂画二首 其二","f":"五言绝句","c":["拥膝度残腊，攀条惊早春。","陈郎浮竹叶，著我北归人。"]},{"t":"题燕邸洋川公养浩堂画二首 其一","f":"五言绝句","c":["萧寺吟双竹，秋醪荐二螯。","破尘归骑速，横日雁行高。"]},{"t":"题醒心轩","f":"七言绝句","c":["尽日竹风谈法要，无人竹影又斜阳。","他时若有相应者，莫负开轩人姓黄。"]},{"t":"赠石敏若","f":"七言绝句","c":["才似谪仙惟欠酒，情如宋玉更逢秋。","相看领会一谈胜，注目长江天际流。"]},{"t":"赠刘静翁颂四首 其四","f":"七言绝句","c":["净名庞老总垂须，君幸元无免破除。","心若出家身若住，何须更觅剃头书。"]},{"t":"赠刘静翁颂四首 其三","f":"七言绝句","c":["万缘空处真如佛，八面风中不动尊。","困便横眠饥吃饭，十方无壁又无门。"]},{"t":"赠刘静翁颂四首 其二","f":"七言绝句","c":["一瓶一钵非难办，住得山时更莫来。","千年粪扫堆头物，优钵罗花特地开。"]},{"t":"赠刘静翁颂四首 其一","f":"七言绝句","c":["念念皆空更莫疑，心王本自绝多知。","艰勤长向途中觅，掉却甜桃摘醋梨。"]},{"t":"赠陈元舆祠部","f":"七言绝句","c":["武成园木锁中秋，久得汀州刺史游。","招唤丁宁方邂逅，谁言天网漏吞舟。"]},{"t":"赠法轮齐公","f":"七言绝句","c":["法轮法眷有齐公，曾探斑斑虎穴中。","不必老夫亲到也，自然千里便同风。"]},{"t":"赠嗣直弟颂十首 其十","f":"五言绝句","c":["往日非今日，今年似去年。","九关多虎豹，聊作地行仙。"]},{"t":"赠嗣直弟颂十首 其九","f":"五言绝句","c":["向上关捩子，未曾说似人。","困来一觉睡，妙绝更通神。"]},{"t":"赠嗣直弟颂十首 其八","f":"五言绝句","c":["虽受然灯记，不从然灯得。","若会翻身句，弥勒真弥勒。"]},{"t":"赠嗣直弟颂十首 其七","f":"五言绝句","c":["江南十兄弟，长被时一共。","梦时各自境，独与君同梦。"]},{"t":"赠嗣直弟颂十首 其六","f":"五言绝句","c":["万里唯将我，回观更有谁。","初无卓锥地，今日更无锥。"]},{"t":"赠嗣直弟颂十首 其五","f":"五言绝句","c":["江南鸿雁行，人言好兄弟。","无端风忽起，纵横不成字。"]},{"t":"赠嗣直弟颂十首 其四","f":"五言绝句","c":["涪陵萨埵子，且道也旁行。","亦嚼横陈蜡，不爱孔方兄。"]},{"t":"赠嗣直弟颂十首 其三","f":"五言绝句","c":["正观心地时，丝发亦无有。","却来观世间，冬后数九九。"]},{"t":"赠嗣直弟颂十首 其二","f":"五言绝句","c":["去日撒手去，来时无与偕。","若将来去看，还似不曾斋。"]},{"t":"赠嗣直弟颂十首 其一","f":"五言绝句","c":["饥渴随时用，悲欢触事真。","十方无壁落，中有昔怨人。"]},{"t":"避秦十人","f":"七言绝句","c":["九真承诏上龙胡，尽是骊山所送徒。","惟有邓公留不去，松根支鼎煮菖蒲。"]},{"t":"避暑李氏园二首 其二","f":"七言绝句","c":["荷气竹风宜永日，冰壶凉簟不能回。","题诗未有惊人句，会唤谪仙苏二来。"]},{"t":"避暑李氏园二首 其一","f":"七言绝句","c":["李侯别馆锁春阴，花径吹香可细寻。","迸笋侵阶藤倒架，主人重为费千金。"]},{"t":"魏夫人坛","f":"七言绝句","c":["独扫蛾眉作远山，春风瑶草照朱颜。","我来欲问许玉斧，二十四峰如髻鬟。"]},{"t":"字颂","f":"五言绝句","c":["斋馀睡兀兀，占尽檐前日。","不与一瓯茶，眼前黑如漆。"]},{"t":"二月丁卯喜雨吴体为北门留守文潞公作","f":"七言律诗","c":["乘舆斋祭甘泉宫，遣使骏奔河岳中。","谁与至尊分旰食，北门卧镇司徒公。","微风不动天如醉，润物无声春有功。","三十馀年霖雨手，淹留河外作时丰。"]},{"t":"十二月十九日夜中发鄂渚晓泊汉阳亲旧携酒追送聊为短句","f":"五言律诗","c":["接淅报官府，敢违王事程。","宵征江夏县，睡起汉阳城。","邻里烦追送，杯盘泻浊清。","秪应瘴乡老，难答故人情。"]},{"t":"万州下岩二首 其二","f":"五言律诗","c":["寺古松楠老，岩虚塔庙开。","僧缘蚕麦去，官数荔支来。","石室无心骨，金铺称意苔。","若为刘道者，拽得鼻头回。"]},{"t":"三月壬申同尧民希孝观净名寺经藏得弘明集中沈烱同庾肩吾诸人游明庆寺诗次韵奉呈二公","f":"五言律诗","c":["秘藏开新译，天花雨旧堂。","證经多宝塔，寝疾净名床。","鸟语杂歌颂，蛛丝凝篆香。","同游得赵李，谈道过何王。"]},{"t":"与黔倅张茂宗","f":"七言律诗","c":["静居门巷似乌衣，文采风流众所归。","别乘同来二千石，化民曾寄十三徽。","寒香亭下方遗爱，吏隐堂中已息机。","暂与计司参婉画，百城官吏借光辉。"]},{"t":"卫南","f":"七言律诗","c":["今年畚锸弃春耕，折苇枯荷绕坏城。","白鸟自多人自少，污泥终浊水终清。","沙场旗鼓千人集，渔户风烟一笛横。","惟有鸣鸱古祠柏，对人犹是向时情。"]},{"t":"大秀宫","f":"七言律诗","c":["玉笥山前大白峰，望仙桥下水溶溶。","前溪流水后溪月，五步白云三步松。","半夜佩环朝上阙，插天楼阁度疏钟。","梦馀彷佛钧天奏，如在蓬莱第几重。"]},{"t":"子范徼巡诸乡捕逐群盗几尽辄作长句劳苦行李","f":"七言律诗","c":["白发尉曹能挽弓，著鞭跨马欲生风。","乃兄本是文章伯，此老真成矍铄翁。","枹鼓诸村宵警报，牛羊几处暮牢空。","得公万户开门卧，看取三年治最功。"]},{"t":"中秋","f":"七言律诗","c":["灏气才中兔魄圆，众躔韬彩独娟娟。","魏宫乌绕空枝上，汉苑桐凋露井前。","金液万重涵渤海，玉沙千里对江边。","遥知此夕多情思，三级萧台枕碧涟。"]},{"t":"书睢阳事后","f":"七言律诗","c":["莫道睢阳覆我师，再兴唐祚匪公谁。","流离颠沛义不辱，去就死生心自知。","政使贺兰非长者，岂妨南八是男儿。","乾坤震荡风尘晦，愁绝宗臣陷贼诗。"]},{"t":"予既不得叶遂过洛滨醉游累日","f":"七言律诗","c":["瘿民见我亦悠悠，瘿木累累满道周。","飞舄已随王令化，真龙宁为叶公留。","未能洗耳箕山去，且复吹笙洛浦游。","舍故趋新归有分，令人何处欲藏舟。"]},{"t":"从陈季张求竹竿引水入厨","f":"七言律诗","c":["井边分水过寒厅，斩竹南溪仗友生。","来酿百壶春酒味，怒流三峡夜泉声。","能令官舍庖厨洁，未减君家风月清。","挥斧直须轻放手，却愁食实凤凰惊。"]},{"t":"以同心之言其臭如兰为韵寄李子先 其三","f":"五言律诗","c":["俗士得失重，舍龟观朵颐。","六经成市道，驵侩以为师。","吾学淡如水，载行欲安之。","惟有无心子，白云相与期。"]},{"t":"以同心之言其臭如兰为韵寄李子先 其七","f":"五言律诗","c":["客从济南来，遗我故人书。","墨淡字疏行，故人情有馀。","上言犹健否，次问意何如。","只今意何有，思食故溪鱼。"]},{"t":"劝交代张和父酒","f":"七言律诗","c":["风流五日张京兆，今日诸孙困小官。","作尹大都如广汉，画眉仍复近长安。","三人成虎事多有，众口铄金君自宽。","酒兴情亲俱不浅，贱生何取罄交欢。"]},{"t":"文安国挽词二首 其二","f":"五言律诗","c":["平生翰墨学，空走使臣车。","瞿令能苍史，归公好古书。","秦山刊日月，周鼓颂畋渔。","不见龙蛇笔，新乾研滴蜍。"]},{"t":"王文恭公挽词二首 其二","f":"五言律诗","c":["宥密深黄阁，光辉极上台。","藏舟移夜壑，华屋落泉台。","雨绋谁为挽，寒笳故作哀。","伤心具瞻地，无复衮衣来。"]},{"t":"王文恭公挽词二首 其一","f":"五言律诗","c":["先皇凭玉几，末命寄元勋。","宾日行黄道，攀髯上白云。","四时成岁律，五色补天文。","不谓堂堂去，今为马鬣坟。"]},{"t":"王圣美三子补中广文生","f":"七言律诗","c":["王家人物从来远，今见诸孙总好贤。","三级定知鱼尾进，一鸣已作雁行连。","愧无藻鉴能推毂，愿卷囊书当赠钱。","归去雄誇向儿侄，舍中犊子剩狂颠。"]},{"t":"王彦祖惠其祖黄州制草书其后","f":"五言律诗","c":["脱略看时辈，诸君等发蒙。","董狐常直笔，汲黯少居中。","鵩入迁臣舍，乌号厌世弓。","平生有嘉树，犹起九原风。"]},{"t":"世弼惠诗求舜泉辄欲以长安酥共泛一杯次韵戏答","f":"七言律诗","c":["寒齑薄饭留佳客，蠹简残编作近邻。","避地梁鸿真好学，著书扬子未全贫。","玉酥鍊得三危露，石火烧成一片春。","沙鼎探汤供卯饮，不忧问字绝无人。"]},{"t":"乐寿县君吕氏挽词二首 其二","f":"五言律诗","c":["剪髻宾筵盛，齐眉妇礼闲。","谓宜俱白发，忽去作青山。","大梦惊蝴蝶，何时识佩环。","哀歌行欲绝，丹旐雨斑斑。"]},{"t":"乐寿县君吕氏挽词二首 其一","f":"五言律诗","c":["归装衣楚楚，家世印累累。","来作箕帚妇，不忘蘋藻诗。","居然成万古，何啻谒三医。","骑省还秋直，霜侵鬓脚衰。"]},{"t":"出池藕花","f":"七言律诗","c":["惜丝不肯织宫鞋，花月仙人谪下来。","河伯借泥封玉腕，风神翻浪沃香腮。","无房不许僧归宿，有盖尝令鹭自开。","何事冤他结青女，一朝收拾付尘灰。"]},{"t":"出迎使客质明放船自瓦窑归","f":"七言律诗","c":["鼓吹喧江雨不开，丹枫落叶放船回。","风行水上如云过，地近岭南无雁来。","楼阁人家捲帘幕，菰蒲鸥鸟乐湾洄。","惜无陶谢挥斤手，诗句纵横付酒杯。"]},{"t":"去岁和元翁重到双涧寺观余兄弟题诗之篇总忘收录病中记忆成此诗","f":"七言律诗","c":["素琴声在时能听，白鸟盟寒久未寻。","眼见野僧垂雪发，养亲原不顾朱金。","开泉浸稻双涧水，煨笋充盘春竹林。","安得一廛吾欲老，君听庄舄病时吟。"]},{"t":"去贤斋","f":"七言律诗","c":["争名朝市鱼千里，观道诗书豹一班。","末俗风波尤浩渺，古人廉陛要跻攀。","螗螂怒臂当车辙，鹦鹉能言著锁关。","顾我安知贤者事，松风永日下帘间。"]},{"t":"古风次韵答初和甫二首 其二","f":"七言律诗","c":["君吟春风花草香，我爱春夜璧月凉。","美人美人隔湘水，其雨其雨怨朝阳。","兰荃盈怀报琼玖，冠缨自洁非沧浪。","道人四十心如水，那得梦为胡蝶狂。"]},{"t":"古风次韵答初和甫二首 其一","f":"七言律诗","c":["饥思河鲤与河鲂，渴思蔗浆玉碗凉。","冬愿纯绵对阴雪，夏愿绉絺度盛阳。","万端作计身愁苦，一事不谐鬓苍浪。","调笑天街吟海燕，藜羹脱粟非公狂。"]},{"t":"古渔父","f":"七言律诗","c":["穷秋漫漫蒹葭雨，裋褐休休白发翁。","范子归来思狡兔，吕公何意兆非熊。","渔收亥日妻到市，醉卧水痕船信风。","四海租庸人草草，太平长在碧波中。"]},{"t":"史天休中散挽词","f":"七言律诗","c":["光禄九男君独秀，赋名几与景仁班。","淹留州县看恬默，出入风波笑险艰。","遗爱蜀中三郡有，退身林下十年閒。","山川英气消磨尽，昨日华堂作土山。"]},{"t":"司马文正公挽词四首 其四","f":"五言律诗","c":["毁誉盖棺了，于今名实尊。","哀荣有王命，终始酌民言。","蝉冕三公府，深衣独乐园。","公心两无累，忧国爱元元。"]},{"t":"司马文正公挽词四首 其三","f":"五言律诗","c":["献纳无虚日，居然迹已陈。","清班区玉石，宝历顺星辰。","更化思鸣鵙，遗书似获麟。","易名无异论，今代两三人。"]},{"t":"司马文正公挽词四首 其二","f":"五言律诗","c":["国在多艰日，人如大雅诗。","忠清俱没世，孝友是生知。","加璧延诸老，櫜弓抚四夷。","公身与宗社，同作太平基。"]},{"t":"司马文正公挽词四首 其一","f":"五言律诗","c":["元祐开皇极，功归用老成。","惟深万物表，不令四时行。","日者倾三接，天乎奠两楹。","堂堂宁复有，埋玉恸佳城。"]},{"t":"四月末天气陡然如秋遂御袷衣游北沙亭观江涨","f":"七言律诗","c":["沙岸人家报急流，船官解缆正夷犹。","震雷将雨度绝壑，远水粘天吞钓舟。","甚欲去挥白羽箑，可堪更着紫茸裘。","平生得意无人会，浩荡舂锄且自由。"]},{"t":"用几复韵题伯氏思堂","f":"七言律诗","c":["夫子勤于蘧伯玉，洗心观道得灵龟。","开门择友尽三益，清坐不言行四时。","风与蛛丝游碧落，日将槐影下隆墀。","天空地迥何处觅，岁计有馀心自知。"]},{"t":"用明发不寐有怀二人为韵寄李秉彝德叟 其八","f":"五言律诗","c":["桃李春成径，本自不期人。","历下两寒士，箪瓢能悦亲。","耻蒙伐国问，肯卧覆车尘。","子既得此友，从之求日新。"]},{"t":"用明发不寐有怀二人为韵寄李秉彝德叟 其一","f":"五言律诗","c":["竹贯四时清，月通云气明。","外弟有佳质，妙年推老成。","后凋对霜雪，不昧处阴晴。","盛德当如此，古人畏后生。"]},{"t":"用明发不寐有怀二人为韵寄李秉彝德叟 其五","f":"五言律诗","c":["往在舅氏旁，获拚堂上帚。","六经观圣人，明如夜占斗。","索居废旧闻，独学无新有。","羡子杞梓材，未曾离矫揉。"]},{"t":"光山道中","f":"七言律诗","c":["客子空知行路难，中田耕者自高闲。","柳条莺啭清阴里，楸树蝉嘶翠带间。","梦幻百年随逝水，劳歌一曲对青山。","出门捧檄羞闲友，归寿吾亲得解颜。"]},{"t":"再次韵","f":"五言律诗","c":["穷奇投有北，鸿鹄止丘隅。","我已魑魅禦，君方燕雀俱。","道应无蒂芥，学要尽工夫。","莫斩猿狙杙，明堂待栋桴。"]},{"t":"再次韵戏赠道夫","f":"五言律诗","c":["名教自乐地，思君相与娱。","囊锥见末疾，椟玉待时沽。","雨歇鸣鸠树，薰销睡鸭炉。","不来应梦起，子学□啼歈。"]},{"t":"再次韵和吉老","f":"七言律诗","c":["今日仆姑晴自语，愁阴前日雪铺床。","三冬一雨禾头湿，百斛几痕牛领疮。","民欲与翁归作腊，公方无事可开场。","相勤冻坐真成恶，愧我偷閒饱太仓。"]},{"t":"再次韵奉答子由","f":"七言律诗","c":["虿尾银钩写珠玉，剡藤蜀茧照松烟。","似逢海若谈秋水，始觉醯鸡守瓮天。","何日清扬能觌面，只今黄落又凋年。","万钱买酒从公醉，一钵行歌听我颠。"]},{"t":"再次韵兼简履中南玉三首 其三","f":"七言律诗","c":["锁江亭上一樽酒，山自白云江自横。","李侯短褐有长处，不与俗物同条生。","经术貂蝉续狗尾，文章瓦釜作雷鸣。","古来寒士但守节，夜夜抱关听五更。"]},{"t":"再次韵寄子由","f":"七言律诗","c":["想见苏耽携手仙，青山桑柘冒寒烟。","骐驎堕地思千里，虎豹憎人上九天。","风雨极知鸡自晓，雪霜宁与菌争年。","何时确论倾樽酒，医得儒生自圣颠。"]},{"t":"再和寄蓝六","f":"七言律诗","c":["南极一星淮上老，承家令子气横秋。","万端只要称心耳，五鼎何如委吏优。","海燕催归人作社，江花欲动雨含愁。","追思二十年前会，棠棣飘零叹鄂不。"]},{"t":"再赠陈季张拒霜花二首 其一","f":"七言律诗","c":["鼓盆庄叟赋情浓，天遣霜华慰此公。","想见尚能迷蝶梦，移栽闻说自蚕丛。","酒倾玉盏垂莲尽，鲙簇金盘下箸空。","秉烛栏边连夜饮，全藤折与卖花翁。"]},{"t":"再赠陈季张拒霜花二首 其二","f":"七言律诗","c":["倒著接䍦吾素风，当时酩酊似山公。","且看小槛新花蕊，休泥他家晚菊丛。","顾笑千金延客醉，解酲五斗为君空。","欢娱尽属少年事，白发欺人作老翁。"]},{"t":"冲雪宿新寨忽忽不乐","f":"七言律诗","c":["县北县南何日了，又来新寨解征鞍。","山衔斗柄三星没，雪共月明千里寒。","小吏有时须束带，故人颇问不休官。","江南长尽捎云竹，归及春风斩钓竿。"]},{"t":"吉老受秋租辄成长句","f":"七言律诗","c":["黄花事了绿丛霜，蟋蟀催寒夜夜床。","爱日捃收如盗至，失时鞭扑奈民疮。","田夫田妇肩赪担，江北江南稼涤场。","少忍飞糠眯君眼，要令私廪上公仓。"]},{"t":"同子瞻和赵伯充团练","f":"七言律诗","c":["金玉堂中寂寞人，仙班时得共朝真。","两宫无事安磐石，万国归心有老臣。","家酿可供开口笑，侍儿工作捧心颦。","醉乡乃是安身处，付与升平作幸民。"]},{"t":"同孙不愚过昆阳","f":"七言律诗","c":["田园恰恰值春忙，驱马悠悠昆水阳。","古庙藤萝穿户牖，断碑风雨碎文章。","真人寂寞神为社，坚垒委蛇女采桑。","拂帽村帘誇酒好，为君聊解一瓢尝。"]},{"t":"同韵和元明兄知命弟九日相忆二首 其二","f":"七言律诗","c":["万水千山厌问津，芭蕉林里自观身。","邻田鸡黍留熊也，风雨关河走阿秦。","鸿雁池边照双影，脊令原上忆三人。","年年献寿须欢喜，白发黄花映角巾。"]},{"t":"同韵和元明兄知命弟九日相忆二首 其一","f":"七言律诗","c":["革囊南渡传诗句，摹写相思意象真。","九日黄花倾寿酒，几回青眼望归尘。","蚤为学问文章误，晚作东西南北人。","安得田园可温饱，长抛簪绂裹头巾。"]},{"t":"孙不愚引开元故事请为移春槛因而赠答","f":"七言律诗","c":["南陌东城处处春，不须移槛损天真。","鬓毛欲白休辞饮，风雨无端只误人。","鸟语提壶元自好，酒狂惊俗未应嗔。","稍寻绿树为诗社，更藉残红作醉茵。"]},{"t":"孙不愚索饮九日酒已尽戏答一篇","f":"七言律诗","c":["满眼黄花慰索贫，可怜风物逐时新。","范丹出后尘生釜，郭泰归来雨垫巾。","偶有清樽供寿母，遂无馀沥及他人。","年丰酒价应须贱，为子明年作好春。"]},{"t":"戏书效乐天","f":"七言律诗","c":["造物生成嵇叔懒，好人容纵接舆狂。","鸟飞鱼泳随高下，蚁集蜂衙听典常。","母惜此儿长道路，兄嗟予弟困冰霜。","酒壶自是华胥国，一醉从他四大忙。"]},{"t":"戏咏江南土风","f":"七言律诗","c":["十月江南未得霜，高林残水下寒塘。","饭香猎户分熊白，酒熟渔家擘蟹黄。","橘摘金苞随驿使，禾舂玉粒送官仓。","踏歌夜结田神社，游女多随陌上郎。"]},{"t":"戏题葆真阁","f":"七言律诗","c":["真常自在如来性，肯綮修持祗益劳。","十二因缘无妙果，三千世界起秋毫。","有心便醉声闻酒，空手须磨般若刀。","截断众流寻一句，不离兔角与龟毛。"]},{"t":"戏赠水牯庵","f":"七言律诗","c":["水牯从来犯稼苗，著绳只要鼻穿牢。","行须万里无寸草，卧对十方同一槽。","租税及时王事了，云山横笛月轮高。","华亭浪说吹毛剑，不见全牛可下刀。"]},{"t":"戏赠南安倅柳朝散","f":"七言律诗","c":["柳侯风味晚相见，衣袂颇薰荀令香。","桃李能言妙歌舞，樽前一曲断人肠。","洞庭归客有佳句，庾岭梅花如小棠。","乘兴高帆少相待，淮湖秋月要传觞。"]},{"t":"戏赠顿二主簿","f":"七言律诗","c":["桐植客亭欣款曲，歌倾家酿勿徘徊。","百年中半夜分去，一岁无多春暂来。","落日园林须秉烛，能言桃李听传杯。","红疏绿暗明朝是，公事相过得几回。"]},{"t":"戏赠惠南禅师","f":"七言律诗","c":["佛子禅心若苇林，此门无古亦无今。","庭前柏树祖师意，竿上风幡仁者心。","草木同沾甘露味，人天倾听海潮音。","胡床默坐不须说，拨尽寒灰劫数深。"]},{"t":"杂吟","f":"五言律诗","c":["城中蛾眉女，珂佩响珊珊。","鹦鹉花间弄，琵琶月下弹。","长歌三日绕，短舞万人看。","未必长如此，芙蓉不耐寒。"]},{"t":"次元明韵寄子由","f":"七言律诗","c":["半世交亲随逝水，几人图画入凌烟。","春风春雨花经眼，江北江南水拍天。","欲解铜章行问道，定知石友许忘年。","脊令各有思归恨，日月相催雪满颠。"]},{"t":"次韵几复和答所寄","f":"七言律诗","c":["海南海北梦不到，会合乃非人力能。","地褊未堪长袖舞，夜寒空对短檠灯。","相看鬓发时窥镜，曾共诗书更曲肱。","作个生涯终未是，故山松长到天藤。"]},{"t":"次韵几复答予所赠三物三首 其三 石刻","f":"五言律诗","c":["九原谁复起，糟魄未传心。","不取丁仪米，疑成校尉金。","名从高位借，德有下僚沈。","笔削多瑕点，犹希畏友箴。"]},{"t":"次韵几复答予所赠三物三首 其一 石灯檠","f":"五言律诗","c":["谁怜湖海士，白发夜窗檠。","风雨鸡不已，诗书眼尚明。","禅枝安宿鸟，僧粥吼华鲸。","但满五车读，行看一座倾。"]},{"t":"次韵几复答予所赠三物三首 其二 石博山","f":"五言律诗","c":["绝域蔷薇露，他山菡萏炉。","薰衣作家想，伏枕梦闺姝。","游子官蚁穴，谪仙居瓠壶。","当时有忧乐，回首亦成无。"]},{"t":"次韵十九叔父台源","f":"五言律诗","c":["闻道台源境，锄荒三径通。","人曾梦蚁穴，鹤亦怕鸡笼。","万壑秋声别，千江月体同。","须知有一路，不在白云中。"]},{"t":"次韵子高即事","f":"七言律诗","c":["诗礼不忘它日问，文章未觉古人疏。","青云自致屠龙学，白首同归种树书。","绿叶青阴啼鸟下，游丝飞絮落花馀。","无因常得杯中物，愿作鸱夷载属车。"]},{"t":"次韵子瞻题无咎所得与可竹二首粥字韵戏嘲无咎人字韵咏竹 其二","f":"五言律诗","c":["地下文夫子，风流绝此人。","能和晚烟色，幻出岁寒身。","马鬣松成拱，鹅溪墨尚新。","应怀斲泥手，去作主林神。"]},{"t":"次韵马荆州","f":"七言律诗","c":["六年绝域梦刀头，判得南还万事休。","谁谓石渠刘校尉，来依绛帐马荆州。","霜髭雪鬓共看镜，茱糁菊英同送秋。","他日江梅腊前破，还从天际望归舟。"]},{"t":"次韵元日","f":"七言律诗","c":["会朝四海登图籍，绛阙清都想盛容。","春色已知回寸草，霜威从此霁寒松。","饮如嚼蜡初忘味，事与浮云去绝踪。","四十九年蘧伯玉，圣人门户见重重。"]},{"t":"次韵元翁从王夔玉借书","f":"七言律诗","c":["为吏三年弄文墨，草莱心径失耕锄。","常思天下无双祖，得读人间未见书。","公子藏山真富有，小儒扪腹正空虚。","何时管钥入吾手，为理签题扑蠹鱼。"]},{"t":"次韵公定世弼登北都东楼四首 其四","f":"五言律诗","c":["汉皇勤远略，晚节相千秋。","不足中原地，犹思一战收。","圣朝方北顾，斜日倚东楼。","庙算知无敌，寒儒浪自愁。"]},{"t":"次韵公定世弼登北都东楼四首 其三","f":"五言律诗","c":["都城碍飞鸟，军幕卧貔貅。","紫葚知蚕老，黄云见麦秋。","接天双阙起，伏地九河流。","耆老深望幸，銮舆不好游。"]},{"t":"次韵公定世弼登北都东楼四首 其二","f":"五言律诗","c":["真皇多庙胜，仁祖用功深。","卜宅迁九鼎，破胡藏万金。","百年休战士，当日纵前禽。","欲断匈奴臂，不如留此心。"]},{"t":"次韵公定世弼登北都东楼四首 其一","f":"五言律诗","c":["日著阑干角，风吹濯浣衣。","喜同王季哲，更得谢玄晖。","清兴俱不浅，长吟无用归。","月明南北道，犹见驿尘飞。"]},{"t":"次韵少激甘露降太守居桃叶上","f":"七言律诗","c":["金茎甘露荐斋房，润及边城草木香。","蕡实叶间天与味，成蹊枝上月翻光。","群心爱戴葵倾日，万事驱除叶陨霜。","玉烛时和君会否，旧臣重叠起南荒。"]},{"t":"次韵文少激祈雨有感","f":"七言律诗","c":["穷儒忧乐与民同，何况朱轮职劝农。","终日齑盐供一饭，几时肤寸冒千峰。","未须丘垤占鸣鹳，只要朝廷起卧龙。","从此滂沱遍枯槁，爱民天子似仁宗。"]},{"t":"次韵文潜休沐不出二首 其二","f":"五言律诗","c":["与世自少味，闭关非有心。","戎葵一笑粲，露井百尺深。","著书洒风雨，枯笔束如林。","苏公叹妙墨，逼人太骎骎。"]},{"t":"次韵文潜休沐不出二首 其一","f":"五言律诗","c":["风尘车马逐，得失两关心。","惟有张仲蔚，门前蓬藋深。","自公及归沐，毕愿诗书林。","墙东作瘦马，万里气骎骎。"]},{"t":"次韵王定国扬州见寄","f":"七言律诗","c":["清洛思君昼夜流，北归何日片帆收。","未生白发犹堪酒，垂上青云却佐州。","飞雪堆盘鲙鱼腹，明珠论斗煮鸡头。","平生行乐自不恶，岂有竹西歌吹愁。"]},{"t":"次韵外舅喜王正仲三丈奉诏祷南岳回至襄阳舍驿马就舟见过三首 其二","f":"七言律诗","c":["能来问疾好音传，蹇步昏花当日痊。","烹鲤得书增目力，呼儿扶立候门前。","游谈取重惭犀首，居物多赢昧计然。","惟有交亲等金石，白头忘义复忘年。"]},{"t":"次韵外舅喜王正仲三丈奉诏祷南岳回至襄阳舍驿马就舟见过三首 其三","f":"七言律诗","c":["语言少味无阿堵，冰雪相看有此君。","灯火诗书如梦寐，麒麟图画属浮云。","平章息女能为妇，欢喜儿曹解缀文。","忧乐同科惟石友，别离空复数朝曛。"]},{"t":"次韵汉公招七兄","f":"七言律诗","c":["白发霏霏雪点斑，朱樱忽忽鸟衔残。","公庭休吏进汤饼，语燕无人窥井栏。","诗句多传知有暇，道人相见不应难。","老郎亲屈延处士，风味依稀如姓桓。"]},{"t":"次韵任君官舍秋雨","f":"七言律诗","c":["墙根戢戢数蜗牛，雨长垣衣亭更幽。","惊起归鸿不成字，辞柯落叶最知秋。","菊花莫恨开时晚，谷穟犹思晴后收。","独立搔头人不解，南山用取一樽酬。"]},{"t":"次韵任道雪中同游东皋之作","f":"五言律诗","c":["四海方嗷嗷，我奔走独劳。","停舟近北渚，扶杖步东皋。","霜落瘦石骨，水涨腐溪毛。","更有山阴兴，能无秦复陶。"]},{"t":"次韵刘景文登邺王台见思五首 其五","f":"五言律诗","c":["公诗如美色，未嫁已倾城。","嫁作荡子妇，寒机泣到明。","绿琴蛛网遍，弦绝不成声。","想见鸱夷子，江湖万里情。"]},{"t":"次韵刘景文登邺王台见思五首 其四","f":"五言律诗","c":["茗花浮曾坑，酒泛酌宜城。","路寻西九曲，人似汉三明。","千户非无相，五言空有声。","何时郭池晚，照影写閒情。"]},{"t":"次韵刘景文登邺王台见思五首 其三","f":"五言律诗","c":["系匏两相忆，极目十馀城。","积潦干斗极，山河皆夜明。","白璧按剑起，朱弦流水声。","乖逢四时尔，木石了无情。"]},{"t":"次韵刘景文登邺王台见思五首 其二","f":"五言律诗","c":["旧时刘子政，憔悴邺王城。","把笔已头白，见书犹眼明。","平原秋树色，沙麓暮钟声。","归雁南飞尽，无因寄此情。"]},{"t":"次韵刘景文登邺王台见思五首 其一","f":"五言律诗","c":["黄浊归大壑，涟漪绕重城。","西风一横笛，金气与高明。","归鸦度晚景，落雁带边声。","平生知音处，别离空复情。"]},{"t":"次韵吉老知命同游青原二首 其二","f":"五言律诗","c":["至人来有会，吾道本无家。","阅世鱼行水，遗书鸟印沙。","斋盂香佛饭，法席雨天花。","时有清谈胜，还同叹永嘉。"]},{"t":"次韵吉老知命同游青原二首 其一","f":"五言律诗","c":["洗钵寻思去，论诗匡鼎来。","鸦窥锡处井，鱼泳钓时台。","垂足收亲子，存身亘劫灰。","僧雏手金钥，一为道人开。"]},{"t":"次韵吉老寄君庸","f":"七言律诗","c":["何郎生事四立壁，心地高明百不忧。","白眼醉来思阮籍，碧云吟罢对汤休。","诸公著力书交上，尺璧深藏价未酬。","空使君如巢幕燕，将雏处处度春秋。"]},{"t":"次韵师厚雨中昼寝忆江南饼曲酒","f":"五言律诗","c":["雨砌无车马，风帘洒静便。","忽思江外酒，准拟醉时眠。","隐几惟观化，开书屡绝编。","遥知烟渚梦，遣骑唤渔船。"]},{"t":"次韵师厚萱草","f":"五言律诗","c":["从来占北堂，雨露借恩光。","与菊乱佳色，共葵倾太阳。","人生真苦相，物理忌孤芳。","不及空庭草，荣衰可两忘。"]},{"t":"次韵戏答彦和","f":"七言律诗","c":["本不因循老镜春，江湖归去作閒人。","天于万物定贫我，智效一官全为亲。","布袋形骸增碨磊，锦囊诗句愧清新。","杜门绝俗无行迹，相忆犹当遣化身。"]},{"t":"次韵伯氏戏赠韩正翁菊花开时家有美酒","f":"七言律诗","c":["鬓发斑然潘骑省，腰围瘦尽沈东阳。","茶瓯屡煮龙山白，酒椀希逢若下黄。","乌角巾边簪钿朵，红银杯面冻糖霜。","会须著意怜时物，看取年华不久芳。"]},{"t":"次韵伯氏寄赠盖郎中喜学老杜诗","f":"七言律诗","c":["老杜文章擅一家，国风纯正不攲斜。","帝阍悠邈开关键，虎穴深沈探爪牙。","千古是非存史笔，百年忠义寄江花。","潜知有意升堂室，独抱遗编校舛差。"]},{"t":"次韵伯氏谢安石塘莲花酒","f":"七言律诗","c":["花蕊芙蕖拍酒醇，浮蛆相乱菊英新。","寒光欲涨红螺面，烂醉从歌白鹭巾。","行乐衔杯常有意，过门问字久无人。","王孙欲遣双壶到，如入醉乡三月春。"]},{"t":"次韵君庸寓慈云寺待韶惠钱不至","f":"七言律诗","c":["主簿看梅落雪中，闺人应赋首飞蓬。","问安儿女音书少，破笑壶觞梦寐同。","马祖峰前青未了，郁孤台下水如空。","江山信美思归去，听我劳歌亦欲东。"]},{"t":"次韵宋懋宗三月十四日到西池都人盛观翰林公出遨","f":"七言律诗","c":["金狨系马晓莺边，不比春江上水船。","人语车声喧法曲，花光楼影倒晴天。","人间化鹤三千岁，海上看羊十九年。","还作遨头惊俗眼，风流文物属苏仙。"]},{"t":"次韵宋懋宗僦居甘泉坊雪后书怀","f":"七言律诗","c":["汉家太史宋公孙，漫逐班行谒帝阍。","燕颔封侯空有相，蛾眉倾国自难昏。","家徒四壁书侵坐，马瘦三山叶拥门。","安得风帆随雪水，江南石上对洼尊。"]},{"t":"次韵张昌言给事喜雨","f":"七言律诗","c":["三雨全清六合尘，诗翁喜雨句凌云。","垤漂战蚁馀追北，柱击乖龙有裂文。","减去鲜肥忧玉食，遍宗河岳起炉薰。","圣功惠我丰年食，未有涓埃可报君。"]},{"t":"次韵张秘校喜雪三首 其三","f":"七言律诗","c":["满城楼观玉阑干，小雪晴时不共寒。","润到竹根肥腊笋，暖开蔬甲助春盘。","眼前多事观游少，胸次无忧酒量宽。","闻说压沙梨已动，会须鞭马蹋泥看。"]},{"t":"次韵张秘校喜雪三首 其二","f":"七言律诗","c":["巷深朋友稀来往，日晏儿童不扫除。","雪里正当梅腊尽，民饥可待麦秋无。","寒生短棹谁乘兴，光入疏棂我读书。","官冷无人供美酒，何时却得步兵厨。"]},{"t":"次韵张秘校喜雪三首 其一","f":"七言律诗","c":["落月烟沙静渺然，好风吹雪下平田。","琼瑶万里酒增价，桂玉一炊人少钱。","学子已占秋食麦，广文何憾客无毡。","睡馀强起还诗债，腊里春初未隔年。"]},{"t":"次韵杨君全送酒","f":"七言律诗","c":["扶衰却老世无方，惟有君家酒未尝。","秋入园林花老眼，茗搜文字响枯肠。","榨头夜雨排檐滴，杯面春风绕鼻香。","不待澄清遣分送，定知佳客对空觞。"]},{"t":"次韵杨明叔四首 其四","f":"五言律诗","c":["匹士能光国，三孱不满隅。","窃观今日事，君与古人俱。","气类莺求友，精诚石望夫。","雷门震惊手，待汝一援桴。"]},{"t":"次韵杨明叔四首 其三","f":"五言律诗","c":["全德备万物，大方无四隅。","身随腐草化，名与太山俱。","道学归吾子，言诗起老夫。","无为蹈东海，留作济川桴。"]},{"t":"次韵杨明叔四首 其二","f":"五言律诗","c":["道常无一物，学要反三隅。","喜与嗔同本，嗔时喜自俱。","心随物作宰，人谓我非夫。","利用兼精义，还成到岸桴。"]},{"t":"次韵杨明叔四首 其一","f":"五言律诗","c":["鱼去游濠上，鸮来止坐隅。","吉凶终我在，忧乐与生俱。","决定不是物，方名大丈夫。","今观由也果，老子欲乘桴。"]},{"t":"次韵陈荣绪同倚钟楼晚望别后明日见寄之作","f":"五言律诗","c":["天外僧伽塔，斜辉极照临。","凭栏随处好，残雪向来深。","青草无风浪，枯松半死心。","衡阳有回雁，他日更传音。"]},{"t":"次韵和台源诸篇九首 其二 七台峰","f":"七言律诗","c":["欲雕佳句累层峦，深愧挥斤斲鼻端。","作者七人俱老大，昂藏却立古衣冠。","千年避世朝市改，万籁入松溪涧寒。","我有号钟锁蛛网，何时对汝发清弹。"]},{"t":"次韵和台源诸篇九首 其六 仙桥洞","f":"七言律诗","c":["横阁晴虹渡石溪，几年钥锁镇瑶扉。","洞中日月真长久，世上功名果是非。","叱石元知牧羊在，烂柯应有看棋归。","若逢白鹤来华表，识取当年丁令威。"]},{"t":"次韵和台源诸篇九首 其五 灵寿台","f":"七言律诗","c":["藤树谁知先后生，万年相倚共枯荣。","层台定自有天地，鼻祖已来传父兄。","虎豹文章藏雾雨，龙蛇头角听雷声。","何时暂取苍烟策，献与本朝优老成。"]},{"t":"次韵和台源诸篇九首 其一 南屏山","f":"七言律诗","c":["襞积蓝光刻削成，主人题作正南屏。","身更万事已头白，相对百年终眼青。","烟雨数峰当隐几，林塘一带是中庭。","红尘车马无因到，石壁松门本不扃。"]},{"t":"次韵和台源诸篇九首 其九 群玉峰","f":"七言律诗","c":["洞天名籍知第几，洞口诸峰苍翠堆。","彫虎啸风斤斧去，飞廉吹雨晓烟回。","日晴圭角升云气，月冷明珠割蚌胎。","种玉田中饱春笋，仙人忆得早归来。"]},{"t":"次韵奉和仲谟夜话唐史","f":"七言律诗","c":["贞观规摹诚远大，开元宗社半存亡。","才闻冠盖游西蜀，又见干戈暗洛阳。","哲妇乘时倾嫡后，大阍当国定储皇。","伤心不忍前朝事，愿作元龟献未央。"]},{"t":"次韵奉答文少激推官纪赠二首 其二","f":"七言律诗","c":["文章藻鉴随时去，人物权衡逐势低。","扬子墨池春草遍，武侯祠庙晓莺啼。","书帷寂寞知音少，幕府留连要路迷。","顾我何人敢推挽，看君桃李合成蹊。"]},{"t":"次韵奉答文少激推官纪赠二首 其一","f":"七言律诗","c":["诗来清吹拂衣巾，句法词锋觉有神。","今日相看青眼旧，他年肯作白头新。","文如雾豹容窥管，气似灵犀可辟尘。","惭愧相期在台省，无心枯木岂能春。"]},{"t":"次韵奉答吉邻机宜","f":"七言律诗","c":["黠虏乘秋屡合围，上书公独请偏师。","庭中子弟芝兰秀，塞上威名草木知。","千里折冲深寄此，三衙虚席看除谁。","与公相见清班在，仁祖重来筑旧基。"]},{"t":"次韵奉答存道主簿","f":"七言律诗","c":["主簿朝衣如败荷，高怀千尺上松萝。","旅人争席方归去，秋水黏天不自多。","学到会时忘粲可，诗留别后见羊何。","向来四海习凿齿，今日期君不啻过。"]},{"t":"次韵奉答廖袁州怀旧隐之诗","f":"七言律诗","c":["诗题怨鹤与惊猿，一幅溪藤照麝烟。","闻道省郎方结绶，可容名士乞归田。","严安召见天嗟晚，贾谊归来席更前。","何况班家有超固，应封定远勒燕然。"]},{"t":"次韵奉酬刘景文河上见寄","f":"七言律诗","c":["省中岑寂坐云窗，忽有归鸿拂建章。","珍重多情惟石友，琢磨佳句问潜郎。","遥怜部曲风沙里，不废平生翰墨场。","想见哦诗煮春茗，向人怀抱绝关防。"]},{"t":"次韵知命入青原山口","f":"五言律诗","c":["坑路羊肠绕，稻田棋局方。","林间塔馀寸，风外竹斜行。","吠客犬反走，惊人鸟坌忙。","山形与祖印，岑绝两相当。"]},{"t":"次韵舍弟喜雨","f":"七言律诗","c":["时雨真成大有年，斯民沟壑救将然。","麦根肥润桑叶大，春垄未锄蚕未眠。","奔走风雨连晓色，起寻佳句写由拳。","李成六幅骤雨笔，挂在东南楼阁前。"]},{"t":"次韵雨丝云鹤二首 其二","f":"七言律诗","c":["几片云如薛公鹤，精神态度不曾齐。","安知陇鸟樊笼密，便觉南鹏羽翼低。","风散又成千里去，夜寒应上九天栖。","坐来改变如苍狗，试欲挥毫意自迷。"]},{"t":"次韵雨丝云鹤二首 其一","f":"七言律诗","c":["烟云杳霭合中稀，雾雨空濛密更微。","园客茧丝抽万绪，蛛蝥网面罩群飞。","风光错综天经纬，草木文章帝杼机。","愿染朝霞成五色，为君王补坐朝衣。"]},{"t":"次韵庭诲按秋课出城","f":"五言律诗","c":["风鸣落意地，露著晚瓜田。","官道奔车气，经家煮枣烟。","穫人歌挃挃，公子骑翩翩。","旁舍末隐举，明秋愿有年。"]},{"t":"次韵春游别说道二首 其二","f":"五言律诗","c":["青春倚江阁，万象客愁中。","江水不胜绿，檐花无赖红。","攲斜半帘日，留滞一帆风。","携手离筵上，清樽不易空。"]},{"t":"次韵春游别说道二首 其一","f":"五言律诗","c":["愁眼看春色，城西醉梦中。","柳分榆荚翠，桃上竹梢红。","燕湿社翁雨，莺啼花信风。","别离感贫贱，殷子正书空。"]},{"t":"次韵柳通叟寄王文通","f":"七言律诗","c":["故人昔有凌云赋，何意陆沈黄绶间。","头白眼花行作吏，儿婚女嫁望还山。","心犹未死杯中物，春不能朱镜里颜。","寄语诸公肯湔祓，割鸡今得近乡关。"]},{"t":"次韵胡彦明同年羁旅京师寄李子飞三章一章道其困穷二章劝之归三章言我亦欲归耳胡李相甥也故有槟榔之句 其二","f":"七言律诗","c":["丁未同升乡里贤，别离寒暑未推迁。","萧条羁旅深穷巷，蚤晚声名上细毡。","碧嶂清江原有宅，白鱼黄雀不论钱。","槟榔一斛何须得，李氏弟兄佳少年。"]},{"t":"次韵胡彦明同年羁旅京师寄李子飞三章一章道其困穷二章劝之归三章言我亦欲归耳胡李相甥也故有槟榔之句 其一","f":"七言律诗","c":["看除日月坐中铨，一岁应无官九迁。","葱韭盈盘市门食，诗书满枕客床毡。","留连节物孤朋酒，恼乱邻翁谒子钱。","谁料丹徒布衣得，困穷且忍试新年。"]},{"t":"次韵胡彦明同年羁旅京师寄李子飞三章一章道其困穷二章劝之归三章言我亦欲归耳胡李相甥也故有槟榔之句 其三","f":"七言律诗","c":["畏人重禄难堪忍，阅世浮云易变迁。","徐步当车饥当肉，锄头为枕草为毡。","原无马上封侯骨，安用人间使鬼钱。","不是朱门争底事，清溪白石可忘年。"]},{"t":"次韵闻善","f":"五言律诗","c":["扶醉三竿日，题诗一研埃。","张罗门带雪，投辖井生苔。","待得成丘陇，谁能把酒杯。","常应黄菊畔，怅望白衣来。"]},{"t":"次韵秦少章晁适道赠答诗","f":"五言律诗","c":["二子论文地，阴风雪塞庐。","宁穿东郭履，不遗子公书。","士固难推挽，时闻有诏除。","负暄真得计，献御恐成疏。"]},{"t":"次韵郭右曹","f":"七言律诗","c":["阅世行将老斲轮，那能不朽见仍云。","岁中日月又除尽，圣处工夫无半分。","秋水寒沙鱼得计，南山浓雾豹成文。","古心自有著鞭地，尺璧分阴未当勤。"]},{"t":"次韵郭明叔登县楼见思长句","f":"七言律诗","c":["令尹登临多暇日，杖生芝菌笔生埃。","溪横凤尾寒光去，山拥旌阳翠气来。","晚市张灯明远近，□□留客舞徘徊。","红裳珠履知多在，点检惟无□秀才。"]},{"t":"次韵高子勉十首 其十","f":"五言律诗","c":["沙上步微暖，思君剩欲招。","蒌蒿穿雪动，杨柳索春饶。","枉驾时逢出，新诗若见撩。","樽前远湖树，来饮莫辞遥。"]},{"t":"次韵高子勉十首 其九","f":"五言律诗","c":["少年基一篑，长岁足三馀。","忽作飞黄去，顿超同队鱼。","尊前八采句，窗下十年书。","定作牛腰束，传抄听小胥。"]},{"t":"次韵高子勉十首 其八","f":"五言律诗","c":["凿开混沌窍，窥见伏羲心。","有物先天地，含生尽陆沈。","伐山成大厦，鼓橐铸祥金。","三尺无弦木，期君发至音。"]},{"t":"次韵高子勉十首 其七","f":"五言律诗","c":["志士难推毂，将如高子何。","心期诚不浅，馀论或相多。","欲向沧洲去，还能小艇么。","鸬鹚西照处，相并晒渔蓑。"]},{"t":"次韵高子勉十首 其五","f":"五言律诗","c":["荆渚楼中赋，南阳垄底吟。","谁言小隐处，频屈故人临。","经笥难窥底，词源幸汲深。","思君眠竹屋，雪月冰寒衾。"]},{"t":"次韵高子勉十首 其四","f":"五言律诗","c":["君不居郎省，还应上谏坡。","才高殊未识，岁晚喜无它。","枥马羸难出，邻鸡冻不歌。","寒炉馀几火，灰里拨阴何。"]},{"t":"次韵高子勉十首 其三","f":"五言律诗","c":["岘南羁旅井，灞上猎归亭。","日绕分鱼市，风回落雁汀。","笔由诗客把，笛为故人听。","但恐苏耽鹤，归时或姓丁。"]},{"t":"次韵高子勉十首 其二","f":"五言律诗","c":["扫雪我三日，御风君过旬。","言诗今有数，下笔不无神。","行布佺期近，飞扬子建亲。","可怜金石友，去不待斯人。"]},{"t":"次韵高子勉十首 其一","f":"五言律诗","c":["雪尽虚檐滴，春从细草回。","德人泉下梦，俗物眼中埃。","久立我有待，长吟君不来。","重玄锁关籥，要待玉匙开。"]},{"t":"次韵寄上七兄","f":"七言律诗","c":["学得屠龙长缩手，鍊成五色化苍烟。","谁言游刃有馀地，自信无功可补天。","啼鸟笑歌追暇日，饱牛耕凿望丰年。","荷锄端欲相随去，邂逅青云恐疾颠。"]},{"t":"次韵寄滑州舅氏","f":"七言律诗","c":["舫斋闻有小溪山，便是壶公谪处天。","想听琐窗深夜雨，似看叶水上江船。","瞻相白马津亭路，寂寞双凫古县前。","舅氏知甥最疏懒，折腰尘土解哀怜。"]},{"t":"次韵寄蓝六在广陵","f":"七言律诗","c":["圣学相期沧海头，当时各倚富春秋。","班扬文字初无意，滕薛功名自不优。","焦尾朱弦非众听，南山白石使人愁。","传声为向扬州问，相忆犹能把酒不。"]},{"t":"次韵崔伯易席上所赋因以赠行二首 其二","f":"五言律诗","c":["老惜交情别，追随车马勤。","临朝思共理，治郡复斯文。","讼息常休吏，民贫更劝分。","西湖十顷月，自比汉封君。"]},{"t":"次韵崔伯易席上所赋因以赠行二首 其一","f":"五言律诗","c":["迎新与送故，渠已不胜勤。","民卖腰间剑，公宽柱后文。","诸郎投赐沐，高会惜临分。","去国虽千里，分忧即近君。"]},{"t":"次韵清虚同访李园","f":"七言律诗","c":["年来高兴满莼丝，寒薄春风骀荡时。","稍见燕脂开杏萼，已闻香雪烂梅枝。","老逢乐事心犹壮，病得新诗和更迟。","何日联镳向金谷，拟追仙翼到瑶池。"]},{"t":"次韵清虚喜子瞻得常州","f":"七言律诗","c":["喜色侵淫动搢绅，俞音下报谪仙人。","惊回汝水间关梦，乞与江天自在春。","罨画初游冰欲泮，浣花何处月还新。","凉州不是人间曲，伫见君王按玉宸。"]},{"t":"次韵盖郎中率郭郎中休官二首 其二","f":"七言律诗","c":["世态已更千变尽，心源不受一尘侵。","青春白日无公事，紫燕黄鹂俱好音。","付与儿孙知伏腊，听教鱼鸟逐飞沈。","黄公垆下曾知味，定是逃禅入少林。"]},{"t":"次韵盖郎中率郭郎中休官二首 其一","f":"七言律诗","c":["仕路风波双白发，閒曹笑傲两诗流。","故人相见自青眼，新贵即今多黑头。","桃叶柳花明晓市，荻芽蒲笋上春洲。","定知闻健休官去，酒户家园得自由。"]},{"t":"次韵黄斌老晚游池亭二首 其二","f":"七言律诗","c":["岑寂东园可散愁，胶胶扰扰梦神游。","万竿苦竹旌旗卷，一部鸣蛙鼓吹休。","雨后月前天欲冷，身閒心远地常幽。","杜门谢客恐生谤，且作人间鹏鴳游。"]},{"t":"次韵黄斌老晚游池亭二首 其一","f":"七言律诗","c":["路入东园无俗驾，忽逢佳士喜同游。","绿荷菡萏稍觉晚，黄菊拒霜殊未秋。","客位正须悬榻下，主人自爱小塘幽。","老夫多病蛮江上，颇忆平生马少游。"]},{"t":"次韵景珍酴醾","f":"七言律诗","c":["莫惜金钱买玉英，担头春老过清明。","天香国艳不著意，诗社酒徒空得名。","及此一时须痛饮，已拚三日作狂酲。","濠州园里都开尽，肠断萧萧雨打声。"]},{"t":"次韵答任仲微","f":"七言律诗","c":["邂逅相逢讲世盟，诸任尊行各才名。","交情吾子如棠棣，酒椀今秋对菊英。","高论生风摇麈尾，新诗掷地作金声。","文章学问嗟予晚，深信前贤畏后生。"]},{"t":"次韵答任仲微","f":"七言律诗","c":["伯氏文章足起家，雁行唯我乏芳华。","不堪黄绶腰铜印，只合清江把钓车。","缩项鱼肥炊稻饭，扶头酒熟卧芦花。","吴儿何敢当伦比，或有离骚似景差。"]},{"t":"次韵答李端叔","f":"七言律诗","c":["喜接高谈若饮冰，风骚清兴坐来增。","重寻伐木君何厚，欲赋骊驹我未能。","山影北来浮汇泽，松行东望际钟陵。","相期烂醉西楼月，缓带凭栏濯郁蒸。"]},{"t":"次韵答柳通叟问舍求田之诗","f":"七言律诗","c":["少日心期转谬悠，蛾眉见妒且障羞。","但令有妇如康子，安用生儿似仲谋。","横笛牛羊归晚径，卷帘瓜芋熟西畴。","功名可致犹回首，何况功名不可求。"]},{"t":"次韵答蒲元礼病起","f":"七言律诗","c":["暖律温风何处饶，莫言先上绿杨条。","梢头红糁杏花发，瓮面浮蛆酒齐销。","吏事困人如缚虎，君诗入手似闻韶。","直须扶病营春事，老味难将少壮调。"]},{"t":"次韵赏梅","f":"七言律诗","c":["安知宋玉在邻墙，笑立春晴照粉光。","淡薄似能知我意，幽闲元不为人芳。","微风拂掠生春思，小雨廉纤洗暗妆。","只恐浓葩委泥土，谁令解合返魂香。"]},{"t":"次韵裴仲谋同年","f":"七言律诗","c":["交盖春风汝水边，客床相对卧僧毡。","舞阳去叶才百里，贱子与公皆少年。","白发齐生如有种，青山好去坐无钱。","烟沙篁竹江南岸，输与鸬鹚取次眠。"]},{"t":"次韵德孺惠贶秋字之句","f":"七言律诗","c":["少日才华接贵游，老来忠义气横秋。","未应白发如霜草，不见丹砂似箭头。","顾我今成丧家狗，期君早作济川舟。","汉家宗庙英灵在，定是寒儒浪自愁。"]},{"t":"次韵德孺感兴二首 其二","f":"五言律诗","c":["眼前尝废忘，事往更追寻。","爱酒陶元亮，著书王仲任。","寒蒲虽有节，枯木已无心。","客至还须饮，逢欢起自斟。"]},{"t":"次韵德孺感兴二首 其一","f":"五言律诗","c":["于此吾忘我，从谁尺直寻。","事来千万种，人有两三心。","自守藩篱小，犹能井臼任。","过时虽不采，吾与菊花斟。"]},{"t":"次韵德孺新居病起","f":"五言律诗","c":["潭潭经略府，寂寂闭门居。","京洛圣贤宅，江湖鱼鳖潴。","官如一梦觉，话胜十年书。","稍喜过从近，扶筇不驾车。"]},{"t":"池口风雨留三日","f":"七言律诗","c":["孤城三日风吹雨，小市人家只菜蔬。","水远山长双属玉，身閒心苦一舂锄。","翁从旁舍来收网，我适临渊不羡鱼。","俛仰之间已陈迹，暮窗归了读残书。"]},{"t":"红蕉洞独宿","f":"七言律诗","c":["南床高卧读逍遥，真感生来不易销。","枕落梦魂飞蛱蝶，灯残风雨送芭蕉。","永怀玉树埋尘土，何异蒙鸠挂苇苕。","衣笐妆台蛛结网，可怜无以永今朝。"]},{"t":"自巴陵略平江临湘入通城无日不雨至黄龙奉谒清禅师继而晚晴邂逅禅客戴道纯款语作长句呈道纯","f":"七言律诗","c":["山行十日雨沾衣，幕阜峰前对落晖。","野水自添田水满，晴鸠却唤雨鸠归。","灵源大士人天眼，双塔老师诸佛机。","白发苍颜重到此，问君还是昔人非。"]},{"t":"观王主簿家酴醾","f":"七言律诗","c":["肌肤冰雪薰沉水，百草千花莫比芳。","露湿何郎试汤饼，日烘荀令炷炉香。","风流彻骨成春酒，梦寐宜人入枕囊。","输与能诗王主簿，瑶台影里据胡床。"]},{"t":"讲武台南有感","f":"七言律诗","c":["月明犹在搭衣竿，晓踏台南路屈盘。","驺子雨中先马去，村童烟外倚墙看。","鸦啼宰木秋风急，鹭立渔船野水乾。","花似去年堪折赠，插花人去泪阑干。"]},{"t":"过方城寻七叔祖旧题","f":"七言律诗","c":["壮气南山若可排，今为野马与尘埃。","清谈落笔一万字，白眼举觞三百杯。","周鼎不酬康瓠价，豫章元是栋梁材。","眷然挥涕方城路，冠盖当年向此来。"]},{"t":"过平舆怀李子先时在并州","f":"七言律诗","c":["前日幽人佐吏曹，我行堤草认青袍。","心随汝水春波动，兴与并门夜月高。","世上岂无千里马，人中难得九方皋。","酒船鱼网归来是，花落故溪深一篙。"]},{"t":"伯氏到济南寄诗颇言太守居有湖山之胜同韵和","f":"七言律诗","c":["西来黄犬传佳句，知是陆机思陆云。","历下楼台追把酒，舅家宾客厌论文。","山椒欲雨好云气，湖面逆风生水纹。","想得争棋飞鸟上，行人不见只听闻。"]},{"t":"伯父祖善耆老好学于所居紫阳溪后小马鞍山为放隐斋远寄诗句意欲庭坚和之幸师友同赋率尔上呈","f":"五言律诗","c":["樵入千岩静，松含万籁寒。","儿童给行李，藜蓧对衣冠。","小槛聊防虎，时来即解鞍。","阿翁吹笛罢，怀昔泪相看。"]},{"t":"何主簿萧斋郎赠诗思家戏和答之","f":"七言律诗","c":["善吟闺怨断人肠，二妙风流不可当。","傅粉未归啼玉箸，吹笙无伴涩银篁。","睡添乡梦客床冷，瘦尽腰围衣带长。","天性少情诗亦少，羡他萧史与何郎。"]},{"t":"何造诚作浩然堂陈义甚高然颇喜度世飞升之说筑屋饭方士愿乘六气游天地间故作浩然词二章赠之 其二","f":"七言律诗","c":["万物浮沈共我家，清明心水遍河沙。","无钩狂象听人语，露地白牛看月斜。","小雨呼儿蓺桃李，疏帘帏客转琵琶。","尘尘三昧开门户，不用丹田养素霞。"]},{"t":"何造诚作浩然堂陈义甚高然颇喜度世飞升之说筑屋饭方士愿乘六气游天地间故作浩然词二章赠之 其一","f":"七言律诗","c":["公欲轻身上紫霞，琼爢玉馔厌豪奢。","百年世路同朝菌，九钥天关守夜叉。","霜桧左纽空白鹿，金炉同契漫丹砂。","要令心地閒如水，万物浮沈共我家。"]},{"t":"初至叶县","f":"七言律诗","c":["白鹤去寻王子晋，真龙得慕沈诸梁。","千年往事如飞鸟，一日倾愁对夕阳。","遗老能名唐郡邑，断碑犹是晋文章。","浮云不作苞桑计，只有荒山意绪长。"]},{"t":"初望淮山","f":"七言律诗","c":["风裘雪帽别家林，紫燕黄鹂已夏深。","三釜古人干禄意，一年慈母望归心。","劳生逆旅何休息，病眼看山力不禁。","想见夕阳三径里，乱蝉嘶罢柳阴阴。"]},{"t":"呈马粹老范德孺","f":"七言律诗","c":["颍上相逢杏始青，尔来瓜垄有新耕。","四时为岁已中半，万物得秋将老成。","日永清风摇麈尾，夜阑飞雹落棋枰。","两厅未觉过从数，政以顽疏累友生。"]},{"t":"呈王明复陈季张","f":"七言律诗","c":["倦客西来厌马鞍，为予休辔小长安。","陈遵投辖情何厚，王粲登楼兴未阑。","雪压群山晴后白，月临千里夜深寒。","少留待我同归去，洛下林中斫钓竿。"]},{"t":"宋夫人挽词","f":"七言律诗","c":["往岁涂宫暗碧纱，倾城出祖路人嗟。","松楠峰下迁华寝，雪月光中咽晓笳。","有子今为二千石，同州才数两三家。","儿孙满地厥衣举，不见归时桃李华。"]},{"t":"希仲招饮李都尉北园","f":"七言律诗","c":["晓踏骅骝傍古墙，北园同系紫游缰。","主人情厚杯无算，别馆春深日正长。","杨柳阴斜移坐晚，酴醾花暗染衣香。","夜深恐触金吾禁，走马天街趁夕阳。"]},{"t":"张仲谟许送河鲤未至戏督以诗","f":"七言律诗","c":["浮蛆琰琰动春醅，张仲临津许鲙材。","盐豉欲催莼菜熟，霜鳞未贯柳条来。","日晴鱼网应曾晒，风软河冰必暂开。","莫误晓窗占食指，仍须持取报章回。"]},{"t":"李濠州挽词二首 其二","f":"七言律诗","c":["礼数最优徐孺子，风流不减谢宣城。","那知此别成千古，未信斯言隔九京。","落日松楸阴隧道，西风箫鼓送铭旌。","善人报施今如此，陇水长寒呜咽声。"]},{"t":"李濠州挽词二首 其一","f":"七言律诗","c":["循吏功名两汉中，平生风义最雍容。","鱼游濠上方云乐，鵩在承尘忽告凶。","挂剑自知吾已许，脱骖不为涕无从。","百年穷达都归尽，淮水空围墓上松。"]},{"t":"社日奉寄君庸主簿","f":"五言律诗","c":["花发社公雨，阴寒殊未开。","初闻燕子语，似报玉人来。","遮眼便书册，挑聋欺酒杯。","传声习主簿，勤为拨春醅。"]},{"t":"秀江亭","f":"七言律诗","c":["因循不到此江头，匹马黄埃三十秋。","旧舍只今人共老，清波常与月分流。","羡君潇洒成佳趣，感我凄凉念旧游。","沽酒买鱼终不负，何时相与泛扁舟。"]},{"t":"闰月访同年李夷伯子真于河上子真以诗谢次韵","f":"七言律诗","c":["十年不见犹如此，未觉斯人叹滞留。","白璧明珠多按剑，浊泾清渭要同流。","日晴花色自深浅，风软鸟声相应酬。","谈笑一樽非俗物，对公无地可言愁。"]},{"t":"陈氏园咏竹","f":"七言律诗","c":["不问主人来看竹，小溪风物似家林。","春供馈妇几番笋，夏与行人百亩阴。","直气虽冲云汉上，高材终恐斧斤寻。","截竿可举北溟钓，欲赠溪翁谁姓任。"]},{"t":"陈季张有蜀芙蓉长饮客至开辄剪去作诗戏之","f":"七言律诗","c":["剪花莫学韩中令，投辖惟闻陈孟公。","客兴不孤春竹叶，年华全属拒霜丛。","玄子蹙迫三秋尽，青女摧残一夜空。","著意留连好风景，非君谁作主人翁。"]},{"t":"陈荣绪惠示之字韵诗推奖过实非所敢当辄次高韵三首 其三","f":"五言律诗","c":["十家有忠信，江夏可无之。","政苦寄卖友，忽闻衡说诗。","饥蒙青䭀饭，寒赠紫陀尼。","酬报矜难巧，深惭陆与皮。"]},{"t":"陈荣绪惠示之字韵诗推奖过实非所敢当辄次高韵三首 其二","f":"五言律诗","c":["太丘胸量阔，一苇莫杭之。","万事不挂眼，四愁犹有诗。","状閒聊阘茸，心洁似毗尼。","早晚同舟去，烟波学子皮。"]},{"t":"陈荣绪惠示之字韵诗推奖过实非所敢当辄次高韵三首 其一","f":"五言律诗","c":["纷纷不可耐，君子有忧之。","鞅掌诚庄语，贤劳似怨诗。","颓波阅砥柱，浊水得摩尼。","知我无枝叶，刳心只有皮。"]},{"t":"陈留市隐","f":"五言律诗","c":["市井怀珠玉，往来人未逢。","乘肩娇小女，邂逅此生同。","养性霜刀在，阅人清镜空。","时时能举酒，弹镊送飞鸿。"]},{"t":"饮韩三家醉后始知夜雨","f":"七言律诗","c":["醉卧人家久未曾，偶然樽俎对青灯。","兵厨欲罄浮蛆瓮，馈妇初供醒酒冰。","只见眼前人似月，岂知帘外雨如绳。","浮云不负青春色，未觉新诗减杜陵。"]},{"t":"叔父钓亭","f":"七言律诗","c":["槛外溪风拂面凉，四围春草自锄荒。","陆沈霜发为钩直，柳贯锦鳞缘饵香。","影落华亭千尺月，梦通岐下六州王。","麒麟卧笑功名骨，不道山林日月长。"]},{"t":"呻吟斋睡起五首呈世弼 其四","f":"五言律诗","c":["已把社公酒，春寒那得严。","厌听鸿啄雪，喜有燕穿帘。","璞玉深藏器，囊锥立见尖。","儿时爱谈道，今日口如钳。"]},{"t":"呻吟斋睡起五首呈世弼 其一","f":"五言律诗","c":["棐几坐清昼，博山凝妙香。","兰芽依客土，柳色过邻墙。","巷僻过从少，官閒气味长。","江南一枕梦，高卧听鸣桹。"]},{"t":"呻吟斋睡起五首呈世弼 其三","f":"五言律诗","c":["疏食吾犹饱，曲肱哦古今。","酒倾因好事，弦绝为知音。","妒檗长春木，争巢喧暮禽。","长怀阮校尉，北望首阳岑。"]},{"t":"呻吟斋睡起五首呈世弼 其五","f":"五言律诗","c":["墙下蓬蒿地，儿童课剪除。","蔓莴随分种，杞菊未须锄。","河水传烽火，交州报捷书。","无能落閒处，惭愧饱春蔬。"]},{"t":"呻吟斋睡起五首呈世弼 其二","f":"五言律诗","c":["学省非簿领，卧痾常闭关。","雨馀楼阁静，风晚鸟乌还。","赏逐四时改，心安一味閒。","古人虽已往，不废仰高山。"]},{"t":"和中玉使君晚秋开天宁节道场","f":"七言律诗","c":["江南江北尽云沙，车骑东来风旆斜。","倒影楼台开紫府，得霜篱落剩黄花。","钓溪筑野收多士，航海梯山共一家。","想见星坛祝尧寿，步虚声里静无哗。"]},{"t":"和文潜舟中所题","f":"词","c":["云横疑有路，天远欲无门。","信矣江山美，怀哉谴逐魂。","长波空?记，佳句洗眵昏。","谁奈离愁得，村醪或可尊。"]},{"t":"和王明之雪","f":"七言律诗","c":["金母紫皇开寿域，炼成天地一炉沙。","千花乱发春无耐，万井交光月未斜。","贫巷有人衣不纩，北窗惊我眼飞花。","歌楼处处催沽酒，谁念寒生泣白华。"]},{"t":"和外舅夙兴三首 其三","f":"五言律诗","c":["暑逐池莲尽，寒随塞雁来。","衣裘虽得暖，狐貉正相哀。","僧汲辘轳晓，车鸣关锁开。","不因朝鼓起，来帙乱书堆。"]},{"t":"和外舅夙兴三首 其二","f":"五言律诗","c":["风烈僧鱼响，霜严郡角悲。","短童疲洒扫，落叶故纷披。","水冻食鲑少，瓮寒浮蚁迟。","朝阳乌鸟乐，安稳托禅枝。"]},{"t":"和外舅夙兴三首 其一","f":"五言律诗","c":["瓜蔓已除垄，苔痕犹上墙。","蓬蒿贪雨露，松竹见冰霜。","卷幔天垂斗，披衣日在房。","无诗叹不遇，千古一潜郎。"]},{"t":"和吕秘丞","f":"七言律诗","c":["北海樽中忘日月，南山雾里晦文章。","清朝不上九卿列，白发归来三径荒。","车辙马蹄疏市井，花光竹影照门墙。","人间荣辱无来路，万顷风烟一草堂。"]},{"t":"和师厚郊居示里中诸君","f":"七言律诗","c":["篱边黄菊关心事，窗外青山不世情。","江橘千头供岁计，秋蛙一部洗朝酲。","归鸿往燕竞时节，宿草新坟多友生。","身后功名空自重，眼前樽酒未宜轻。"]},{"t":"和师厚秋半时复官分司西都","f":"七言律诗","c":["遥知得谢分西洛，无复肯弹冠上尘。","园地除瓜犹入市，水田收秫未全贫。","杜陵白发垂垂老，张翰黄花句句新。","还与老农争坐席，青林同社赛田神。"]},{"t":"和师厚栽竹","f":"五言律诗","c":["大隐在城市，此君真友生。","根须辰日斸，笋要上番成。","龙化葛陂去，凤吹阿阁鸣。","草荒三径断，岁晚见交情。"]},{"t":"和张沙河招饮","f":"七言律诗","c":["张侯耕稼不逢年，过午未炊儿女煎。","腹里虽盈五车读，囊中能有几钱穿。","况闻缊素尚黄葛，可怕雪花铺白毡。","谁料丹徒布衣得，今朝忽有酒如川。"]},{"t":"和李文伯暑时五首 其一 扇","f":"五言律诗","c":["团扇如明月，动摇微风兴。","屏去坐上热，袪逐盘中蝇。","有用何提挈，无心分爱憎。","炎炎虽可贵，弃置奈寒冰。"]},{"t":"和知命招晁道夫叔侄","f":"五言律诗","c":["过我诸公子，寂寥非世娱。","茶须亲碾试，酒可倩行沽。","日永乌皮几，窗寒竹火炉。","不来寻翰墨，僮仆解吴歈。"]},{"t":"和庭诲苦雨不出","f":"五言律诗","c":["端居广文舍，暑服似纯绵。","绿竹尘蒙合，红榴日炙蔫。","披襟风入幌，洒面雨连天。","莫借角巾垫，勤来坐马鞯。"]},{"t":"和庭诲雨后","f":"五言律诗","c":["小霁卧观书，凉轩夏簟舒。","天青印鸟迹，云黑卷犀渠。","新月来高树，清风转广除。","雨师真解事，一为洗空虚。"]},{"t":"和高仲本喜相见","f":"七言律诗","c":["雨昏南浦曾相对，雪满荆州喜再逢。","有子才如不羁马，知君心是后凋松。","閒寻书册应多味，老傍人门似更慵。","何日晴轩观笔砚，一樽相属要从容。"]},{"t":"和答元明黔南赠别","f":"七言律诗","c":["万里相看忘逆旅，三声清泪落离觞。","朝云往日攀天梦，夜雨何时对榻凉。","急雪脊令相并影，惊风鸿雁不成行。","归舟天际常回首，从此频书慰断肠。"]},{"t":"和答王世弼","f":"七言律诗","c":["文章年少气如虹，肯爱闲曹一秃翁。","弦上深知流水意，鼻端不怯运斤风。","燕堂淡薄无歌舞，鲑菜清贫只韭葱。","惭愧伯鸾留步履，好贤应与孟光同。"]},{"t":"和答刘太博携家游庐山见寄","f":"七言律诗","c":["缓辔松阴不起尘，岚光经雨一番新。","遥知数夜寻山宿，便是全家避世人。","落日已迷烟际路，飞花还报洞中春。","可怜不更寻源入，若见刘郎想问秦。"]},{"t":"和答孙不愚见赠","f":"七言律诗","c":["诗比淮南似小山，酒名曲米出云安。","且凭诗酒勤春事，莫爱儿郎作好官。","簿领侵寻台相笔，风埃蓬勃使星鞍。","小臣才力堪为掾，敢学前人便挂冠。"]},{"t":"和答张仲谟泛舟之诗","f":"七言律诗","c":["云容天影水中摇，分坐船舷似小桥。","联句敏于山吐月，举觞疾甚海吞潮。","兴来活脔牛心熟，醉罢红炉鸭脚焦。","公子翩翩得真意，马蹄尘里有嘉招。"]},{"t":"和答李子真读陶庾诗","f":"五言律诗","c":["乐易陶彭泽，忧思庾义城。","风流扫地尽，诗句识馀情。","往者不再作，前贤畏后生。","君言得意处，此意少人明。"]},{"t":"和答赵令同前韵","f":"七言律诗","c":["人生政自无闲暇，忙里偷闲得几回。","紫燕黄鹂驱日月，朱樱红杏落条枚。","诗成稍觉嘉宾集，饮少先愁急板催。","亲遣小童锄草径，鸣驺早晚出城来。"]},{"t":"和答郭监簿咏雪","f":"七言律诗","c":["细学梅花落晚风，忽翻柳絮下春空。","家贫无酒愿邻富，官冷有田知岁丰。","夜听枕边飘屋瓦，梦成江上打船篷。","觉来幽鸟语声乐，疑在白鸥寒苇中。"]},{"t":"和答登封王晦之登楼见寄","f":"七言律诗","c":["县楼三十六峰寒，王粲登临独倚阑。","清坐一番春雨歇，相思千里夕阳残。","诗来嗟我不同醉，别后喜君能自宽。","举目尽妨人作乐，几时归得钓鲵桓。"]},{"t":"咏伯时画太初所获大宛虎脊天马图","f":"五言律诗","c":["笔端那有此，千里在胸中。","四蹄雷电去，一顾马群空。","谁能乘此物，超俗驾长风。","逸材归辔勒，岁在执徐同。"]},{"t":"咏雪奉呈广平公","f":"七言律诗","c":["连空春雪明如洗，忽忆江清水见沙。","夜听疏疏还密密，晓看整整复斜斜。","风回共作婆娑舞，天巧能开顷刻花。","正使尽情寒至骨，不妨桃李用年华。"]},{"t":"夜观蜀志","f":"七言律诗","c":["盖世英雄不自知，暮年初志各参差。","南阳陇底卧龙日，北固樽前失箸时。","霸主三分割天下，宗臣十倍胜曹丕。","寒炉夜发尘书读，似覆输筹一局棋。"]},{"t":"奉送刘君昆仲","f":"七言律诗","c":["游子归心日夜流，南陔香草可晨羞。","平原晓雨半槐夏，汾上午风初麦秋。","鸿雁要须翔集早，脊令无憾急难求。","欲因行李传家信，姑射山前是晋州。"]},{"t":"奉答圣思讲论语长句","f":"七言律诗","c":["簿领文书千笔秃，公庭嚚讼百虫鸣。","时从退食须臾顷，喜听邻家讽诵声。","观海诸君知浩渺，学山他日看崇成。","暮堂吏退张灯火，抱取鲁论来讲评。"]},{"t":"奉答固道","f":"七言律诗","c":["平生湖海鱼竿手，强学来操制锦刀。","末俗相看终眼白，古人不见想山高。","未乘春水归行李，傥得閒官去坐曹。","自是无能欲乐尔，烦君错为叹贤劳。"]},{"t":"宗室公寿挽词二首 其二","f":"五言律诗","c":["昧旦鸣珂路，春朝禁殿班。","方看分宝玉，何意作丘山。","燕入风荣舞，花开日笑颜。","空馀杜陵泪，一为汉中潸。"]},{"t":"宗室公寿挽词二首 其一","f":"五言律诗","c":["昔在熙宁日，葭莩接贵游。","题诗奉先寺，横笛宝津楼。","天网恢中夏，宾筵禁列侯。","但闻刘子政，头白更清修。"]},{"t":"宜阳别元明用觞字韵","f":"七言律诗","c":["霜须八十期同老，酌我仙人九酝觞。","明月湾头松老大，永思堂下草荒凉。","千林风雨莺求友，万里云天雁断行。","别夜不眠听鼠齧，非关春茗搅枯肠。"]},{"t":"明叔惠示二颂云见七佛偈似有警觉乃是向道之端发于此故以二颂为报 其一","f":"五言律诗","c":["山川围宴坐，日月转庭隅。","般若寻常事，如来卧起俱。","多闻成外道，只是守凡夫。","欲听虚空教，须弥作鼓桴。"]},{"t":"河舟晚饮呈陈说道","f":"七言律诗","c":["西风脱叶静林柯，浅水扁舟阁半河。","落日游鱼穿镜面，中秋明月涨金波。","由来白发生无种，岂似青山保不磨。","胜事只愁樽酒尽，莫言争奈醉人何。"]},{"t":"范蜀公挽词二首 其二","f":"五言律诗","c":["公在昭陵日，文章近赤墀。","空嗟伏生老，不侍迩英帷。","去国几三虎，闻韶待一夔。","谁言盖棺了，新乐锁蛛丝。"]},{"t":"范蜀公挽词二首 其一","f":"五言律诗","c":["信道虽常尔，知人乃独亨。","书林身老大，谏纸字敧倾。","鳌去三山动，人危五鼎烹。","保全天子圣，几杖送馀生。"]},{"t":"诗一首","f":"七言律诗","c":["石磴层层鸟道斜，仙家楼阁锁烟霞。","丹砂已化黄金鼎，玉洞犹开白鹤花。","铁简有云神永护，金钟无韵鬼曾楂。","洞天福地阴阳合，胜事留传岂浪誇。"]},{"t":"雨过至城西苏家","f":"七言律诗","c":["飘然一雨洒青春，九陌净无车马尘。","渐散紫烟笼帝阙，稍回晴日丽天津。","花飞衣袖红香湿，柳拂鞍鞯绿色匀。","管领风光唯痛饮，都城谁是得闲人。"]},{"t":"信中远来相访且致今岁新茗又枉任道寄佳篇复次韵呈信中兼简任道","f":"五言律诗","c":["安坐一柱观，立遣十年劳。","玄圭于我厚，千里来江皋。","松风转蟹眼，乳花明兔毛。","何如浮大白，一举醉陶陶。"]},{"t":"南安试院无酒饮周道辅自赣上携一榼时时对酌惟恐尽试毕仆夫言尚有馀樽木芙蓉盛开戏呈道辅","f":"七言律诗","c":["闻说君家好弟兄，穷乡相见眼俱青。","偶同一饭论三益，颇为诸生醉六经。","山邑已催乘传马，晓窗犹共读书萤。","霜花留得红妆面，酌尽斋中竹叶瓶。"]},{"t":"客自潭府来称明因寺僧作静照堂求予作","f":"七言律诗","c":["客从潭府渡河梁，籍甚传誇静照堂。","正苦穷年对尘土，坐令合眼梦湖湘。","市门晓日鱼虾白，邻舍秋风橘柚黄。","去马来舟争岁月，老僧元不下胡床。"]},{"t":"弈棋二首呈任公渐 其一","f":"七言律诗","c":["偶无公事负朝暄，三百枯棋共一樽。","坐隐不知岩穴乐，手谈胜与俗人言。","簿书堆积尘生案，车马淹留客在门。","战胜将骄疑必败，果然终取敌兵翻。"]},{"t":"弈棋二首呈任公渐 其二","f":"七言律诗","c":["偶无公事客休时，席上谈兵校两棋。","心似蛛丝游碧落，身如蜩甲化枯枝。","湘东一目诚甘死，天下中分尚可持。","谁谓吾徒犹爱日，参横月落不曾知。"]},{"t":"思亲汝州作","f":"七言律诗","c":["岁晚寒侵游子衣，拘留幕府报官移。","五更归梦三百里，一日思亲十二时。","车上吐茵元不逐，市中有虎竟成疑。","秋毫得失关何事，总为平安书到迟。"]},{"t":"既作闵雨诗是夕遂澍雨夜中喜不能寐起作喜雨诗","f":"七言律诗","c":["南风吹雨下田塍，田父伸眉愿力耕。","麰麦明年应解好，帘栊今夜不胜清。","直须洗尽焦枯意，不厌屡闻飘洒声。","黄卷腐儒何所用，惟将歌咏报升平。"]},{"t":"春祀分得叶公庙双凫观","f":"七言律诗","c":["春将祠事出门扉，宫殿参差缭翠微。","清晓风烟迷部曲，小蹊桃杏挂冠衣。","叶公在昔真龙去，王令何时白鹤归。","糟魄相传漫青史，独怀千古对容徽。"]},{"t":"春雪呈张仲谋","f":"七言律诗","c":["暮雪霏霏若撒盐，须知千陇麦纤纤。","梦阑半枕听飘瓦，晓起高堂看入帘。","剩与月明分夜砌，即成春溜滴晴檐。","万金一醉张公子，莫道街头酒价添。"]},{"t":"柳闳展如子瞻甥也其才德甚美有意于学故以桃李不言下自成蹊八字作诗赠之 其四","f":"五言律诗","c":["任世万钧重，载言以为轩。","空文误来世，圣达欲无言。","咸池浴日月，深宅养灵根。","胸中浩然气，一家同化元。"]},{"t":"癸亥立春日煮茗于石池寺见庚戌中盛二十舅中叔为县时题名叹此寺不日而成哀县学弊而不能复","f":"七言律诗","c":["中叔风流映江左，当年桃李自光辉。","看成佛屋上云雨，不忍学宫荒蕨薇。","人物深藏青白眼，官联曾近赭黄衣。","蛛丝柱后惠文暗，憔悴今乘别驾归。"]},{"t":"神宗皇帝挽词三首 其二","f":"五言律诗","c":["钓筑收贤辅，天人与圣能。","辉光唐六典，度越汉中兴。","百世神宗庙，千秋永裕陵。","帝乡无马迹，空望白云乘。"]},{"t":"神宗皇帝挽词三首 其三","f":"五言律诗","c":["昔在基皇极，师臣论九畴。","丘陵忽为谷，天地不藏舟。","河洛功无憾，幽燕策未收。","嗣皇朝万国，任姒正兴周。"]},{"t":"神宗皇帝挽词三首 其一","f":"五言律诗","c":["文思昭日月，神武用雷霆。","制作深垂统，忧勤减梦龄。","孙谋开二圣，末命对三灵。","今代谁班马，能书汗简青。"]},{"t":"秋思","f":"七言律诗","c":["椎牛作社酒新篘，扶老将儿嬉陇头。","木落人家见鸡犬，晓寒溪口在汀洲。","无功可佩水苍玉，卒岁空思狐白裘。","身到楚伧非屈宋，顾惭疏懒作悲秋。"]},{"t":"结客","f":"五言律诗","c":["结客结英豪，肯同儿女曹。","黄金妆佩剑，猛兽画旗旄。","北极狼星落，中原王气高。","终令贺兰贼，不著赭黄袍。"]},{"t":"赵令许载酒见过","f":"七言律诗","c":["玉马何时破紫苔，南溪水满绿徘徊。","买鱼斫鲙须论网，扑杏供盘不数枚。","广汉威名知讼少，平原樽俎费诗催。","草玄寂寂下帘幕，稍得闲时公合来。"]},{"t":"赵令答诗约携山妓见访","f":"七言律诗","c":["晴波鸂鶒漾潭隈，能使游人判不回。","风入园林寒漠漠，日移宫殿影枚枚。","未尝绿蚁何妨拨，宿戒红妆莫待催。","缺月西南光景少，仍须挽取烛笼来。"]},{"t":"追和东坡壶中九华","f":"七言律诗","c":["有人夜半持山去，顿觉浮岚暖翠空。","试问安排华屋处，何如零落乱云中。","能回赵璧人安在，已入南柯梦不通。","赖有霜钟难席卷，袖椎来听响玲珑。"]},{"t":"追和东坡题李亮功归来图","f":"七言律诗","c":["今人常恨古人少，今得见之谁谓无。","欲学渊明归作赋，先烦摩诘画成图。","小池已筑鱼千里，隙地仍栽芋百区。","朝市山林俱有累，不居京洛不江湖。"]},{"t":"送陈氏女弟至石塘河","f":"七言律诗","c":["富贵常多覆族忧，贱贫骨肉不相收。","独乘舟去值花雨，寄得书来应麦秋。","行李淮山三四驿，风波春水一双鸥。","人言离别愁难遣，今日真成始欲愁。"]},{"t":"送徐隐父宰馀干二首 其二","f":"七言律诗","c":["天上麒麟来下瑞，江南橘柚间生贤。","玉台书在犹骚雅，孺子亭荒只草烟。","半世功名初墨绶，同兄文字直青钱。","割鸡不合庖丁手，家传风流更著鞭。"]},{"t":"送徐隐父宰馀干二首 其一","f":"七言律诗","c":["地方百里身南面，翻手冷霜覆手炎。","赘婿得牛庭少讼，长官斋马吏争廉。","邑中丞掾阴桃李，案上文书略米盐。","治状要须闻岂弟，此行端为霁威严。"]},{"t":"送徐景道尉武宁二首 其二","f":"五言律诗","c":["黄绶补一尉，还依水竹居。","身随南渡马，书寄北来鱼。","风俗谙邻并，艰难试事初。","官閒莫歌舞，教子诵诗书。"]},{"t":"送徐景道尉武宁二首 其一","f":"五言律诗","c":["李苦少人摘，酒醇无巷深。","当官莫避事，为吏要清心。","葛藟松千尺，寒泉绠百寻。","公朝有汲引，吾子茂徽音。"]},{"t":"送莫郎中致仕归湖州","f":"五言律诗","c":["霅上多高士，君今又乞身。","中年谢事客，白日上升人。","静泛苕溪月，閒尝顾渚春。","滔滔夜行者，能不愧清尘。"]},{"t":"送顾子敦赴河东三首 其三","f":"七言律诗","c":["揽辔都城风露秋，行台无妾护衣篝。","虎头妙墨能频寄，马乳蒲萄不待求。","上党地寒应强饮，两河民病要分忧。","犹闻昔在军兴日，一马人间费十牛。"]},{"t":"送顾子敦赴河东三首 其二","f":"七言律诗","c":["家在江东不系怀，爱民忧国有从来。","月斜汾沁催驿马，雪暗岢岚传酒杯。","塞上金汤惟粟粒，胸中水镜是人材。","遥知更解青牛句，一寸功名心已灰。"]},{"t":"送顾子敦赴河东三首 其一","f":"七言律诗","c":["头白书林二十年，印章今领晋山川。","紫参可掘宜包贡，青铁无多莫铸钱。","劝课农桑诚有道，折冲樽俎不临边。","要知使者功多少，看取春郊处处田。"]},{"t":"送高士敦赴成都钤辖二首 其二","f":"五言律诗","c":["捧日高宣事，东京四姓侯。","军中闻俎豆，庙胜脱兜鍪。","烧烛海棠夜，香衣药市秋。","君平识行李，河汉接天流。"]},{"t":"送高士敦赴成都钤辖二首 其一","f":"七言律诗","c":["玉钤金印临参井，控蜀通秦四十州。","日下书来望鸿雁，江头花发醉貔貅。","巴滇有马驹空老，林箐无人叶自秋。","能为将军歌此曲，鸣机割锦与缠头。"]},{"t":"送曹黔南口号","f":"七言律诗","c":["摩围山色醉今朝，试问归程指斗杓。","荔子阴成棠棣爱，竹枝歌是去思谣。","阳关一曲悲红袖，巫峡千波怨画桡。","归去天心承雨露，双鱼来报旧宾僚。"]},{"t":"送彭南阳","f":"七言律诗","c":["南阳令尹振华镳，三月春风困柳条。","携手河梁愁欲别，离魂芳草不胜招。","壶觞调笑平民讼，宾客风流醉舞腰。","若见贤如武侯者，为言来仕圣明朝。"]},{"t":"送舅氏野夫之宣城二首 其二","f":"五言律诗","c":["试说宣城郡，停杯且细听。","晚楼明宛水，春骑簇昭亭。","䆉稏丰圩户，桁杨卧讼庭。","谢公歌舞处，时对换鹅经。"]},{"t":"送舅氏野夫之宣城二首 其一","f":"五言律诗","c":["藉甚宣城郡，风流数贡毛。","霜林收鸭脚，春网荐琴高。","共理须良守，今年辍省曹。","平生割鸡手，聊试发硎刀。"]},{"t":"食瓜有感","f":"七言律诗","c":["暑轩无物洗烦蒸，百果凡材得我憎。","藓井筠笼浸苍玉，金盘碧箸荐寒冰。","田中谁问不纳履，坐上适来何处蝇。","此理一杯分付与，我思明哲在东陵。"]},{"t":"徐孺子祠堂","f":"七言律诗","c":["乔木幽人三亩宅，生刍一束向谁论。","藤萝得意干云日，箫鼓何心进酒樽。","白屋可能无孺子，黄堂不是欠陈蕃。","古人冷淡今人笑，湖水年年到旧痕。"]},{"t":"病起次韵和稚川进叔倡酬之什","f":"七言律诗","c":["池塘夜雨听鸣蛙，老境侵寻每忆家。","白发生来惊客鬓，黄粱炊熟又春华。","百年不负胶投漆，万事相依葛与瓜。","胜日主人如有酒，犹堪扶病见莺花。"]},{"t":"罢姑熟寄元明用觞字韵","f":"七言律诗","c":["追随富贵劳牵尾，准拟田园略滥觞。","本与江鸥成保社，聊随海燕度炎凉。","未栽姑熟桃李径，却入江西鸿雁行。","别后常同千里月，书来莫寄九回肠。"]},{"t":"袁州刘司法亦和予摩字诗因次韵寄之","f":"七言律诗","c":["袁州司法多兼局，日暮归来印几窠。","诗罢春风荣草木，书成快剑斩蛟鼍。","遥知吏隐清如此，应问卿曹果是何。","颇忆病馀居士否，在家无意饮萝摩。"]},{"t":"读曹公传","f":"七言律诗","c":["南征北伐报功频，刘氏亲为魏国宾。","毕竟以丕成霸业，岂能于汉作纯臣。","两都秋色皆乔木，二祖恩波在细民。","驾驭英雄虽有术，力扶宗社可无人。"]},{"t":"辱粹道兄弟寄书久不作报以长句谢不敏","f":"七言律诗","c":["病癖无堪吾懒书，交亲情分岂能疏。","深惭烟际两鸿雁，遗我罾中双鲤鱼。","故国青山长极眼，今年白发不胜梳。","几时得计休官去，笋叶裹茶同趁虚。"]},{"t":"郭明甫作西斋于颍尾请予赋诗二首 其二","f":"七言律诗","c":["东京望重两并州，遂有汾阳整缀旒。","翁伯入关倾意气，林宗异世想风流。","君家旧事皆青史，今日高材未白头。","莫倚西斋好风月，长随三径古人游。"]},{"t":"郭明甫作西斋于颍尾请予赋诗二首 其一","f":"七言律诗","c":["食贫自以官为业，闻说西斋意凛然。","万卷藏书宜子弟，十年种木长风烟。","未尝终日不思颍，想见先生多好贤。","安得雍容一樽酒，女郎台下水如天。"]},{"t":"钱塘旧游","f":"七言律诗","c":["薄宦飘然笑漫郎，瑟洲花草弄幽芳。","莫教景物添春色，转觉山川是异乡。","南北峰岩空入梦，短长亭舍自相望。","湖边山寺清明后，相见兰开禊水香。"]},{"t":"宿广惠寺","f":"七言律诗","c":["鸦啼残照下层城，僧舍初寒夜气清。","风乱竹枝垂地影，霜乾桐叶落阶声。","不遑将母伤今日，无以为家笑此生。","都下苦无书信到，数行归雁月边横。"]},{"t":"寄上叔父夷仲三首 其三","f":"七言律诗","c":["关寒塞雪欲嗣音，燕雁拂天河鲤沉。","百书不如一见面，几日归来两慰心。","弓刀陌上望行色，儿女灯前语夜深。","更怀父子东归得，手种江头柳十寻。"]},{"t":"寄张仲谋","f":"五言律诗","c":["好在张公子，清秋应苦吟。","衣穿慈母线，囊罄旅人金。","早晚辞天阙，归来慰陆沈。","黄花一樽酒，期与尔同斟。"]},{"t":"寄怀公寿","f":"七言律诗","c":["好赋梁王在日边，重帘复幕锁神仙。","莫因酒病疏桃李，且把春愁付管弦。","愚智相悬三十里，荣枯同有百馀年。","及身强健且行乐，一笑端须直万钱。"]},{"t":"寄袁守廖献卿","f":"七言律诗","c":["公移猥甚丛生笋，讼牒纷如蜜分窠。","少得曲肱成梦蝶，不堪衙吏报鸣鼍。","已荒里社田园了，可奈春风桃李何。","想见宜春贤太守，无书来问病维摩。"]},{"t":"寄清新二禅师颂 其二","f":"七言律诗","c":["死心寮里有清新，把断黄河塞要津。","一段风涛惊彻底，个中无我尔无人。","梦惊蛇咬慞惶走，痛学寻医□有神。","此是如来正法藏，觉来床上笑番身。"]},{"t":"寄清新二禅师颂 其一","f":"七言律诗","c":["石公来斲鼻端尘，无手人来斧凿亲。","白牯狸奴心即佛，铜睛虎眼主中宾。","自携瓶去沽村酒，幻著衫来作主人。","万里相看如对面，死心寮里有清新。"]},{"t":"寄黄几复","f":"七言律诗","c":["我居北海君南海，寄雁传书谢不能。","桃李春风一杯酒，江湖夜雨十年灯。","持家但有四立壁，治病不蕲三折肱。","想得读书头已白，隔溪猿哭瘴溪藤。"]},{"t":"寄黄从善","f":"七言律诗","c":["故人千里隔谈经，想见牛刀刃发硎。","渴雨芭蕉心不展，未春杨柳眼先青。","凫飞叶县郎官宰，虹贯江南处士星。","天子文思求逆耳，吾宗一为试雷霆。"]},{"t":"寄舒申之户曹","f":"七言律诗","c":["吉州司户官虽小，曾屈诗人杜审言。","今日宣城读书客，还趋手板傍辕门。","江山依旧岁时改，桃李欲开烟雨昏。","公退但呼红袖饮，剩传歌曲教新翻。"]},{"t":"寄新茶与南禅师","f":"五言律诗","c":["筠焙熟香茶，能医病眼花。","因甘野夫食，聊寄法王家。","石钵收云液，铜瓶煮露华。","一瓯资舌本，吾欲问三车。"]},{"t":"寄题瑩中野轩","f":"七言律诗","c":["开轩城市如村落，人似往时陈太邱。","暄景半窗行野马，雨寒疏竹上牵牛。","平生江海心犹在，退食诗书吏罢休。","□□□□□□力，必知耆旧想风流。"]},{"t":"情人怨戏效徐庾慢体三首 其三","f":"五言律诗","c":["障羞罗袂薄，承汗领巾红。","晚风斜虿发，逸艳照窗笼。","胡琴抱明月，宝瑟阵归鸿。","倚壁生蛛网，年光如转蓬。"]},{"t":"情人怨戏效徐庾慢体三首 其二","f":"五言律诗","c":["翡翠钗梁碧，石榴裙摺红。","隙光斜斗帐，香字冷薰笼。","闻道西飞燕，将随北固鸿。","鸳鸯会独宿，风雨打船蓬。"]},{"t":"情人怨戏效徐庾慢体三首 其一","f":"五言律诗","c":["秋水无言度，荷花称意红。","主人敬爱客，催唤出房笼。","一斛明珠曲，何时落塞鸿。","莫藏春笋手，且为剥莲蓬。"]},{"t":"曹村道中","f":"七言律诗","c":["嘶马萧萧苍草黄，金天云物弄微凉。","瓜田馀蔓有荒垄，梨子压枝铺短墙。","明月风烟如梦寐，平生亲旧隔湖湘。","行行秋兴已孤绝，不忍更临山夕阳。"]},{"t":"清明","f":"七言律诗","c":["佳节清明桃李笑，野田荒垄只生愁。","雷惊天地龙蛇蛰，雨足郊原草木柔。","人乞祭馀骄妾妇，士甘焚死不公侯。","贤愚千载知谁是，满眼蓬蒿共一丘。"]},{"t":"渔父二首 其二","f":"七言律诗","c":["草草生涯事不多，短船身外岂知他。","蒹葭浩荡双蓬鬓，风雨飘零一钓蓑。","春鲔出潜留客鲙，秋蕖遮岸和儿歌。","莫言野父无分别，解笑沈江捐汨罗。"]},{"t":"渔父二首 其一","f":"七言律诗","c":["秋风淅淅苍葭老，波浪悠悠白鬓翁。","范子几年思狡兔，吕公何处兆非熊。","天寒两岸识渔火，日落几家收钓筒。","不困田租与王役，一船妻子乐无穷。"]},{"t":"盖郎中惠诗有二强攻一老不战而胜之嘲次韵解之","f":"七言律诗","c":["诗翁琢句玉无瑕，淡墨稀行秋雁斜。","读罢清风生麈尾，吟馀新月度檐牙。","自知拙学无师匠，要且强言遮眼花。","笔力有馀先示怯，真成句践胜夫差。"]},{"t":"雪中连日行役戏书简同僚","f":"七言律诗","c":["简书催出似驱鸡，闻道饥寒满屋啼。","炙背宵眠榾柮火，嚼冰晨饭萨波齑。","风如利剑穿狐腋，雪似流沙饮马蹄。","官小责轻聊自慰，犹胜擐甲去征西。"]},{"t":"黄颍州挽词三首 其三","f":"五言律诗","c":["公与汝阳守，人间孝友稀。","脊令鸣夜雨，常棣倚春晖。","粉省双飞入，泉台相与归。","哀笳宛丘道，衰涕不胜挥。"]},{"t":"黄颍州挽词三首 其二","f":"五言律诗","c":["临民次公老，论事长舆通。","袖有投虚刃，时无斲鼻工。","风流前辈近，名实后人公。","不谓三日别，今成万事空。"]},{"t":"黄颍州挽词三首 其一","f":"五言律诗","c":["恭惟同自出，累世复通家。","惠沫沾枯涸，忠规补过差。","胸中明玉石，仕路困风沙。","尚有平生酒，秋原洒菊花。"]},{"t":"喜太守毕朝散致政","f":"七言律诗","c":["膏火煎熬无妄灾，就阴息迹信明哉。","功名富贵两蜗角，险阻艰难一酒杯。","百体观来身是幻，万夫争处首先回。","胸中元有不病者，记得陶潜归去来。"]},{"t":"喜念四念八至京","f":"七言律诗","c":["朔雪萧萧映薄帏，梦回空觉泪痕稀。","惊闻庭树鸟乌乐，知我江湖鸿雁归。","拂榻喜开姜季被，上堂先着老莱衣。","酒樽烟火长相近，酬劝从今更不违。"]},{"t":"游张公洞","f":"七言律诗","c":["古洞深沉白昼间，烟霞出没绝尘寰。","落红满地花初歇，啼鸟一声春自閒。","丹灶苔荒仙去远，松坛月冷鹤飞还。","我来几欲重登眺，削壁题诗兴不悭。"]},{"t":"登快阁","f":"七言律诗","c":["痴儿了却公家事，快阁东西倚晚晴。","落木千山天远大，澄江一道月分明。","朱弦已为佳人绝，青眼聊因美酒横。","万里归船弄长笛，此心吾与白鸥盟。"]},{"t":"登南禅寺怀裴仲谋","f":"七言律诗","c":["茅亭风入葛衣轻，坐见山河表里清。","归燕略无三月事，残蝉犹占一枝鸣。","天高秋树叶公邑，日暮碧云樊相城。","别后寄诗能慰我，似逃空谷听人声。"]},{"t":"答龙门潘秀才见寄","f":"七言律诗","c":["男儿四十未全老，便入林泉真自豪。","明月清风非俗物，轻裘肥马谢儿曹。","山中是处有黄菊，洛下谁家无白醪。","想得秋来常日醉，伊川清浅石楼高。"]},{"t":"答余洪范二首 其一","f":"五言律诗","c":["道在东西祖，诗如大小山。","一家同雪月，万事废机关。","天上麒麟阁，山中虎豹闲。","何时得丘壑，明镜失朱颜。"]},{"t":"答和孔常父见寄","f":"七言律诗","c":["孔氏文章冠古今，君家兄弟况南金。","为官落魄人谁问，从骑雍容独见寻。","旅馆别时无宿酒，邮筒开处得新吟。","黄山依旧寒相对，岂有愁思附七林。"]},{"t":"答德甫弟","f":"七言律诗","c":["鸟啼花发独愁思，怜子三章怨慕诗。","鸿雁双飞弹射下，脊令同病急难时。","功名所在犹争死，意气相须尚不移。","何况极天无以报，林回投璧负婴儿。"]},{"t":"谢仲谋示新诗","f":"七言律诗","c":["赠我新诗许指瑕，令人失喜更惊嗟。","清于夷则初秋律，美似芙蓉八月花。","采菲直须论下体，鍊金犹欲去寒沙。","唐朝韩老誇张籍，定有云孙作世家。"]},{"t":"道中寄景珍兼简庾元镇","f":"七言律诗","c":["传语濠州贤刺史，隔年诗债几时还。","因循樽俎疏相见，弃掷光阴只等闲。","心在青云故人处，身行红雨乱花间。","遥知别后多狂醉，恼杀江南庾子山。"]},{"t":"韩献肃公挽词三首 其三","f":"五言律诗","c":["泪尽才难日，斯人遽陨倾。","冰枝忧木稼，食昴恨长庚。","名与具茨重，心如颍水清。","堂堂万夫表，直作闭佳城。"]},{"t":"韩献肃公挽词三首 其二","f":"五言律诗","c":["物产原希世，风流更折冲。","决疑京兆尹，富国大司农。","远业终三事，仁声达九宗。","方祈酌周斗，何意辍秦舂。"]},{"t":"韩献肃公挽词三首 其一","f":"五言律诗","c":["郁郁高阳里，生才世不孤。","八龙归月旦，三凤继天衢。","梁坏吾安仰，人亡道固癯。","空令湖海士，愁绝奠生刍。"]},{"t":"新息渡淮","f":"七言律诗","c":["京尘无处可轩眉，照面淮滨喜自知。","风里麦苗连地起，雨中杨树带烟垂。","故林归计嗟迟暮，久客平生厌别离。","落日江南采蘋去，长歌柳恽洞庭诗。"]},{"t":"新喻道中寄元明用觞字韵","f":"七言律诗","c":["中年畏病不举酒，孤负东来数百觞。","唤客煎茶山店远，看人秧稻午风凉。","但知家里俱无恙，不用书来细作行。","一百八盘携手上，至今犹梦绕羊肠。"]},{"t":"稚川约晚过进叔次前韵赠稚川并呈进叔","f":"七言律诗","c":["人骑一马钝如蛙，行向城东小隐家。","道上风埃迷皂白，堂前水竹湛清华。","春归河曲定寒食，公到江南应削瓜。","樽酒光阴俱可惜，端须连夜发园花。"]},{"t":"廖袁州次韵见答并寄黄靖国再生传次韵寄之","f":"七言律诗","c":["春去怀贤感物多，飞花高下罥丝窠。","传闻治境无戾虎，更道丰年鸣白鼍。","史笔纵横窥宝铉，诗才清壮近阴何。","寄声千万相劳苦，如倚胡床得按摩。"]},{"t":"粹老家隔帘听琵琶","f":"七言律诗","c":["马卿劝客且无喧，请以侍儿临酒樽。","妆罢黄昏帘隔面，曲终清夜月当轩。","弦弦不乱拨来往，字字如闻人语言。","千古胡沙埋妙手，岂如桃李在中园。"]},{"t":"静居寺上方南入一径有钓台气象甚古而俗传谬妄意尝有隐君子渔钓其上感之作诗","f":"五言律诗","c":["避世一丘壑，似渔非世渔。","独吟嘉橘颂，不遗子公书。","笋蕨园林晚，丝缗岁月除。","安知冶容子，红袖泣前鱼。"]},{"t":"嘲小德","f":"五言律诗","c":["中年举儿子，漫种老生涯。","学语啭春鸟，涂窗行暮鸦。","欲嗔王母惜，稍慧女兄誇。","解著潜夫论，不妨无外家。"]},{"t":"德孺五丈和之字诗韵难而愈工辄复和成可发一笑","f":"五言律诗","c":["且然聊尔耳，得也自知之。","独笑真成梦，狂歌或似诗。","照滩禽郭索，烧野得伊尼。","早晚来同醉，僧窗卧虎皮。"]},{"t":"摩诘画","f":"五言律诗","c":["丹青王右辖，诗句妙九州。","物外常独往，人间无所求。","袖手南山雨，辋川桑柘秋。","胸中有佳处，泾渭看同流。"]},{"t":"题双凫观","f":"七言律诗","c":["飘萧阅世等虚舟，叹息眼前无此流。","满地悲风盘翠竹，半丛寒日破红榴。","青山空在衣冠古，白鹤不归宫殿秋。","王令平生樽酒地，千年万岁想来游。"]},{"t":"题司门李文园亭","f":"七言律诗","c":["白氏草堂元自葺，陶公三径不教荒。","青蕉雨后开书卷，黄菊霜前碎鹄裳。","落日看山凭曲槛，清风谈道据胡床。","此来遂得归休意，却莫翻然起相汤。"]},{"t":"题吉州承天院清凉轩","f":"五言律诗","c":["菩萨清凉月，游于毕竟空。","我观诸境尽，心与古人同。","僧发侵眉白，桃花映竹红。","傥来寻祖意，展手似家风。"]},{"t":"题安福李令朝华亭","f":"七言律诗","c":["丹楹刻桷上峥嵘，表里江山路眼平。","晓日成霞张锦绮，青林多露缀珠缨。","人如旋磨观群蚁，田似围棋据一枰。","对案昏昏迷簿领，暂来登览见高明。"]},{"t":"题李十八知常轩","f":"七言律诗","c":["身心如一是知常，事不惊人味久长。","盖世功名棋一局，藏山文字纸千张。","无心海燕窥金屋，有意江鸥傍草堂。","惊破南柯少时梦，新晴鼓角报斜阳。"]},{"t":"题杨道人默轩","f":"七言律诗","c":["炙手权门烈火炎，冷溪寒谷反幽潜。","轻尘不动琴横膝，万籁无声月入帘。","秋后丝钱谁数得，春馀苍竹自知添。","客星异日乘槎去，会访成都人姓严。"]},{"t":"题神移仁寿塔","f":"七言律诗","c":["十二观音无正面，谁令塔户向东开。","定知四梵神通力，曾借六丁风雨推。","蝇说冰霜如梦寐，鴳闻钟鼓亦惊猜。","从今不信维摩诘，断取三千世界来。"]},{"t":"题息轩","f":"七言律诗","c":["僧开小槛笼沙界，郁郁参天翠竹丛。","万籁参差写明月，一家寥落共清风。","蒲团禅板无人付，茶鼎薰炉与客同。","万水千山寻祖意，归来笑杀旧时翁。"]},{"t":"题槐安阁","f":"七言律诗","c":["曲阁深房古屋头，病僧枯几过春秋。","垣衣蛛网蒙窗牖，万象纵横不系留。","白蚁战酣千里血，黄粱炊熟百年休。","功成事遂人间世，欲梦槐安向此游。"]},{"t":"题樊侯庙二首 其二","f":"七言律诗","c":["门掩虚堂阴窈窈，风摇枯竹冷萧萧。","邱虚馀意谁相问，丰沛英魂我欲招。","野老无知惟卜岁，神巫何事苦吹箫。","人归里社黄云暮，只有哀蝉伴寂寥。"]},{"t":"题樊侯庙二首 其一","f":"七言律诗","c":["汉兴丰沛开天下，故旧因依日月明。","拔剑一卮戏下酒，剖符千户舞阳城。","鼓刀屠狗少时事，排闼谏君身后名。","异日淮阴傥相见，安能鞅鞅似平生。"]},{"t":"题默轩和遵老","f":"五言律诗","c":["平生三业净，在俗亦超然。","佛事一盂饭，横眠不学禅。","松风佳客共，茶梦小僧圆。","漫续山家颂，非诗莫浪传。"]},{"t":"颜徒贫乐斋二首 其二","f":"五言律诗","c":["小山作友朋，义重子舆桑。","香草当姬妾，不须珠翠妆。","鸟乌窥冻砚，星月入幽房。","儿报无炊米，浩歌绕屋梁。"]},{"t":"赠李辅圣","f":"七言律诗","c":["交盖相逢水急流，八年今复会荆州。","已回青眼追鸿翼，肯使黄尘没马头。","旧管新收几妆镜，流行坎止一虚舟。","相看绝叹女博士，笔研管弦成古丘。"]},{"t":"赠清隐持正禅师","f":"七言律诗","c":["清隐开山有胜缘，南山松竹上参天。","擗开华岳三峰手，参得浮山九带禅。","水鸟风林成佛事，粥鱼斋鼓到江船。","异时折脚铛安稳，更种平湖十顷莲。"]},{"t":"赠惠洪","f":"五言律诗","c":["数面欣羊胛，论诗喜雉膏。","眼横湘水暮，云献楚天高。","堕我玉麈尾，乞君宫锦袍。","月清放舟舫，万里渺云涛。"]},{"t":"赠谢敞王博喻","f":"七言律诗","c":["高哉孔孟如秋月，万古清光仰照临。","千里特来求骥马，两生于此敌南金。","文章最忌随人后，道德无多只本心。","废轸断弦尘漠漠，起予惆怅伯牙琴。"]},{"t":"赠黔南贾使君","f":"七言律诗","c":["绿发将军领百蛮，横戈得句一开颜。","少年圯下传书客，老去崆峒问道山。","春入莺花空自笑，秋成梨枣为谁攀。","何时定作风光主，待得征西鼓吹还。"]},{"t":"懋宗奉议有佳句咏冷庭叟野居庭坚于庭叟有十八年之旧故次韵赠之","f":"七言律诗","c":["城西冷叟半忙閒，人道王阳得早还。","四望楼台皆我有，一原花竹住中间。","初无狗盗窥篱落，底事蛾眉失锁关。","每为朝天三十里，时时惊枕梦催班。"]},{"t":"太和奉呈吉老县丞","f":"五言古诗","c":["山拥鸠民县，江横决事厅。","土风尊健讼，吏道要繁刑。","觟䚦今无种，蒲卢教未形。","里多齐瞯氏，材谢宋庖丁。","令尹三年课，斯人万物灵。","吾方师岂弟，僚友助丹青。"]},{"t":"见诸人唱和酴醾诗辄次韵戏咏","f":"五言古诗","c":["梅残红药迟，此物共春归。","名字因壶酒，风流付枕帏。","坠钿香径草，飘雪净垣衣。","玉气晴虹发，沉材锯屑霏。","直知多不厌，何忍摘令稀。","常恨金沙学，颦时正可挥。"]},{"t":"东观读未见书","f":"五言古诗","c":["汉规群玉府，东观近宸居。","诏许无双士，来观未见书。","皇文开万卷，家学陋三馀。","竹帛森延阁，星辰绕直庐。","诸生起孤贱，天子自吹嘘。","愿以多闻力，论思补帝裾。"]},{"t":"再留几复","f":"五言古诗","c":["客兴敝鹑衣，囊金罄袅蹄。","羸骖多断辔，垢发不胜篦。","道德千年事，穷通一理齐。","晚田犹溉种，稚子且归妻。","径欲眠漳浦，几成访剡溪。","鄙心须澡雪，莲藕在淤泥。"]},{"t":"岁寒知松柏","f":"五言古诗","c":["群阴彫品物，松柏尚桓桓。","老去惟心在，相依到岁寒。","霜严御史府，雨立大夫官。","牺象沟中断，徽弦爨下残。","光阴一鸟过，剪伐万牛难。","春日辉桃李，苍颜亦预观。"]},{"t":"岁寒知松柏","f":"五言古诗","c":["松柏天生独，青青贯四时。","心藏后凋节，岁有大寒知。","惨淡冰霜晚，轮囷涧壑姿。","或容蝼蚁穴，未见斧斤迟。","摇落千秋静，婆娑万籁悲。","郑公扶贞观，已不见封彝。"]},{"t":"戏答宝胜甫长老颂","f":"五言古诗","c":["易拔苍龙角，难参宝胜禅。","林泉饱枯涩，烟月唱清绵。","笑出黄龙手，慵扶阿卯肩。","持刀欺寡妇，盗佛铸私钱。","月黑踰城夜，风高放火天。","解嗤招觉老，担屎污心田。"]},{"t":"次韵邵之才将流民过悬帛岭均田","f":"七言古诗","c":["独贤从是出荒城，下马携筇上石层。","幽洞寻花疑阮肇，断崖长啸想孙登。","欲超浮世挂冠绂，未决重云抚剑棱。","经雨晓烟寒索寞，顺风樵叟震碐磳。","山形春到添高秀，瀑溜冰消转沸腾。","行有流移携襁褓，坐看憔悴拾薪蒸。","素餐每愧斯民病，改作常为法吏绳。","官小责轻须自慰，得逢佳处几人曾。"]},{"t":"次韵和台源诸篇九首 其三 七台溪","f":"七言古诗","c":["先生行乐在清溪，满世功名对画脂。","一道寒波随眼净，百年高柳到天垂。","昔人无处问谁氏，遗础有情犹旧基。","猿鹤至今烟惨淡，贤愚俱尽水涟漪。","四时相及漏催滴，万事不疑冰泮澌。","聊欲烹茶羹杞菊，身如桑苧与天随。"]},{"t":"次韵和魏主簿","f":"五言古诗","c":["梅蕊触人意，绕枝三四旋。","玄冥与之笑，青帝不争权。","帘晚寿阳醉，云深姑射眠。","愁蛾英半落，娇靥菡初圆。","短簿吹羌笛，诸郎宴洞天。","官栖仇览棘，才拍翰林肩。","风力能冰酒，霜威欲折绵。","锦衾寒有恨，花信远难传。","饮罢钟催晓，诗成律换年。","馀香勤管领，莫厌屡中贤。"]},{"t":"次韵曾都曹喜雨","f":"五言古诗","c":["水旱国代有，人神理本通。","遍雩祠小大，敢指蜺雌雄。","地厌焚惔极，天回顾盼中。","蛟龙起乖卧，星斗晦澄空。","云挟雷声走，江翻电脚红。","宠光归稼穑，滴沥在梧桐。","诐讼犹相及，时霖恐未丰。","洁斋蕲得岁，同病托诸公。"]},{"t":"即来","f":"五言古诗","c":["先去岂长别，后来非久亲。","新坟将旧冢，相次似鱼鳞。","茂陵谁辨汉，骊山讵识秦。","千里与昨日，一种并成尘。","定知今世士，还是昔时人。","乌用取他骨，复持埋我身。"]},{"t":"和范廉","f":"五言古诗","c":["一代功名醉，斯人尚独醒。","风霜寒惨淡，松柏后凋零。","岁晚虚前席，天涯作使星。","百城同缓带，列校听横经。","汲直非刀笔，山翁识宁馨。","愁思理前语，祠下柳阴庭。"]},{"t":"送杨瓘雁门省亲二首 其二","f":"五言古诗","c":["蜀客出衰世，独升邹鲁堂。","蚊虻观得失，虎豹擅文章。","吾子已强学，草玄宜不忘。","江河须畎浍，松柏要冰霜。","马策路千里，雁门书数行。","旨甘君有妇，尺璧爱分光。"]},{"t":"送杨瓘雁门省亲二首 其一","f":"七言古诗","c":["执戟老翁年七十，人看生理亦无聊。","草玄事业窥周易，作赋声名动汉朝。","今见远孙勤翰墨，还持遗藁困箪瓢。","三年乡校趋晨鼓，一日边城听夜刁。","野饭盈盘厌葱韭，春风半道解狐貂。","归时定倒迎门屣，问雁安能学度辽。"]},{"t":"效进士作观成都石经","f":"五言古诗","c":["成都九经石，岁久麝煤寒。","字画参工拙，文章可鉴观。","危邦犹劝讲，相国校雕刊。","群盗烟尘后，诸生竹帛残。","王春尊孔氏，乙夜诏甘盘。","愿比求诸野，成书上学官。"]},{"t":"留几复饮","f":"五言古诗","c":["几复平生好，能来屈马蹄。","愈风观草檄，刮膜受金篦。","藏器时难得，忘言物已齐。","买书聊教子，让粟不谋妻。","碧草迷寒梦，丹枫落故溪。","尔时千里恨，且愿醉如泥。"]},{"t":"被褐怀珠玉","f":"五言古诗","c":["国士怀珠玉，通津不易扛。","椟藏心有待，褐短义难降。","宝唾归青简，晴虹贯夜窗。","直言方按剑，岂是故迷邦。","弹雀轻千仞，连城买一双。","安知蓝缕底，明月弄寒江。"]},{"t":"款塞来享","f":"五言古诗","c":["前朝夏州守，来款塞门西。","圣主敷文德，降书付狄鞮。","毡裘瞻日月，剺面带金犀。","殿陛閒干羽，边亭息鼓鼙。","永输量谷马，不作触藩羝。","声势常相倚，今闻定五溪。"]},{"t":"乙卯宿清泉寺","f":"五言古诗","c":["税舆陟高冈，却立倚天壁。","就舆乱清溪，转石飞霹雳。","十步一沮洳，五步一枳棘。","上方未言返，豁见平土宅。","田家鸡犬归，佛庙檀栾碧。","莲荡落红衣，泉泓数白石。","人如安巢鸟，稍就一枝息。","钟鱼各知时，吾亦自得力。"]},{"t":"乙未移舟出口","f":"五言古诗","c":["江湖吞天胸，蛟龙垂涎口。","养躯无千金，特为亲故厚。","本心非华轩，而与马争走。","聘妇缉落毛，教儿耨葱韭。","衣食端须几，将老犹掣肘。","安能诡随人，曲折作杞柳。","桓公瓮盎瘿，楚国不龟手。","生涯但如此，那问托婚友。","久阴快夜晴，天文若科斗。","村南鬼火寒，村北风虎吼。","野人驱鸡豚，缚落坚缠守。","刘郎弓石八，猛气厌冯妇。","一试金仆姑，归饮软臂酒。"]},{"t":"丁巳宿宝石寺","f":"五言古诗","c":["钟磬秋山静，炉香沉水寒。","晴风荡濛雨，云物尚盘桓。","瀹茗赤铜椀，笕泉苍烟竿。","红榴罅玉房，幺橘委金丸。","枕簟已思燠，饭羹可加餐。","观己自得力，谈玄舌本乾。","理窟乃块然，世故浪万端。","牛刀经肯綮，古人贵守官。","摩挲发硎手，考此一丘槃。"]},{"t":"了观师绣观音赞","f":"词","c":["六合内外，若有不观音处。","则此丝缕，不能坚固。","横此三十二应，共此一光明聚。","了观观音，自知金针落处。","知落处，女娲补天夜夜雨。"]},{"t":"二十八宿歌赠别无咎","f":"七言古诗","c":["虎剥文章犀解角，食未下亢奇祸作。","药材根氐罹斸掘，蜜虫夺房抱饥渴。","有心无心材慧死，人言不如龟曳尾。","卫平哆口无南箕，斗柄指日江使噫。","狐腋牛衣同一燠，高丘无女甘独宿。","虚名挽人受实祸，累棋既危安处我。","室中凝尘散发坐，四壁矗矗见天下。","奎蹄曲隈取脂泽，娄猪艾豭彼何择。","倾肠倒胃得相知，贯日食昴终不疑。","古来毕命黄金台，佩君一言等觜觿。","月没参横惜相违，秋风金井梧桐落。","故人过半在鬼录，柳枝赠君当马策。","岁晏星回观盛德，张弓射雉武且力。","白鸥之翼没江波，抽弦去轸君谓何。"]},{"t":"二月二日晓梦会于庐陵西斋作寄陈适用","f":"五言古诗","c":["燕寝著炉香，愔愔閒窗闼。","梦到郡城东，笑谈西斋月。","行乐未渠央，苦遭晴鸠聒。","江郡梅李白，士女嬉城阙。","闻道潘河阳，满城花秀发。","颇留载酒车，共醉生尘袜。","想见舞馀姿，风枝斜虿发。","鄙夫不举酒，春事亦可悦。","雨足肥菌芝，沙暄饶笋蕨。","海牛压风帘，野饭薰僧钵。","饱食愧公家，曾无助毫末。","劝盐推新令，王欲茕独活。","此邦淡食伧，俭陋深次骨。","公囷积丘山，贾竖但圭撮。","县官恩乳哺，下吏用鞭挞。","正恐利一源，未塞兔三窟。","寄声贤令尹，何道补黥刖。","从来无研桑，顾影愧簪笏。","何颜课殿上，解绶行采葛。"]},{"t":"八月十四日夜刀坑口对月奉寄王子难子闻适用","f":"七言古诗","c":["去年对月庐陵郡，醉留歌舞蹋金沙。","今年今夕千峰下，新磨古鉴动菱花。","寒藤老木被光景，深山大泽皆龙蛇。","西风为我奏万籁，落叶起舞惊栖鸦。","遥怜城中二三友，风流惯醉玉钗斜。","今夕传杯定何处，应无二十四琵琶。"]},{"t":"八音歌赠晁尧民 其二","f":"五言古诗","c":["金荷酌美酒，夫子莫留残。","石有补天材，虎豹守九关。","丝窠将柳花，入户扑衣冠。","竹风摇永日，思与子盘桓。","匏瓜岂无匹，自古同心难。","革急而韦缓，只在揉化间。","木桃终报汝，药石理予颜。"]},{"t":"八音歌赠晁尧民 其一","f":"五言古诗","c":["金生寒沙中，见别会有时。","石上千年柏，材高用苦迟。","丝乱犹可理，心乱不可治。","竹斋闻履声，乃是故人来。","匏苦只多叶，水深难为涉。","土床不安席，象床卧烨烨。","革与井同功，守道非关怯。","木直常先伐，樗栎万世叶。"]},{"t":"几复读庄子戏赠","f":"五言古诗","c":["蜩化抢榆枋，鹏化抟扶摇。","大椿万岁寿，粪英不重朝。","有待于无待，定非各逍遥。","譬如宿舂粮，所诣岂得辽。","漆园槁项翁，闻风独参寥。","物情本不齐，显者桀与尧。","烈风号万窍，杂然吹籁箫。","声随器形异，安可一律调。","何尝用吾私，总领使同条。","惜哉向郭误，斯文晚未昭。","胡不弃影事，直以神理超。","木资不才生，雁得不才死。","投身死生中，未可优劣比。","深藏无所用，一寓不得已。","逍遥同我谁，岁暮于吾子。"]},{"t":"几复寄槟榔且答诗劝予同种复次韵寄之","f":"七言绝句","c":["少来不食蚁丘浆，老去得意漆园方。","鉴中已失儿时面，忍能乞与兵作郎。"]},{"t":"十月十三日泊舟白沙江口","f":"五言古诗","c":["岸江倚帆樯，已专北风权。","飞霜挟月下，百笮直如弦。","绿水去清夜，黄芦摇白烟。","篙人持更柝，相语闻并船。","平生濯缨心，鸥鸟共忘年。","风吹落尘网，岁星奔回旋。","险艰自得力，细故可弃捐。","至今梦汹汹，呼禹济广川。"]},{"t":"十四弟归洪州赋莫如兄弟四章赠行 其二","f":"五言绝句","c":["北来哺慈乌，南归护尔雏。","昨夜云飞雁，相随我不如。"]},{"t":"十四弟归洪州赋莫如兄弟四章赠行 其四","f":"五言绝句","c":["大父无恙时，刻意教子弟。","归扫松楸下，泪我万里涕。"]},{"t":"又和斌老病起独游东园二首 其一","f":"五言律诗","c":["西风鏖残暑，如用霍去病。","疏沟满莲塘，扫叶明竹径。","中有寂寞人，自知圆觉性。","心猿方睡起，一笑六窗静。"]},{"t":"又和斌老病起独游东园二首 其二","f":"五言律诗","c":["外物攻伐人，钟鼓作声气。","待渠弓箭尽，我自味无味。","宴安衽席间，蛟鳄垂涎地。","君子履微霜，即知坚冰至。"]},{"t":"又借答送蟹韵并戏小何","f":"七言绝句","c":["草泥本自行郭索，玉人为开桃李颜。","恐似曹瞒说鸡肋，不比东阿举肉山。"]},{"t":"又答斌老病愈遣闷二首 其二","f":"五言律诗","c":["风生高竹凉，雨送新荷气。","鱼游悟世网，鸟语入禅味。","一挥四百病，智刃有馀地。","病来每厌客，今乃思客至。"]},{"t":"又答斌老病愈遣闷二首 其一","f":"五言律诗","c":["百痾从中来，悟罢本谁病。","西风将小雨，凉入居士径。","苦竹绕莲塘，自悦鱼鸟性。","红荷倚翠盖，不点禅心静。"]},{"t":"万州下岩二首 其一","f":"七言绝句","c":["空岩静发钟磬响，古木倒挂藤萝昏。","莫道苍崖锁灵骨，时应持钵到诸村。"]},{"t":"三月乙巳来赋盐万岁乡且蒐狝匿赋之家晏饭此舍遂留宿是日大风自采菊苗荐汤饼二首 其一","f":"七言绝句","c":["飞廉决云开白日，顿撼天地万窍号。","挼挲桃李欲净尽，乞与游丝百尺高。"]},{"t":"三月乙巳来赋盐万岁乡且蒐狝匿赋之家晏饭此舍遂留宿是日大风自采菊苗荐汤饼二首 其二","f":"七言绝句","c":["幽丛秀色可揽撷，煮饼菊苗深注汤。","饮冰食檗浪自古，摩挲满怀春草香。"]},{"t":"三至堂","f":"五言古诗","c":["杨公父子孙，俱出文昌宫。","朱轓与别驾，同最治民功。","当年竹马儿，市上白鬓翁。","相语府门前，郎君有家风。","筑室俯飞鸟，我来岁仲冬。","人烟空橘柚，梅蘤破榛丛。","延客煮茶药，使君语雍容。","畴昔识二父，只今天柱峰。","故开堂北门，突兀在眼中。","千秋万岁后，野人犹致恭。","借问经始谁，开国华阴公。"]},{"t":"三言二首 其二","f":"词","c":["八德水，清且美。","荡精神，浸牙齿。","乱云根，众峰里。","掬与斟，随器尔。"]},{"t":"三言二首 其一","f":"词","c":["寄岳云，安九夏。","无间绿，实潇洒。","碧溪头，古松下。","卧槃陀，昼复夜。"]},{"t":"三笑图赞","f":"词","c":["二豪之所争，不满三隐之一笑。","三隐之所笑，不解耶舍之颜。","耶舍之印，雾锁云埋。","九年面壁，此印方开。"]},{"t":"上大蒙笼","f":"七言古诗","c":["黄雾冥冥小石门，苔衣草路无人迹。","苦竹参天大石门，虎迒兔蹊聊倚息。","阴风搜林山鬼啸，千丈寒藤绕崩石。","清风源里有人家，牛羊在山亦桑麻。","向来陆梁嫚官府，试呼使前问其故。","衣冠汉仪民父子，吏曹扰之至如此。","穷乡有米无食盐，今日有田无米食。","但愿官清不爱钱，长养儿孙听驱使。"]},{"t":"上权郡孙承议","f":"词","c":["公家簿领如鸡栖，私家田园无置锥。","真成忍骂加餐饭，不如西江之水可乐饥。","他人勤拙犹相补，身无功状堪上府。","公诚遣骑束缚归，长随白鸥卧烟雨。"]},{"t":"上冢","f":"五言古诗","c":["自公返蓬荜，税驾上丘垄。","霜露此日悲，松楸千年拱。","养雏数毛羽，初不及承奉。","康州断肠猿，风枝割永痛。","少年不如人，登仕无前勇。","发疏齿牙摇，鲸波怒号汹。","愿为保家子，敢议世轻重。","称觞太夫人，鱼菜赡庖供。"]},{"t":"与六祖长老颂","f":"词","c":["昨夜三更，有人点烛。","烧尽十方，天堂地狱。","不知是谁家之子，都无面目。","但只向深草中藏，莫向孤峰上宿。","斋时有饭，天明有粥。","自然而得，山青水绿。"]},{"t":"与胡彦明处道饮融师竹轩","f":"五言律诗","c":["井寒茶鼎甘，竹密午阴好。","瓜尝邵平种，酒为何侯倒。","倦须槃礴裸，归可倒著帽。","欲去更少留，道人谈药草。"]},{"t":"义松赞","f":"词","c":["西山之松，有岁寒之质。","怀其同气耶，既分矣复合而为一。","涔露云雨，老大霜雪。","匠石辍斤，樵夫叹息。","人之同气，去本未远。","宰上之杞，蔽芾成阴。","有其干戈日寻，余不知其何心。"]},{"t":"乞钟乳于曾公衮","f":"五言律诗","c":["寄语曾公子，金丹几时熟。","愿持钟乳粉，实此罄悬腹。","遥怜蟹眼汤，已化鹅管玉。","刀圭勿妄传，此物非碌碌。"]},{"t":"乞笋于廖宣叔颂","f":"词","c":["龙蜕骨，掉苍尾。","馀戢戢，漫蛇虺。","弃雨中，心烂死。","携长镵，戴篢子。","可尽髡，馘左耳。"]},{"t":"大沩哲禅师真赞","f":"词","c":["即邪是正，即药是病。","乞水指井，乞饭与甑。","杀人如麻，出邪命定。","而得正命，尸罗清净。","而八万四千清净，是谓毗卢遮那正法眼藏。","以平等印封之，以僧伽梨蒙之。","无心者来，弹指门开。","圣凡不尽，金锁生苔。","丹青回互，南北呈露。","影落千江，谁知月处。"]},{"t":"大通禅师真赞","f":"词","c":["前波法涌，后波大通。","大通法涌，彻底澄空。","圆照愿海，千沤一实。","圆通法流，滔天沃日。","三世一念，十方见前。","铜崖铁壁，不可攀缘。","见即弹指，蹉过万千。","大则偏圆异位，通则真假同源。","观者著眼，是传非传。"]},{"t":"大雷口阻风","f":"五言古诗","c":["号橹下沧江，避风大雷口。","天与水模糊，不复知地厚。","谁家上江船，狂追雪山走。","孤村无十室，旅饭困三韭。","黄芦麋鹿场，此地广千肘。","得禽多文章，肯顾鱼贯柳。","莽苍天物悲，彫弓故在手。","鹿鸣犹念群，雉媒竟卖友。","商人万斛船，挂席上牛斗。","横笛倚柁楼，波深苍龙吼。","失水不能神，伐葭作城守。","欲寄大雷书，往问长干妇。","何当楫迎汝，秦淮绿如酒。"]},{"t":"子瞻以子夏丘明见戏聊复戏答","f":"七言律诗","c":["化工见弹太早计，端为失明能著书。","迩来似天会事发，泪睫见光犹陨珠。","喜公新赐紫琳腴，上清虚皇对久如。","请天还我读书眼，愿载轩辕讫鼎湖。"]},{"t":"子瞻诗句妙一世乃云效庭坚体盖退之戏效孟郊樊宗师之比以文滑稽耳恐后生不解故次韵道之","f":"五言古诗","c":["我诗如曹郐，浅陋不成邦。","公如大国楚，吞五湖三江。","赤壁风月笛，玉堂云雾窗。","句法提一律，坚城受我降。","枯松倒涧壑，波涛所舂撞。","万牛挽不前，公乃独力扛。","诸人方嗤点，渠非晁张双。","但怀相识察，床下拜老庞。","小儿未可知，客或许敦厖。","诚堪婿阿巽，买红缠酒缸。"]},{"t":"子瞻题狄引进雪林石屏要同作","f":"五言律诗","c":["翠屏临研滴，明窗玩寸阴。","意境可千里，摇落江上林。","百醉歌舞罢，四郊风雪深。","将军貂狐暖，士卒多苦心。"]},{"t":"己未过太湖僧寺得宗汝为书寄山蓣白酒长韵诗寄答","f":"五言古诗","c":["从学晚闻道，谋官无见功。","早衰观水鉴，内热愧邻邦。","比邻有宗侯，治剧乃雍容。","摩手抚鳏寡，藁砧磔强梁。","桃李与荆棘，称物施露霜。","政经甚缜密，私不蚍蜉通。","吏舍无请赇，家有侯在堂。","府符下盐策，县官劝和羹。","作民敏风雨，令先诸邑行。","我居万夫上，阘惰世无双。","此邑宅岩岩，里中颇秦风。","翁媪无恙时，出分如峰房。","一钱气不直，白梃及父兄。","簪笔怀三尺，揖我谓我臧。","向来豪杰吏，治之以牛羊。","我不忍敌民，教养如儿甥。","荆鸡伏鹄卵，久望羽翼成。","讼端汹汹来，谕去稍听从。","尚馀租庸调，岁岁稽法程。","按图索家资，四壁达牖窗。","掩目鞭扑之，桁杨相推掁。","身欲免官去，驽马恋豆糠。","所以积廪盐，未使户得烹。","八月酾社酒，公私乐年登。","遣徒与会稽，而悉走荻篁。","吾惟不足遣，夙驾略我疆。","邑西軱戾地，是尝婴吾锋。","龈龁其强宗，彼乃可使令。","夙夜于远郊，草露沾帷裳。","入磴履虎尾，扪萝触虿芒。","借问夕何宿，烟边数峰横。","松竹不见天，蟠空作秋声。","谷鸟与溪濑，合弦琵琶筝。","税驾乱石间，岩寺鸣疏钟。","山农颇来服，见其父孙翁。","苦辞王赋迟，户户无积藏。","民病我亦病，呻吟达五更。","韵为诵书语，行歌类楚狂。","举鞭问嘉禾，秣马可及城。","惜哉忧城旦，不得对榻床。","洒笔付飞鸟，北风吹报章。","书回银钩壮，句与麝煤香。","浮蛆拨官醅，倾壶嫩鹅黄。","山气常蓊㔩，此物可屡觞。","蓣药割紫藤，开笼喜手封。","味温颇宜人，芼以石饴姜。","举杯引药糜，咏诗对寒江。","寄声甚劳苦，相思秋月明。","我邑万户乡，其民资嚚凶。","欲割以寿公，使之承化光。","反以来寿我，中有吞舟鲸。","铜墨俱王命，职思慰孤茕。","何时赌一掷，烧烛咒明琼。"]},{"t":"不俗轩耐閒轩颂","f":"词","c":["不爱孔方乃不俗，放下利欲是耐閒。","棒打石狮子，论实不论虚。"]},{"t":"丰城","f":"五言古诗","c":["丰城邑岩岩，水种六万户。","石堤眠长虹，辍棹日沈雾。","令君政有声，新亭延客步。","泪落世父碑，心倾文饶赋。","忆昔两神兵，埋玉思武库。","寒光射汉津，两贤纡一顾。","张公拆中台，木拱孔章墓。","不能从儿嬉，岁晚龙蛇去。","空馀寒泉泓，因雨长蛙鲋。","铅刀藏宝室，万世同此度。"]},{"t":"为茭桥居士作念念即佛颂","f":"词","c":["诸佛心内，众生心心作佛。","众生心中，诸佛念念證真。","君言诸佛无相，山鬼窟里安葬。","即今十二时中，是谁随波逐浪。"]},{"t":"为黄龙心禅师烧香颂三首 其二","f":"七言绝句","c":["一拳打破鬼门关，一笑吐却野狐涎。","四海峥嵘龙象众，鼻头只用短绳牵。"]},{"t":"为黄龙心禅师烧香颂三首 其一","f":"七言绝句","c":["老师身今七十六，老师心亦七十六。","梦中沈却大法船，文殊顿足普贤哭。"]},{"t":"为慧林冲禅师烧香颂三首 其一","f":"七言绝句","c":["昨夜三更狗吠雪，东家闭门推出月。","是渠觉海性澄圆，衲子杀人须见血。"]},{"t":"为慧林冲禅师烧香颂三首 其三","f":"词","c":["西瞿耶尼开静，北郁单越受粥。","慧林也唱云门曲，去年腊月六十六。"]},{"t":"书东坡画郭功父壁上墨竹","f":"七言古诗","c":["郭家髹屏见生竹，惜哉不见人如玉。","凌厉中原草木春，岁晚一棋终玉局。","巨鳌首戴蓬莱山，今在琼房第几间。"]},{"t":"书石牛溪旁大石上","f":"七言律诗","c":["郁郁窈窈天官宅，诸峰排霄帝不隔。","六时谒天开关钥，我身金华牧羊客。","羊眠野草我世閒，高真众灵思我还。","石盆之中有甘露，青牛驾我山谷路。"]},{"t":"书蔡秀才屏风颂四首 其二","f":"七言绝句","c":["接人高下但唯唯，笑语相随不作难。","此翁胸次有泾渭，事不可处执如山。"]},{"t":"书蔡秀才屏风颂四首 其三","f":"七言绝句","c":["此翁家世印累累，平生俯视造物儿。","堪笑痴人不省误，犹说此翁真个痴。"]},{"t":"书蔡秀才屏风颂四首 其一","f":"七言绝句","c":["武宁县中蔡老子，能棋能酒又能诗。","胸中百万多罗藏，不向人间说是非。"]},{"t":"书磨崖碑后","f":"七言古诗","c":["春风吹船著浯溪，扶藜上读中兴碑。","平生半世看墨本，摩挲石刻鬓成丝。","明皇不作苞桑计，颠倒四海由禄儿。","九庙不守乘舆西，万官已作乌择栖。","抚军监国太子事，何乃趣取大物为。","事有至难天幸尔，上皇局蹐还京师。","内间张后色可否，外閒李父颐指挥。","南内凄凉几苟活，高将军去事尤危。","臣结舂陵二三策，臣甫杜鹃再拜诗。","安知忠臣痛至骨，世上但赏琼琚词。","同来野僧六七辈，亦有文士相追随。","断崖苍藓对立久，涷雨为洗前朝悲。"]},{"t":"予欲金玉汝赠黄从善","f":"楚辞体","c":["江山复重兮朋友失，长处幽篁兮隔离天日。","鸟声无人兮我友来即，久矣不闻德人之言兮，为余发药。","嘉若人兮甚好修，兰薰而时发兮，水刚德而用柔。","有璞连城，方谟匠兮，忍其与斗筲议之。","螫吾手而不砭兮，举百体而弃之。","为民父母兮，灼子之肤，何能忍。","顾白日临辰兮，臣何爱不与俱来。","古之人偿责言兮，虽九死其犹未悔。","虹气贯斗牛兮，岂用俗人之町畦。","予爱兰而莫与予佩兮，曰斯其不情。","帝关九牡兮，照下土孔明。","予将观东海兮，蛙说予以坎井。","盍尝视吾宝兮，兹有重于岑鼎。","予欲金玉汝兮，汝既金玉。","揭日月以适四方兮，殆而按剑以为戮。","雁以不鸣烹，木以材而斲。","天下皆羿兮，矢来无乡，惟应以无名之朴。"]},{"t":"云居祐禅师烧香颂","f":"七言绝句","c":["一身入定千身出，云居不打这鼓笛。","虎驮太华入高丽，波斯鼻孔撑白日。"]},{"t":"云盖智和尚真赞","f":"词","c":["哆哆啝啝，搭猱左科。","吃十方饭，唱快活歌。","任疏慵，没礼数。","赶则去，招则住。","住似著衫，去如脱裤。","禅徒苦口劝和光，捏聚虚空要泊路。"]},{"t":"五老亭","f":"七言律诗","c":["白发苍髯五老人，德虽不孤世无邻。","松风忘味同戴舜，梅雨蒙头非避秦。","筑亭风流二千石，此老入谒官不嗔。","一樽相对是宾友，学得养生通治民。"]},{"t":"五祖演禅师真赞","f":"五言古诗","c":["问道白云端，蹋著自家底。","无心万事禅，一月千江水。","路逢摩登伽，石上漫浇水。","赤土画簸箕，也有第一义。","谁言川藞䕢，具相三十二。"]},{"t":"从王都尉觅千叶梅云已落尽戏作嘲吹笛侍儿","f":"七言绝句","c":["若为可耐昭华得，脱帽看发已微霜。","催尽落梅春已半，更吹三弄乞风光。"]},{"t":"从斌老乞苦笋","f":"七言绝句","c":["南园苦笋味胜肉，箨龙称冤莫采录。","烦君更致苍玉束，明日风雨皆成竹。"]},{"t":"以十扇送徐天隐","f":"七言律诗","c":["人贫鹅雁聒邻墙，公贫琢诗声绕梁。","坐客有毡吾不爱，暑榻无扇公自凉。","党锢诸生尊孺子，建安七人先伟长。","遣奴送箑非为好，恐有佳客或升堂。"]},{"t":"以小团龙及半挺赠无咎并诗用前韵为戏","f":"七言古诗","c":["我持玄圭与苍璧，以暗投人渠不识。","城南穷巷有佳人，不索宾郎常晏食。","赤铜茗椀雨斑斑，银粟翻光解破颜。","上有龙文下棋局，探囊赠君诺已宿。","此物已是元丰春，先皇圣功调玉烛。","晁子胸中开典礼，平生自期莘与渭。","故用浇君磊隗胸，莫令鬓毛雪相似。","曲几团蒲听煮汤，煎成车声绕羊肠。","鸡苏胡麻留渴羌，不应乱我官焙香。","肥如瓠壶鼻雷吼，幸君饮此勿饮酒。"]},{"t":"以双井茶送孔常父","f":"七言律诗","c":["校经同省并门居，无日不闻公读书。","故持茗椀浇舌本，要听六经如贯珠。","心知韵胜舌知腴，何似宝云与真如。","汤饼作魔应午寝，慰公渴梦吞江湖。"]},{"t":"以古铜壶送王观复","f":"五言古诗","c":["随俗易汩没，从公常纠纷。","我观王隆化，入莸不改薰。","未见蛇起陆，已看豹成文。","爱君古人风，古壶投赠君。","酌酒时在傍，可用弭楚氛。","问君何以报，直谅与多闻。"]},{"t":"以右军书数种赠邱十四","f":"七言古诗","c":["邱郎气如春景晴，风暄百果草木生。","眼如霜鹘齿玉冰，拥书环坐爱窗明。","松花泛砚摹真行，字身藏颖秀劲清，问谁学之果兰亭。","我昔颇复喜墨卿，银钩虿尾烂箱籯，赠君铺案黏曲屏。","小字莫作痴冻蝇，乐毅论胜遗教经。","大字无过瘗鹤铭，官奴作草欺伯英。","随人作计终后人，自成一家始逼真。","卿家小女名阿潜，眉目似翁有精神。","试留此书他日学，往往不减卫夫人。"]},{"t":"以皮鞋底赠石推官三首 其三","f":"五言绝句","c":["鼻孔随人走，日中忽见斗。","踏定太冲脉，壁上挂着口。"]},{"t":"以皮鞋底赠石推官三首 其二","f":"五言绝句","c":["毗卢足趺光，照耀世界海。","旋岚黑风起，到岸得自在。"]},{"t":"以皮鞋底赠石推官三首 其一","f":"五言绝句","c":["道人不凋琢，万镜自明己。","愿公勤此履，深彻法源底。"]},{"t":"以同心之言其臭如兰为韵寄李子先 其六","f":"五言律诗","c":["穷阎蒿蔓膻，富屋酒肉臭。","酒肉令人肥，蒿蔓令人瘦。","欲从钟鼎食，复恐忧患构。","秦时千户侯，寂寞种瓜后。"]},{"t":"以同心之言其臭如兰为韵寄李子先 其五","f":"五言律诗","c":["携手力不足，七年坐乖离。","愁思不能眠，起视夜何其。","残月挂破镜，寒星满天垂。","明明故人心，维斗终不移。"]},{"t":"以同心之言其臭如兰为韵寄李子先 其四","f":"五言律诗","c":["摧藏褫冠冕，寂寞归丘园。","一瓢俱好学，伯仲吹篪埙。","正以此易彼，高车择朱门。","得失固有在，难为欲人言。"]},{"t":"以同心之言其臭如兰为韵寄李子先 其二","f":"五言律诗","c":["流水鸣无意，白云出无心。","水得平淡处，渺渺不厌深。","云行不能雨，还归碧山岑。","斯人似云水，廊庙等山林。"]},{"t":"以同心之言其臭如兰为韵寄李子先 其八","f":"五言律诗","c":["吾子有嘉德，譬如含薰兰。","清风不来过，岁晚蒿艾间。","古来百夫雄，白首在涧槃。","非关自取重，直为知人难。"]},{"t":"以同心之言其臭如兰为韵寄李子先 其一","f":"五言律诗","c":["往日三语掾，解道将无同。","我观李校书，超迈有古风。","谈道屡入微，闭门长蒿蓬。","谁能赏远韵，太守似安丰。"]},{"t":"以团茶洮州绿石砚赠无咎文潜","f":"词","c":["晁子智囊可以括四海，张子笔端可以回万牛。","自我得二士，意气倾九州。","道山延阁委竹帛，清都太微望冕旒。","贝宫胎寒弄明月，天网下罩一日收。","此地要须无不有，紫皇访问富春秋。","晁无咎，赠君越侯所贡苍玉璧，可烹玉尘试春色。","浇君胸中过秦论，斟酌古今来活国。","张文潜，赠君洮州绿石含风漪，能淬笔锋利如锥。","请书元祐开皇极，第入思齐访落诗。"]},{"t":"以峡州酒遗益修复继前韵","f":"五言古诗","c":["令节不把酒，新诗徒拜嘉。","颇忆宋玉赋，登高气成霞。","渚宫但衰柳，朝云为谁誇。","吾宗怀古恨，流涎过曲车。","一壶浇往事，聊送解愁嗟。"]},{"t":"以香烛团茶琉璃献花碗供布袋和尚颂 其一","f":"五言绝句","c":["一钵千家饭，孤身万里浮。","知音若相问，不住涅槃州。"]},{"t":"以酒渴爱江清作五小诗寄廖明略学士兼简初和父主簿 其一","f":"五言律诗","c":["将发沔鄂间，尽醉竹林酒。","二三石友辈，未肯弃老朽。","借问坐客谁，卢溪紫髯叟。","此翁今惜醉，旧不论升斗。"]},{"t":"以酒渴爱江清作五小诗寄廖明略学士兼简初和父主簿 其五","f":"五言律诗","c":["斯人绝少可，白眼视公卿。","每与俗物逢，三沐取洁清。","我亦漫浪者，君何许同盟。","试问卢溪叟，犹得多可名。"]},{"t":"以酒渴爱江清作五小诗寄廖明略学士兼简初和父主簿 其二","f":"五言律诗","c":["平生思故人，江汉不解渴。","谁言放逐地，烧烛饮至跋。","忧予先狗马，劝以爱肤发。","有罪当窜流，但惧不得活。"]},{"t":"以酒渴爱江清作五小诗寄廖明略学士兼简初和父主簿 其四","f":"五言律诗","c":["竹林文章伯，国士无与双。","比来少制作，非以弱故降。","景阳机中锦，犹衣被丘江。","时时能度曲，秀句入新腔。"]},{"t":"以酒渴爱江清作五小诗寄廖明略学士兼简初和父主簿 其三","f":"五言律诗","c":["廖侯劝我酒，此亦雅所爱。","中年刚制之，常惧作灾怪。","连台盘拗倒，故人不相贷。","谁能知许事，痛饮且一快。"]},{"t":"以椰子茶瓶寄德孺二首 其一","f":"五言律诗","c":["硕果霣林梢，可以代悬匏。","携持二十年，煮茗当酒肴。","我今禦魑魅，学打衲僧包。","聊持坚重器，遗我金石交。"]},{"t":"以椰子茶瓶寄德孺二首 其二","f":"五言律诗","c":["炎丘椰木实，入用随茗椀。","譬如楛矢砮，但贵从来远。","往时万里物，今在篱落间。","知公一拂拭，想我瘴雾颜。"]},{"t":"元丰癸亥经行石潭寺见旧和栖蟾诗甚可笑因削柎灭藁别和一章","f":"七言律诗","c":["千里追奔两蜗角，百年得意大槐宫。","空馀祗夜数行墨，不见伽梨一臂风。","俗眼只如当日白，我颜非复向来红。","浮生不作游丝上，即在尘沙逐转蓬。"]},{"t":"元师自荣州来追送余于泸之江安绵水驿因复用旧所赋此君轩诗韵赠之并简元师法弟周彦公","f":"七言古诗","c":["岁行辛巳建中年，诸公起废自林泉。","王师侧闻陛下圣，抱琴欲奏南风弦。","孤臣蒙恩已三命，望尧如日开金镜。","但忧衰疾不敢前，眼前黑花耳闻磬。","岂如道人山绕门，开轩友此岁寒君。","能来作诗赏劲节，家有晓事扬子云。","箨龙森森新间旧，父翁老苍孙子秀。","但知战胜得道肥，莫问无肉令人瘦。","是师胸中抱明月，醉翁不死起自说。","竹影生凉到屋椽，此声可听不可传。"]},{"t":"元翁坐中见次元寄到和孔四饮王夔玉家长韵因次韵率元翁同作寄湓城","f":"五言古诗","c":["雨罢山泽明，日长花柳困。","游丝上天衢，观物得无闷。","时从顾曲人，笋馔酌春酝。","季子未识面，想见眉目俊。","新诗如鸣弦，快读开鄙吝。","铜官鲁诸生，事道三无愠。","比来工五字，句法妙何逊。","枯棋覆吴图，青简玩秦烬。","叶暗黄鸟时，风号报花信。","遥仰吟思苦，江锦割向尽。","应烦王公子，又破黄封印。"]},{"t":"六月闵雨","f":"七言律诗","c":["汤帝咨嗟惩六事，汉庭灾异劾三公。","圣朝罪己恩宽大，时雨愆期旱蕴隆。","东海得无冤死妇，南阳疑有卧云龙。","传闻已减大官膳，肉食诸君合奏功。"]},{"t":"六舅以诗来觅铜犀用长句持送舅氏学古之馀复味禅悦故篇末及之","f":"七言古诗","c":["海牛压纸写银钩，阿雅守之索自收。","长防玩物败儿性，得归老成散百忧。","先生古心冶金铁，堂堂一角谁能折。","儿言觳觫持赠谁，外家子云乃翁师。","不著鼻绳袖两手，古犀牛儿好看取。"]},{"t":"劝石洞道真师染袈裟颂","f":"词","c":["丈夫出家，当被坏色衣。","蜀僧袈裟，多似苾刍。","轻罗绉縠，染成春柳丝。","撩蜂引蝶，唯欠远山眉。"]},{"t":"化毡颂","f":"词","c":["夺却群生夏衣，成得衲僧卧具。","为伊业识茫茫，所以一夺一与。","三百四百野狐队，中有一两个不瞌睡。","十方虚空百杂碎，宁不打破悭皮袋。"]},{"t":"午寝","f":"五言古诗","c":["读书常厌烦，燕处意坐驰。","动静两不适，尘劳败天倪。","目昏生黟花，耳聩喧鼓鼙。","沈忧愁五神，倦剧委四支。","不聊终日堪，况乃久远期。","投书曲肱卧，天游从所之。","是身入华胥，彷佛胜初时。","春蚕眠巨箔，夏蜩化枯枝。","今之隐几者，岂有异子綦。","觉寐须臾閒，良亦休我疲。","乃知大觉梦，盖此德之归。","谁为今日是，二十二年非。"]},{"t":"双井茶送子瞻","f":"七言律诗","c":["人间风日不到处，天上玉堂森宝书。","想见东坡旧居士，挥毫百斛泻明珠。","我家江南摘云腴，落硙霏霏雪不如。","为君唤起黄州梦，独载扁舟向五湖。"]},{"t":"太平寺慈氏阁","f":"七言律诗","c":["青玻瓈盆插千岑，湘江水清无古今。","何处拭目穷表里，太平飞阁暂登临。","朝阳不闻皂盖下，愚溪但见古木阴。","谁与洗涤怀古恨，坐有佳客非孤斟。"]},{"t":"文安国挽词二首 其一","f":"五言律诗","c":["七闽家举子，百粤海还珠。","往日推忠厚，穷年领转输。","一床遗杖屦，万事委锱铢。","岂有苍茫恨，归巢未拮据。"]},{"t":"文勋真赞","f":"词","c":["荣如辱如，谁丧谁得。","萃如嗟如，不见声色。","为吏不残，去其败群。","好贤喜士，黾勉而勤。","子克家，吾税驾。","舍几而寝，漠然即化。","眉目在图，慰尔时思。","蔼然粹温，似无恙时。"]},{"t":"木之彬彬","f":"词","c":["木之彬彬，非取异于人。","可宫室则斩则伐，可笾豆则捋则撷。","草之茸茸，非求显于世。","中刍牧则刈则锄，中医和则剥则枯。","非以其材故耶，是非之歧，利害薰蒸。","嗟人道之多患，彼草木尚无情。","吾尝观于若人矣，巧于辨人，拙于自辨。","好动乎天机，不周乎时变。","罪莫惨于德有心，祸莫深于心有见。","罪不在德，心其蟊贼，祸不在心。","见其髡钳之人也，皦皦自鲜，行于众污之前。","峣峣不让，立乎众埤之上。","积小不当，是以亡其大当。","悲夫！","羿注矢以当物，十尝中其七八。","引镆铘以自残，骇兕虎之窃发。","祸集于所忽，怨栖于荣名。","易其言则害智，用其智则害明。","为君子则奈何，独见晓于冥冥。"]},{"t":"王圣涂二亭歌","f":"楚辞体","c":["营丘之下，有宅有田。","梨枣兮觞豆，耘耔兮为年。","鸡栖埘兮羊豕在牧，课儿子兮蓺松菊。","炙背兮墙东，梦覆舟兮涛且风。","洋之回兮可以驾，孙甥扶舆兮父老同社。","洋之水兮可以舟入，鸥鸟兮与之游。","一世兮蜉蚁，桑榆兮憖可收。","从此休兮，公谁黄发之休。","伟长松兮卧龙蛇，阅千岁兮不改其柯。","震雷不惊兮，谁欲休之以蜩蛭。","下有锦石兮可用杯勺，云月供帐兮万籁奏乐。","石子磊磊兮涧谷纵横，春月桃李兮士女倾城。","时雨霖兮忽若海潦收，无事兮我以观万物之情。","儿时所蓺兮桃李纤纤，随世风波兮吹而北南。","昔去兮拱把，今归兮与天参。","与古人兮合契，树如此兮我何以堪。","鸿雁嗷兮或在洲渚，有心于粒兮弋者所取。","飞冥冥兮渺万里而绝，去薮泽之罗者兮官予落羽。"]},{"t":"王充道送水仙花五十枝欣然会心为之作咏","f":"七言律诗","c":["凌波仙子生尘袜，水上轻盈步微月。","是谁招此断肠魂，种作寒花寄愁绝。","含香体素欲倾城，山矾是弟梅是兄。","坐对真成被花恼，出门一笑大江横。"]},{"t":"见子瞻粲字韵诗和答三人四返不困而愈崛奇辄次韵寄彭门三首 其二","f":"五言古诗","c":["人生等尺捶，岂耐日取半。","谁能如秋虫，长夜向壁叹。","朝四与暮三，适为狙公玩。","臭腐暂神奇，喑噫即飘散。","我观万世中，独立无介伴。","小黠而大痴，夜气不及旦。","低首甘豢养，尻脽登俎案。","所以终日饮，醉眠朱碧乱。","无人明此心，忍垢待濯盥。","仰看东飞云，只使衣带缓。","先生古人学，百氏一以贯。","见义勇必为，少作衰俗懦。","忠言愿回天，不忍敩吞炭。","还从股肱郡，待诏图书馆。","投壶得赐金，侏儒馀饱暖。","宁令东方公，但索长安粲。"]},{"t":"见子瞻粲字韵诗和答三人四返不困而愈崛奇辄次韵寄彭门三首 其一","f":"五言古诗","c":["公才如洪河，灌注天下半。","风日未尝撄，昼夜圣所叹。","名世二十年，穷无歌舞玩。","入宫又见妒，徒友飞鸟散。","一饱事难谐，五车书作伴。","风雨暗楼台，鸡鸣自昏旦。","虽非锦绣赠，欲报青玉案。","文似离骚经，诗窥关雎乱。","贱生恨学晚，曾未奉巾盥。","昨蒙双鲤鱼，远托郑人缓。","风义薄秋天，神明还旧贯。","更磨荐祢墨，推挽起疲懦。","忽忽未嗣音，微阳归候炭。","仁风从东来，拭目望斋馆。","鸟声日日春，柳色弄晴暖。","漫有酒盈樽，何因见此粲。"]},{"t":"见子瞻粲字韵诗和答三人四返不困而愈崛奇辄次韵寄彭门三首 其三","f":"五言古诗","c":["元龙湖海士，毁誉略相半。","下床卧许君，上床自永叹。","丈夫属有念，人物非所玩。","坐令结欢客，化为烟雾散。","武功有大略，亦复寡朋伴。","咏歌思见之，长夜鸣曷旦。","东南望彭门，官道平如案。","简书束缚人，一水不能乱。","斯文媲秬鬯，可用圭瓒盥。","诚求活国医，何忍弃和缓。","开疆日百里，都内钱朽贯。","铭功甚俊伟，乃见儒生懦。","且当置是事，勿使冰作炭。","上帝群玉府，道家蓬莱馆。","曲肱夏簟寒，炙背冬屋暖。","只令文字垂，万世星斗粲。"]},{"t":"见翰林苏公马祖庞翁赞戏书","f":"词","c":["一口吸尽西江水，磨却马师三尺觜。","马驹蹋杀天下人，惊雷破浪非凡鳞。","马祖庞公，水泄不通。","游鯈方乐，科斗生角。"]},{"t":"长句谢陈适用惠送吴南雄所赠纸","f":"七言古诗","c":["庐陵政事无全牛，恐是汉时陈太丘。","书记姓名不肯学，得纸无异夏得裘。","琢诗包纸送赠我，自状明月非暗投。","诗句纵横剪宫锦，惜无阿买书银钩。","蛮溪切藤卷盈百，侧理羞滑茧羞白。","想当鸣杵砧面平，桄榔叶风溪水碧。","千里鹅毛意不轻，瘴衣腥腻北归客。","君侯谦虚不自供，胡不赠世文章伯。","一涔之水容牛蹄，识字有数我自知。","小时双钩学楷法，至令儿子憎家鸡。","虽然嘉惠敢虚辱，煮泥续尾成大轴。","写心与君心莫传，平生落魄不问天。","樽前花底幸好戏，为君绝笔谢风烟。","已无商颂猗那手，请续南华内外篇。"]},{"t":"长芦夫和尚真赞","f":"词","c":["松枯竹瘦，是其岁寒也。","山高水深，不可犯干也。","取多国士，庄严此土，如陶家手也。","拂除方丈，置榻而坐，一不受也。","首出万物，渊默雷吼，寂寥者之参也。","若夫以法界印，印毛印海，则惊僧繇而走巫咸也。"]},{"t":"长短星歌","f":"词","c":["正月虎，七泽阴风无避处。","少年射杀白额归，二十一岁赐旗鼓。","二月兔，翰墨功名归四杜。","中山毛遂定从还，十九上客谁复数。","三月龙，定力降来一钵中。","升腾便欲致云雨，十六开士观云风。","四月蛇，九蛇相辅成晋家。","屈原离骚二十五，不及之推死怨嗟。","五月马，十五国风多咏写。","汉将西极天马来，二十五城不当价。","六月羊，十岁小儿牧道傍。","他年叱石金华路，二十年前身姓黄。","七月猴，恒山八命列封侯。","当年传国二十二，想是衣冠骑土牛。","八月鸡，二妙灵台向晓啼。","五更风雨十八九，残月昏昏信可期。","九月狗，三窟深坑四荒走。","暮归得兔十六七，黄卢朱雀皆在后。","十月猪，白头一笑献士夫。","杀身愿为鲁津伯，申封兰王十四都。","十一月鼠，列十二辰配龙虎。","二十二年看仙飞，一朝化作蝙蝠去。","十二月牛，百户椎肥醉九州。","角端围寸二十五，良弓之材牛带牛。"]},{"t":"丙申泊东流县","f":"五言古诗","c":["前日发大雷，真成料虎头。","今日伐鼓出，棹歌傲阳侯。","沧江百折来，及此始东流。","东流会宾客，建德椎羊牛。","野语尚信然，小市黄芦洲。","惟有采薪翁，经营往来舟。","槠枥尽斤斧，山童烟雨愁。"]},{"t":"丙辰仍宿清泉寺","f":"五言古诗","c":["山农居负山，呼集来苦迟。","既来授政役，谣诼谓余欺。","按省其家赀，可忍鞭抶之。","恩言谕公家，疑阻久乃随。","滕口终自愧，吾敢乏王师。","官宁惮淹留，职在拊茕嫠。","所将部曲多，溷汝父老为。","西山失半壁，且复下囊辎。","啼鸦散篇帙，休吏税巾衣。","石泉鼓坎坎，竹风吹参差。","书冷行熠耀，壁虫催杼机。","昏釭夜未央，高枕梦登巘。"]},{"t":"丙寅十四首效韦苏州 其三","f":"五言古诗","c":["渐嘉楼外花，嘉赏亭边柳。","作者归山丘，今春为谁有。","千秋万岁后，还复来游否。"]},{"t":"丙寅十四首效韦苏州 其九","f":"五言古诗","c":["谢甥有逸兴，李髯非不嘉。","苦思梦春草，醉狂眠酒家。","斯游无俗物，傲睨至昏鸦。"]},{"t":"丙寅十四首效韦苏州 其十四","f":"五言古诗","c":["少小尚狷介，与人常不款。","置身稍雍容，遇酒辄引满。","自是鹤足长，难齐凫胫短。"]},{"t":"丙寅十四首效韦苏州 其八","f":"五言古诗","c":["庭空日色静，楼迥钟声迟。","褐叟已争席，驯鸦更不疑。","同来复同去，竟别我为谁。"]},{"t":"丙寅十四首效韦苏州 其十三","f":"五言古诗","c":["出身世丧道，解绶饥驱我。","杯中得醉乡，去就不复果。","岂为俗人言，达人傥余可。"]},{"t":"丙寅十四首效韦苏州 其二","f":"五言古诗","c":["不知鞍马倦，想见洲渚春。","清昼锁芳园，谁家停画轮。","高柳极有思，向风招游人。"]},{"t":"丙寅十四首效韦苏州 其十","f":"五言古诗","c":["寺古老僧静，亭阴脩竹多。","莱公作州日，部曲屡经过。","众推识公面，苍石眠绿莎。"]},{"t":"丙寅十四首效韦苏州 其十一","f":"五言古诗","c":["盛时众吹嘘，谪去众毁辱。","不为公存亡，幽兰春自绿。","欲书名相传，安得南山竹。"]},{"t":"丙寅十四首效韦苏州 其一","f":"五言古诗","c":["雪霁草木动，春融烟景和。","嘉晨掩关坐，如此节物何。","同游得二子，晤对不在多。"]},{"t":"丙寅十四首效韦苏州 其四","f":"五言古诗","c":["城南有佳园，风物迎马首。","但赏主人竹，不饮主人酒。","红日媚紫苔，轻风泛春柳。"]},{"t":"丙寅十四首效韦苏州 其七","f":"五言古诗","c":["我思五柳翁，解作一生事。","得钱送酒家，便静寻山寺。","念我还如此，翁应会人意。"]},{"t":"丙寅十四首效韦苏州 其五","f":"五言古诗","c":["三公未白发，十辈乘朱轮。","只取人看好，何益百年身。","但愿长今日，清樽对故人。"]},{"t":"丙寅十四首效韦苏州 其六","f":"五言古诗","c":["江梅香冷淡，开遍未全疏。","已有耐寒蝶，双飞上花须。","今夜严城角，肯留花在无。"]},{"t":"丙寅十四首效韦苏州 其十二","f":"五言古诗","c":["昔公调鼎实，指顾九庙尊。","郡国富士马，于今开塞垣。","谁能起公死，为国守北门。"]},{"t":"东坡先生真赞三首 其二","f":"词","c":["岌岌堂堂，如山如河。","其爱之也，引之上西掖銮坡。","是亦一东坡，非亦一东坡。","槁项黄馘，触时干戈。","其恶之也，投之于鲲鲸之波。","是亦一东坡，非亦一东坡。","计东坡之在天下，如太仓之一稊米。","至于临大节而不可夺，则与天地相终始。"]},{"t":"东坡先生真赞三首 其一","f":"词","c":["子瞻堂堂，出于峨眉，司马班扬。","金马石渠，阅士如墙。","上前论事，释之冯唐。","言语以为阶，而投诸云梦之黄。","东坡之酒，赤壁之笛。","嬉笑怒骂，皆成文章。","解羁而归，紫微玉堂。","子瞻之德，未变于初尔。","而名之曰元祐之党，放之珠厓儋耳。","方其金马石渠，不自知其东坡赤壁也。","及其东坡赤壁，不自意其紫微玉堂也。","及其紫微玉堂，不自知其珠厓儋耳也。","九州四海，知有东坡。","东坡归矣，民笑且歌。","一日不朝，其间容戈。","至其一丘一壑，则无如此道人何。"]},{"t":"代书","f":"五言古诗","c":["阿熊去我时，秋暑削甘瓜。","离别日月除，莲房倒箭靫。","得书报平安，肥字如栖鸦。","汝才跃炉金，自必为镆铘。","穷年抱新书，挽条咀春葩。","弄笔不能休，屈宋欲作衙。","屈指推日星，许身上云霞。","安知九天关，虎豹守夜叉。","祝田操豚蹄，持狭所欲奢。","文章六经来，汗漫十牛车。","譬如观沧海，细大极龙虾。","古人以圣学，未肯废百家。","旧山木十围，斋堂绿阴遮。","红稻香盂饭，黄鸡厌食鲑。","摩挲垂腴腹，颇复读书耶。","念汝齿壮矣，无妇助烹茶。","父兄亦怜汝，须儿牧犬豭。","且伐千章木，赠行当马檛。","赢粮果后时，定随八月槎。","觉民在林中，丁丁闻兔罝。","奉身甚和友，干父办咄嗟。","台源吟松籁，先生岸巾纱。","留客醉风月，盘箸供柔嘉。","仍工朱丝弦，洗心拂奇邪。","孤臣发楚调，倾国怨胡笳。","把笔学周鼓，字形锥画沙。","诗书乃宿好，不为蓬生麻。","元明祖师禅，妙手发琵琶。","已无富贵心，鼓吹一池蛙。","天民服农圃，颇复秋敛赊。","下田督未耘，入岭按新畬。","悉力输王赋，至今困生涯。","知命叔山徒，炉香严佛花。","惟思苾刍园，脱冠著袈裟。","起家望两季，佩金蹋朝靴。","嘉鱼在南国，宗庙荐鲿鲨。","我为万夫长，朝论不齿牙。","刺头簿领中，蚤虱废搔爬。","世累已缠缚，官箴易疵瑕。","何时烟雨里，驱羊入金华。","遣奴迫王事，不暇学惊蛇。"]},{"t":"代书寄翠岩新禅师","f":"五言古诗","c":["山谷青石牛，自负万钧重。","八风吹得行，处处是日用。","又将十六口，去作宜州梦。","苦忆新老人，是我法梁栋。","信手斫方圆，规矩一一中。","遥思灵源叟，分坐法席共。","聊持楚狂句，往作天女供。","岭上早梅春，参军惭独弄。"]},{"t":"写真自赞五首 其四","f":"词","c":["道是鲁直亦得，道不是鲁直亦得。","是与不是，且置勿道。","唤那个作鲁直，若要斩截一句，藏头白海头黑。"]},{"t":"写真自赞五首 其一","f":"词","c":["饮不过一瓢，食不过一箪。","田夫亦不改其乐，而夫子不谓之能贤，何也。","颜渊当首出万物，而奉以四海九州。","而享之若是，故曰人不堪其忧。","若余之于山泽，鱼在深藻。","鹿得丰草，伊其野性则然。","盖非抱陆沈之屈，怀迷邦之宝。","既不能诗成无色之画，画出无声之诗。","又白首而不闻道，则奚取于似摩诘为。","若乃登山临水，喜见清扬。","岂以优孟为孙叔敖，虎贲似蔡中郎者耶。"]},{"t":"写真自赞五首 其三","f":"词","c":["或问鲁直似不似，似与不似，是何等语。","前乎鲁直，若甲若乙，不可胜纪。","后乎鲁直，若甲若乙，不可胜纪。","此一时也，则鲁直而已矣。","一以我为牛，予因以渡河而彻源底。","一以我为马，予因以日千里计。","鲁直之在万化，何翅太仓之一稊米。","吏能不如赵张三王，文章不如司马班扬。","颀颀以富贵酖毒，而酖毒不能入其城府。","投之以世故豺虎，而豺虎无所措其爪角。","则于数子，有一日之长。"]},{"t":"写真自赞五首 其二","f":"词","c":["吏能精密，里行姻恤。","则不如兄元明，而无元明忧疑万事之敝。","斟酌世故，铨品人物。","则不如其弟知命，而无知命强项好胜之累。","盖元明以寡过，而知命以傲世。","如鲁直者，欲寡过而未能，以傲世则不敢。","自江南乘一虚舟，又安知乘流之与遇坎者哉。"]},{"t":"出城送客过故人东平侯赵景珍墓","f":"七言律诗","c":["朱颜苦留不肯住，白发正尔欺得人。","婵娟去作谁家妾，意气都成一聚尘。","今日牛羊上丘垄，当时近前左右嗔。","花开鸟啼荆棘里，谁与平章作好春。"]},{"t":"发白沙口次长芦","f":"五言古诗","c":["篙师救首尾，我为制中权。","挂席满风力，如椎强弩弦。","晓放白沙口，长芦见炊烟。","一叶托秋雨，沧江百尺船。","反观世风波，谁能保长年。","念昔声利区，与世阙周旋。","大道甚閒暇，百物不废捐。","谁知目力净，改观旧山川。"]},{"t":"发舒州向皖口道中作寄李德叟","f":"五言古诗","c":["黑云平屋檐，晨夜隔星月。","晓装商旅前，冰底泥活活。","野人攘畔耕，蹇马不能滑。","驼裘惜蒙茸，俱落水塘缺。","孤材小蜗舍，乞火乾履袜。","前登极峥嵘，他日飞鸟没。","寒花委乱草，耐冻鸣风叶。","江形篆平沙，分派回劲笔。","髯弟不俱来，得句漫剞劂。","却望同安城，惟有松郁郁。","遥知浦口晴，诸峰见明雪。"]},{"t":"发赣上寄余洪范","f":"七言律诗","c":["二川来集南康郡，气味相似相和流。","木落山明数归雁，郁孤栏楯绕深秋。","胸中淳于吞一石，尘下庖丁解十牛。","他日欲言人不解，西风散发棹扁舟。"]},{"t":"古风寄周元翁","f":"词","c":["周元翁，古人风。","诗书苦，作字工。","允有德，自琢砻。","观古人，怨慧聪。","眼欲盲，耳欲聋。","黄落后，期君同。"]},{"t":"古乐府白纻四时歌 其三","f":"七言律诗","c":["络纬惊秋鸣唧唧，美人停灯中夜织。","回文中有白头吟，人生难得相知心。","少年志愿不成就，故年主人且恩旧。","及河之清八月来，斗酒聊为社公寿。"]},{"t":"古乐府白纻四时歌 其二","f":"七言律诗","c":["日晴桑叶绿宛宛，春蚕忽忽都成茧。","缲车宛转头绪多，相思如此心乱何。","少年志愿不成就，故年主人且恩旧。","及河之清八月来，斗酒聊为社公寿。"]},{"t":"古乐府白纻四时歌 其一","f":"七言律诗","c":["桃李欲开风雨多，笼弦束管奈春何。","风休雨静花满地，时节去我如惊波。","少年志愿不成就，日月星辰役昏昼。","俟河之清未有期，斗酒聊为社公寿。"]},{"t":"古乐府白纻四时歌 其四","f":"七言律诗","c":["北风降霜松柏彫，天形惨澹光景销。","山河夜半失故处，何地藏舟无动摇。","少年志愿不成就，故年主人且恩旧。","及河之清八月来，斗酒聊为社公寿。"]},{"t":"吉老许惠李北海石室碑以诗促之","f":"词","c":["往时李北海，翰墨妙天下。","石室苍苔世未知，公独得本今无价。","肉字不肥藏兔锋，郎官壁刊佳处同。","愿公倒箧速持赠，免断银钩输蠹虫。"]},{"t":"古诗二首上苏子瞻 其一","f":"五言古诗","c":["江梅有佳实，托根桃李场。","桃李终不言，朝露借恩光。","孤芳忌皎洁，冰雪空自香。","古来和鼎实，此物升庙廊。","岁月坐成晚，烟雨青已黄。","得升桃李盘，以远初见尝。","终然不可口，掷置官道傍。","但使本根在，弃捐果何伤。"]},{"t":"古诗二首上苏子瞻 其二","f":"五言古诗","c":["青松出涧壑，十里闻风声。","上有百尺丝，下有千岁苓。","自性得久要，为人制颓龄。","小草有远志，相依在平生。","医和不并世，深根且固蒂。","人言可医国，可用太早计。","小大材则殊，气味固相似。"]},{"t":"古意赠郑彦能八音歌","f":"五言古诗","c":["金欲百鍊刚，不欲绕指柔。","石羊卧荒草，一世如蜉蝣。","丝成蚕自缚，智成龟自囚。","竹箭天与美，岂愿作嚆矢。","匏枯中笙竽，不用系墙隅。","土偶与木偶，未用相贤愚。","革辙要合道，覆车还不好。","木讷赤子心，百巧令人老。"]},{"t":"古豪侠行赠魏邻几","f":"五言古诗","c":["翩翩魏公子，恐是信陵君。","高义动衰俗，孤标对层云。","风吹棠棣花，一枝落夷门。","俯仰少颜色，萧萧烟景昏。","已朽朱亥骨，侯嬴无子孙。","众中气轩昂，把臂输肺肝。","沃之红鹦鹉，载以乌贺兰。","门前马嘶急，我弟忽扣关。","谓言空中落，逆旅有仁人。","老母一解颜，万金难报恩。","琅玕乃未赠，交好如弟昆。"]},{"t":"史应之赞","f":"词","c":["眉山史应之，爱酒而滑稽。","对鄙不肖，醉眼一笑。","司马德操，万事但好。","东方戏嘲，惊动汉朝。","穷则德操，达则方朔。","天地一壶，不胶者卓。","应之老矣，似愚不愚。","江安食不足，江阳酒有馀。"]},{"t":"四月丁卯对雨寄赵正夫","f":"五言古诗","c":["公家常匆务，退食用寝讹。","相思虽劳勤，书问不能多。","时雨光万物，开云见羲和。","乾坤有美意，畎浍未盈科。","凯风吹南荣，官槐绿婆娑。","鷾鸸将其匹，来巢自成家。","于物无讥嫌，人亦不谁何。","眷言生理拙，无地牧鸡鹅。","丈人春秋高，雏鷇勤摩挲。","在公每怀归，安得借明驼。","畏涂失无乡，酌海持一蠡。","平生朱丝绳，寂寞长生窠。","故人累累去，宰木上女萝。","生存半白首，会面阻山河。","赵侯秉金玉，不与世同波。","从容觉差晚，鄙心寄琢磨。","外物良难必，岁寒不改柯。"]},{"t":"四月戊申赋盐万岁山中仰怀外舅谢师厚","f":"五言古诗","c":["只今汉庞公，白发佐州郡。","穷通视寒暑，仕已谁喜愠。","长松卧涧底，桴霤多裂璺。","未须论才难，世人无此韵。","禅悦称性深，语端入理近。","涣若开春冰，超然听年运。","临民秉三尺，朱墨不可紊。","传闻但言归，心许手自隐。","欲知南陂稻，得几就收捃。","胥疏江湖滨，不迩金玉训。","濡需且肉食，觳觫恐钟衅。","龙移山发洪，虎乳月生晕。","竹声寒夏簟，辍寝中夜听。","寄声向鹿门，傥赐劳苦问。"]},{"t":"四休居士诗三首 其三","f":"七言绝句","c":["一病能恼安乐性，四病长作一生愁。","借问四休何所好，不令一点上眉头。"]},{"t":"四休居士诗三首 其二","f":"七言绝句","c":["无求不着看人面，有酒可以留人嬉。","欲知四休安乐法，听取山谷老人诗。"]},{"t":"圣柬将寓于卫行乞食于齐有可怜之色再次韵感春五首赠之 其四","f":"五言古诗","c":["风雨桃李华，佳人来何暮。","安齐果未安，寓卫岂所寓。","张侯室县磬，得酒美无度。","常忧腐肠死，须我嫁阿骛。","双鱼传尺素，何处迷春渚。","啼鸟劝不归，晓鞍逐行旅。","遥知登楼兴，信美非吾土。"]},{"t":"圣柬将寓于卫行乞食于齐有可怜之色再次韵感春五首赠之 其一","f":"五言古诗","c":["温气冰底归，忽忽六过旬。","园林改柯叶，鸟声日日新。","耕稼百年外，四郊无短闉。","高丘试顾望，俯仰迹已陈。","信陵松郁郁，不见曩时人。","空怀负暄赏，莫望属车尘。","腹中书万卷，阽死沟壑滨。","投壶与射覆，一笑物皆春。"]},{"t":"圣柬将寓于卫行乞食于齐有可怜之色再次韵感春五首赠之 其二","f":"五言古诗","c":["种萱欲遣忧，丛薄空自绿。","洗心日三省，人亦不我谷。","谁能书窗下，草玄抱幽独。","白首官不迁，校书汉天禄。","身当万户侯，鼓吹拥部曲。","解佩著犀渠，张弓插彫服。","何时李将军，射猎出上谷。"]},{"t":"圣柬将寓于卫行乞食于齐有可怜之色再次韵感春五首赠之 其三","f":"五言古诗","c":["春风鸣布谷，天道似劝分。","持饥望路人，谁能颜色温。","笑忆枯鱼说，诙谐老漆园。","湘累不得禄，哀怨写荃荪。","千年涧谷松，惭愧雨露恩。","思为万乘器，顾掩斧凿痕。"]},{"t":"圣柬将寓于卫行乞食于齐有可怜之色再次韵感春五首赠之 其五","f":"五言古诗","c":["鲁公但食粥，百口常忧煎。","金张席贵宠，奴隶乘朱轩。","丈夫例寒饿，万世无后先。","风霾天作恶，雷亦怒阗阗。","俄顷花柳静，烟暖谷鸟喧。","人事每如此，翻覆不常然。","下流多谤议，高位又疾颠。","空馀壮士志，不逐四时迁。"]},{"t":"外舅孙莘老守苏州留诗斗野亭庚申十月庭坚和","f":"五言古诗","c":["谢公所筑埭，未叹曲池平。","苏州来赋诗，句与秋气清。","僧构擅空阔，浮光飞栋甍。","维斗天司南，其下百渎倾。","贝宫产明月，含泽遍诸生。","槃礴淮海间，风烟侵十城。","籁箫吹木末，浪波沸庖烹。","我来杪摇落，霜清见鱼行。","白鸥远飞来，得我若眼明。","佳人归何时，解衣绕厢荣。"]},{"t":"失紫竹柱杖颂","f":"词","c":["袁门西关失却柱杖，木平万载县里拾得。","恰似郑州却出曹门，何处待此左科禅客。"]},{"t":"对酒次前韵寄怀元翁","f":"五言古诗","c":["花光渐寒食，木燧催国火。","沽酒鸟劝人，怀贤吾忘我。","事往堕甑休，心知求田可。","可人不在眼，樽俎思促坐。","有生常倥偬，无暇天所课。","不解闻健饮，俄成一蓬颗。","泥钧埏万物，寒暑勤五佐。","岂其怀爱憎，私使我穷饿。","醉招魂不来，浪下巫阳些。","梦成少年嬉，走马章台左。"]},{"t":"对酒歌答谢公静","f":"词","c":["我为北海饮，君作东武吟。","看君平生用意处，萧洒定自知人心。","南阳城边雪三日，愁阴不能分皂白。","摧轮踠蹄泥数尺，城门昼开眠贾客。","移人僵尸在旦夕，谁能忍饥待食麦。","身忧天下自有人，寒士何者愁填臆。","民生正自不愿材，可乘以车可鞭策。","君不见海南水沈紫栴檀，碎身百鍊金博山。","岂如不蒙斧斤赏，老大绝崖霜雪间。","投身有用祸所集，何况四达之衢井先汲。","昨日青童天上回，手捧玉帝除书来。","一番通籍清都阙，百身书名赤城台。","飞升度世无虚日，怪我短褐趋尘埃。","顾谓彼童子，此何预人事。","但对清樽即眼开，一杯引人著胜地。","传闻官酒亦自清，径须沽取续吾瓶。","南山朝来似有意，今夜傥放春月明。"]},{"t":"平阴张澄居士隐处三诗 其一 仁亭","f":"五言古诗","c":["无心经世网，有道藏丘山。","养生息天黥，艺木印岁寒。","德人墙九仞，强学窥一斑。","张侯大雅质，结发闯儒关。","奇赢或谐偶，老大尝艰难。","筑亭上云雨，日月转朱栏。","床敷听万籁，我家颇宽閒。","牧牛有坦途，亡羊自多端。","市声鏖午枕，常以此心观。"]},{"t":"平阴张澄居士隐处三诗 其三 亨泉","f":"五言律诗","c":["水德通万物，发源会时亨。","伏坎非心愿，成川且意行。","栖迟林丘下，欲濯无尘缨。","杖藜逢载酒，一瓢酌馀清。"]},{"t":"平阴张澄居士隐处三诗 其二 复庵","f":"五言古诗","c":["舂粮出求仁，行李弥宇宙。","久客渺愁人，马饥仆夫瘦。","归来一丘中，万事不改旧。","禾黍锄其骄，牛羊鞭在后。","隐几天籁寒，六凿忽通透。"]},{"t":"戊午夜宿宝石寺视宝石戏题","f":"五言古诗","c":["石形卧苍牛，屃赑古松阴。","松风与溪月，相守历古今。","初无廊庙姿，又不能础砧。","呈文谢珉光，抚质愧球琳。","金马与碧鸡，光景动照临。","圯桥授书老，陈仓雊时禽。","是皆为国器，不尔事陆沉。","浮云有傥来，得名岂其心。","谅如曲辕社，长存斧斤寻。","智士贻美谥，自珍非世琛。","不材以为宝，吾与汝同音。"]},{"t":"玉芝园","f":"五言古诗","c":["春生潇湘水，风鸣涧谷泉。","过雨花漠漠，弄晴絮翩翩。","名园上朱阁，观后复观前。","借问昔居人，岑绝无炊烟。","人生须富贵，河水清且涟。","百年共如此，安用涕潺湲。","蒋侯真好事，杖屦喜接连。","车载溪中骨，推排若差肩。","厌看孔壬面，丑石反成妍。","感君劝我醉，吾亦无间然。","乱我朱碧眼，空花坠便翾。","行动须人扶，那能金石坚。","爱君雷氏琴，汤汤发朱弦。","但恨赏音人，大半随逝川。","平生有诗罪，如痼不可痊。","今当痛自改，三衅复三湔。"]},{"t":"玉京轩","f":"词","c":["苍山其下白玉京，五城十二楼，郁仪结邻常杲杲。","紫云黄雾锁玄关，雷驱不祥电挥扫。","上有千年来归之白鹤，下有万世不凋之瑶草。","野僧云卧对开轩，一钵安巢若飞鸟。","北风卷沙过夜窗，枕底鲸波撼蓬岛。","个中即是地行仙，但使心閒自难老。"]},{"t":"玉泉长老不受承天衬因作颂","f":"五言绝句","c":["达摩从西来，不受梁武衬。","却面少林墙，衣钵一万贯。"]},{"t":"玉照泉而名之","f":"五言古诗","c":["仙人持玉照，留在灊西峰。","一往不返顾，尘痕废磨砻。","想当光溢匣，云山叠万重。","有井洌寒泉，照影互相容。","得名未觉晚，学士古人风。","持节按九城，乐此水一钟。","税车束上饭，谈笑考百工。","金瓶煮山腴，茗椀不暇攻。","苏侯亦静者，疏凿济成功。","排遣尘滓行，石奁清如空。","能令水源浊，鱼虾来其中。","生子岁月多，往往隐蛟龙。","玉照不见影，盘桓蜗螺宫。","一朝揭源去，枯渎草蒙茸。"]},{"t":"玉醴颂","f":"词","c":["北郭子，竹林居。","酝玉醴，拨浮蛆。","味橘露，色鹅雏。","春盎盎，想可?。","鱼枕蕉，正阙渠。","来问字，傥借书。","扫三径，待双鱼。"]},{"t":"用明发不寐有怀二人为韵寄李秉彝德叟 其七","f":"五言律诗","c":["少时诵诗书，贯穿数万字。","迩来窥陈编，记一忘三二。","光阴如可玩，老境翻手至。","良医曾折足，说病乃真意。"]},{"t":"用明发不寐有怀二人为韵寄李秉彝德叟 其三","f":"五言律诗","c":["人生不如意，十事恒八九。","未见历下人，徒倾历城酒。","从来亲骨肉，不免相可不。","但愿崇事实，虚名等箕斗。"]},{"t":"用明发不寐有怀二人为韵寄李秉彝德叟 其四","f":"五言律诗","c":["蚤知鹊山亭，李杜发佳思。","弥年听传誇，登览通梦寐。","遥怜坐清旷，落笔富新制。","尚因宾客集，沥酒使我醉。"]},{"t":"用明发不寐有怀二人为韵寄李秉彝德叟 其六","f":"五言律诗","c":["安诗无恙时，学行超辈侪。","华屋落丘山，百忧满人怀。","此士如不亡，仲子抱奇材。","不独典刑在，神明还观来。"]},{"t":"用明发不寐有怀二人为韵寄李秉彝德叟 其二","f":"五言律诗","c":["在昔授子书，髧彼垂两发。","乖离今十年，树立映先达。","青灯哦妙句，如酌春酒滑。","把书念携手，惆怅至明发。"]},{"t":"用前韵谢子舟为予作风雨竹","f":"五言古诗","c":["子舟诗书客，画手睨前辈。","挹袂拍其肩，馀力左右逮。","摩拂造化炉，经营鬼神会。","光煤叠乱叶，世与作者背。","看君回腕笔，犹喜汉仪在。","岁寒十三本，与可可追配。","小山苍苔面，突兀谢憎爱。","风斜兼雨重，意出笔墨外。","吾闻绝一源，战胜自十倍。","荣枯转时机，生死付交态。","狙公倒七芧，勿用嗔喜对。","此物当更工，请以小喻大。"]},{"t":"记梦","f":"七言古诗","c":["众真绝妙拥灵君，晓然梦之非纷纭。","窗中远山是眉黛，席上榴花皆舞裙。","借问琵琶得闻否，灵君色庄妓摇手。","两客争棋烂斧柯，一儿坏局君不呵。","杏梁归燕语空多，奈此云窗雾阁何。"]},{"t":"龙眠操三章赠李元中 其一","f":"楚辞体","c":["吾其行乎，道渺渺兮骖弱，石岩岩兮川横。","日月兮在上，风吹雨兮昼冥。","吾其止乎，曲者如几，直者如矢。","我为直兮棘余趾，我为曲兮不如其已。","吾耕石田兮为芝，乃三岁兮报我饥。","嗣兹穑兮则以稼，从子于耜兮龙眠之下。"]},{"t":"龙眠操三章赠李元中 其三","f":"楚辞体","c":["朝百牢兮九饭，藜羹不糁兮共槃而笑。","狐白裘兮豹袪，缊袍无里兮亦见春。","予何喜兮安乐此，曰有嘉人兮遗予履。","发十袭兮示予，与予武兮合度。","使羿兮隅立，使离朱兮诏之。","若人兮无鹄，离朱茫然兮羿韔弓。","牧牛兮于鼻，牧羊兮不歧。","有若人兮可与归，因子问涂兮龙眠之蹊。"]},{"t":"龙眠操三章赠李元中 其二","f":"楚辞体","c":["螳臂美兮当车，蟹螯强兮斗虎。","我观兮上下四方，或锡予兮以大武。","金石兮水波，松柏兮雨霜。","有时女兮不春，我欲筮兮同床。","筮告予以不好，予与居兮甚妩。","秦人同炙兮徒欺予，予和羹兮众吐之。","南山雾兮楚氛，其在兹兮斗日月。","扬汤兮救暍，从子休兮龙眠之樾。"]},{"t":"乔令真赞","f":"词","c":["抱璞而居，其谁别玉。","乔君不献，自尊两足。","窥其狱户，视其邑庭。","吏无重糈，民有颂声。","提平如砥，持廉如水。","观其中，公清有馀。","相其貌，固凡人耳。"]},{"t":"仰山简和尚真赞","f":"词","c":["不戒而六和恭敬，不禅而十方清净。","不学而文理井井，不吏而施于有政。","寿八十馀，阅人三世。","孝于塔庙，勤力勤礼。","百室崇成，檀者亹亹。","齐始如终，薪穷于指。","耋老而精明，丰肉而神清。","和同而不浊，退屈而不陵。","是谓大雅之士，惜乎其不发诸朝廷。"]},{"t":"伏仙岩颂","f":"七言绝句","c":["生死浪中涅槃宅，与人同黑非同白。","谁令避世作聋盲，独来寒岩伏石壁。"]},{"t":"众人观俳优","f":"五言古诗","c":["众人观俳优，诚有可笑时。","侏儒笑人后，所笑动未知。","非桀是尧舜，诸生同一词。","不能解其会，何笑侏儒为。","桓公方读书，轮扁释斧凿。","借问作书人，已归蒿里宅。","至精固不传，所说乃糟粕。","使道如怀珍，分我赡人贫。","人将遗朋友，谁不献君亲。","喁喁来噍食，泯泯去游魂。","昭穆才弟兄，愚智已子孙。","愚游智者笼，智受万物役。","奔奔相后先，成则自为德。","劳神不知疲，求所不能知。","深心著文字，有如鸟粘黐。","败新为故裤，何独郑人妻。","鹄卵待啄抱，自怜非荆鸡。","谁能起千载，化此故纸痴。"]},{"t":"会稽竹箭为蕲春傅尉作","f":"七言古诗","c":["会稽竹箭天下闻，青岭霜笴摇紫云。","金作仆姑如鸟翼，壮士持用横三军。","迩来场师无远虑，剪伐柔萌荐菹茹。","人閒禦武急难才，不得生民饱霜露。","嘉瓜美果无他长，取升俎豆献壶觞。","奈何生与此等伍，大器小用良可伤。","吾闻先王用人力，不足有馀无损益。","硕人俣俣舞公庭，长咏国风三叹息。"]},{"t":"伤歌行四首 其四","f":"七言律诗","c":["伯夷不食周武粟，程婴可托赵氏孤。","死者复生欲无愧，受遗归妹况在予。","经营百事失本意，跬步寻常畏简书。","人閒若有不税地，判尽筋力终年锄。"]},{"t":"伤歌行四首 其三","f":"七言律诗","c":["诸妹欲归囊褚单，值我薄宦多艰难。","为吏受赇恐得罪，啜菽饮水终无欢。","永怀遂休一夜梦，谁与少缓百忧端。","古人择婿求过寡，取妇岂为谋饥寒。"]},{"t":"伤歌行四首 其二","f":"七言律诗","c":["孟氏至诚通竹笋，姜诗纯孝感渊鱼。","古人常欲养志意，君子不唯全发肤。","有妹言归奉箕帚，仰谁出力助葭莩。","等閒亲鬓贫中白，自悔从来色养疏。"]},{"t":"伤歌行四首 其一","f":"七言律诗","c":["草木摇落天沉阴，蟋蟀为我商声吟。","高明从来畏鬼瞰，贫贱不能全孝心。","蚤知义利有轻重，积羽何翅一钩金。","莫悲归妹无锦绣，但愿教儿和瑟琴。"]},{"t":"全州双松堂","f":"五言古诗","c":["文殊堂下松，永日如鸣琴。","我登双松堂，时步双松阴。","中有寂莫人，安禅无古今。"]},{"t":"再用旧韵寄孔毅甫","f":"词","c":["鉴中之发蒲柳望秋衰，眼中之人风雨俱星散。","往者托体同青山，健者漂零不相见。","庾公楼上有诗人，平生落笔泻河汉。","置驿勤来索我诗，自说中郎识元叹。","我方冻坐酒官曹，为公然薪炙冰砚。","不解穷愁著一书，岂有文章名九县。","奴星结柳送文穷，退倚北窗睡松风。","太阿耿耿截归鸿，夜思龙泉号匣中。","斗柄垂天霜雨空，独雁叫群云万重。","何时握手香炉峰，下看寒泉濯卧龙。"]},{"t":"再用前韵咏子舟所作竹","f":"五言古诗","c":["森梢一山竹，壮士十三辈。","自干云天去，草芥肯下逮。","虚心听造物，颠沛风云会。","荣枯偶同时，终不相弃背。","谁云湖州没，笔力今尚在。","阿筌虽墨妙，好以桃李配。","国工裁主意，冷淡恐不爱。","子舟落心画，荣观不在外。","耆年道机熟，增胜当倍倍。","祖述今百家，小纸弄姿态。","虽云出湖州，卷置懒开对。","非公笔如椽，孰能为之大。"]},{"t":"再次孔四韵寄怀元翁兄弟并致问毅甫","f":"五言古诗","c":["书帙蠹鱼乾，炉香眠鸭困。","佳人来无期，诗句且排闷。","遥知乌衣游，棋局具肴酝。","争道嘲不恭，鏖兵劳得俊。","颇寻文献盟，不落市井吝。","四月明朱夏，南风解人愠。","风前怀二陆，家法窥抗逊。","身有三尺桐，爨下得馀烬。","端可张洞庭，寥阔世未信。","为我谢孔君，举酒取快尽。","世故安足存，青天飞鸟印。"]},{"t":"再次前韵 其二","f":"七言绝句","c":["久狎渔樵作往还，晓风宫殿梦催班。","邻娃似与春争道，酥滴花枝綵剪幡。"]}]};